INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C1','kor',3,2,'u1',2,'경험을 떠올리는 틀 — 글을 읽고 떠오른 일을 언제·어디에서·무엇을·누구와, 본 것과 들은 것, 그때 든 마음으로 또렷하게 떠올리기(정확한 시각·물건값 같은 것은 필요 없음)',ARRAY['[4국05-02][4국05-05]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C2','kor',3,2,'u1',2,'마음이 이어지는 경험 — 작품과 똑같은 일을 겪지 않았어도 그때 든 생각이나 느낌이 이어지면 알맞게 떠올린 경험이고, 창문·국·휴지처럼 겉에 나온 물건이나 사건이 같다고 이어지는 것이 아님',ARRAY['[4국05-02][4국05-05]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C3','kor',3,2,'u1',2,'시의 내용과 말하는 이의 마음 — 시에서 말하는 이가 겪는 일을 알고, 마음은 시에 그대로 적혀 있지 않으므로 시에 나온 말과 행동(닦아도 또 썼다 · 지우개를 굴렸다)을 근거로 짐작하기',ARRAY['[4국05-02][4국05-05]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C4','kor',3,2,'u1',2,'인상 깊은 부분 견주기와 시 바꾸어 쓰기 — 마음에 남는 줄은 겪은 일과 생각에 따라 사람마다 달라 정답이 없고, 친구와 다를 때는 까닭을 물어 견주며, 시의 한 줄을 내 경험으로 바꿀 때는 뒤에 오는 줄과 이어지게 바꾸기',ARRAY['[4국05-02][4국05-05]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C5','kor',3,2,'u1',4,'이야기의 내용과 낱말 — 「나중에 온 아이」에서 인물이 겪은 일과 까닭을 글에서 찾고, 낱말의 뜻(선뜻 · 기웃거리다 · 멋쩍다)을 그 낱말이 나온 앞뒤 줄로 알기',ARRAY['[4국05-02][4국05-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C6','kor',3,2,'u1',4,'근거 있는 짐작 — 인물의 마음 짐작은 사람마다 달라도 되지만, 이야기에 나온 상황·말·행동에서 근거를 댈 수 있어야 하고, 글에 없는 것(원래 청소를 좋아한다 등)을 지어내지 않기; 말이 없는 인물은 행동으로 짐작하기',ARRAY['[4국05-02][4국05-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C7','kor',3,2,'u1',4,'인물의 마음과 내 경험 잇기, 하고 싶은 말 — 인물이 겪은 일과 마음을 찾아 그 마음과 이어지는 내 경험을 떠올리고(국·휴지 같은 겉 사건이 아니라 망설이던 마음), 인물에게 하고 싶은 말은 가르치는 말이나 인물 탓이 아니라 인물이 한 말·행동을 짚어 마음을 알아주는 말로 하며, 이야기를 권할 때는 그 친구의 어떤 일과 이어질지 까닭을 대기',ARRAY['[4국05-02][4국05-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C8','kor',3,2,'u1',6,'간추리며 듣는 세 걸음 — 듣기 전(무엇을 알려고 듣는지 정하기·제목으로 예상하기·아는 것 떠올리기) → 듣는 중(첫째·둘째·이것은·따라서·가장 중요한 것은 같은 말에 귀를 세우고 간단히 적기) → 들은 후(번호·화살표 같은 기호로 나누어 정리하고 궁금한 것 적기)',ARRAY['[4국01-03]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C9','kor',3,2,'u1',6,'질문과 대답으로 간추리기 — 묻고 답하는 말을 들을 때 질문과 대답을 짝지어 적으면 그 표가 곧 간추린 것이 되고, 들은 말을 하나도 빠뜨리지 않고 받아 적는 것은 간추리기가 아님',ARRAY['[4국01-03]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C10','kor',3,2,'u1',7,'이야기를 간추리는 방법 — 인물의 특성·일이 일어난 차례·원인과 결과를 잡아 이야기의 뼈대를 남기고, 본문을 그대로 옮기거나 재미있던 부분만 남기지 않기(재미있는 것 ≠ 중요한 것), 간추린 것이 한 편으로 읽히는지 살피기',ARRAY['[4국01-03]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C11','kor',3,2,'u1',9,'목적에 맞게 간추려 글로 정리하기 — 듣기 전에 무엇을 하려고 듣는지 정하고, 있는 곳·자랑거리·좋은 점 같은 칸으로 나누어 빠진 것을 찾으며, 목적이 다르면 남길 것도 달라 간추리기에는 하나의 정답이 없으니 서로 다를 때는 목적부터 물어보기',ARRAY['[4국01-03]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C12','kor',3,2,'u1',11,'배운 내용 실천하기 — 내 경험에 어울리는 이야기는 유명하거나 긴 것이 아니라 겪은 일이나 마음이 이어지는 것으로 고르고, 안내를 듣고 표지어 뒤의 중요한 것만 간추려 내가 할 수 있는 한 가지를 언제·무엇을이 드러나게 다짐하기',ARRAY['[4국01-03]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C13','kor',3,2,'u1',11,'받침 ㅎ이 소리 나지 않는 경우 — 받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ 소리가 나지 않고(빻아[빠아] · 찧어[찌어]) 자음이 오면 그렇지 않으며(빻고 · 찧다), 소리만 사라질 뿐 쓸 때는 받침 ㅎ을 그대로 쓰기(기초 다지기)',ARRAY['4국04 문법(초안)']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K3-2-u1-C14','kor',3,2,'u1',11,'낱말을 묶는 이름 — 여러 낱말을 한 이름으로 묶을 수 있고(피리·북·장구 → 악기), 묶어 두면 새 낱말을 만나도 어디에 담을지 알 수 있음(기초 다지기)',ARRAY['4국04 문법(초안)']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X01','kor',3,'u1',ARRAY['K3-2-u1-C1']::text[],'경험을 떠올릴 때 언제·어디에서·누구와를 빠뜨리거나, 정확한 시각·물건값처럼 필요 없는 것을 떠올린다','남에게 말해 준다면 무엇부터? — 언제·어디·무엇·누구·본 것·마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X02','kor',3,'u1',ARRAY['K3-2-u1-C2','K3-2-u1-C7','K3-2-u1-C12']::text[],'작품과 똑같은 일을 겪었거나 겉에 나온 물건·사건이 같아야 이어지는 경험이라고 여긴다','같은 일이 아니라 같은 마음을 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X03','kor',3,'u1',ARRAY['K3-2-u1-C2']::text[],'작품과 상관없이 아무 일이나 떠올려도 된다고 여긴다','그때 든 마음이 작품과 이어지는가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X04','kor',3,'u1',ARRAY['K3-2-u1-C3','K3-2-u1-C6']::text[],'마음을 짐작할 때 글에 나온 말·행동이 아니라 지금 내 기분·제목·글에 없는 사실을 근거로 댄다','그렇게 짐작한 까닭을 글에서 한 줄 찾아 댈 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X05','kor',3,'u1',ARRAY['K3-2-u1-C4','K3-2-u1-C7']::text[],'인상 깊은 부분에 정답이 있다고 여겨 내 것이 맞다고 우기거나 내 생각을 지우고 친구와 똑같이 고른다','다르면 까닭을 물어보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X06','kor',3,'u1',ARRAY['K3-2-u1-C4']::text[],'시의 한 줄을 바꿀 때 뒤에 오는 줄과 이어지지 않게 바꾼다','바꾼 행동을 하면 친구가 어떻게 될까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X07','kor',3,'u1',ARRAY['K3-2-u1-C3','K3-2-u1-C5','K3-2-u1-C10']::text[],'작품에서 인물(말하는 이)이 겪은 일이나 그렇게 한 까닭을 잘못 읽는다','그 일이 적힌 줄을 다시 찾아 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X08','kor',3,'u1',ARRAY['K3-2-u1-C5']::text[],'낱말의 뜻을 앞뒤 줄을 보지 않고 짐작해 다른 낱말의 뜻과 섞는다','그 낱말이 나온 줄을 앞뒤까지 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X09','kor',3,'u1',ARRAY['K3-2-u1-C7']::text[],'인물에게 하고 싶은 말을 가르치는 말(훈계)이나 인물 탓으로 한다','인물이 한 말·행동을 짚어 마음을 알아주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X10','kor',3,'u1',ARRAY['K3-2-u1-C8','K3-2-u1-C11']::text[],'듣기 전에 무엇을 알려고 듣는지 정하지 않거나, 들을 내용을 미리 다 적어 두려 한다','듣기 전 — 목적 · 제목으로 예상 · 아는 것 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X11','kor',3,'u1',ARRAY['K3-2-u1-C8','K3-2-u1-C12']::text[],'첫째·따라서·가장 중요한 것은 같은 말을 놓치거나, 「음, 그러니까」 같은 군말을 중요한 말로 여긴다','그 말 뒤에 꼭 중요한 내용이 따라오나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X12','kor',3,'u1',ARRAY['K3-2-u1-C9','K3-2-u1-C10','K3-2-u1-C11']::text[],'들은 말이나 본문을 하나도 빠뜨리지 않고 그대로 옮겨 적는 것을 간추리기로 여긴다','간추리기는 줄이기가 아니라 다시 정리하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X13','kor',3,'u1',ARRAY['K3-2-u1-C10','K3-2-u1-C12']::text[],'재미있던 부분이나 말투·장면처럼 눈에 띄는 것을 중요한 내용으로 여긴다','그 일을 빼면 이야기(안내)가 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X14','kor',3,'u1',ARRAY['K3-2-u1-C10']::text[],'이야기를 간추릴 때 일이 일어난 차례를 뒤바꾸거나 왜 그랬는지(원인)를 빠뜨린다','「왜 그랬지?」「그래서?」가 남아 있나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X15','kor',3,'u1',ARRAY['K3-2-u1-C10']::text[],'원인과 결과의 짝을 엇갈리게 잇는다','그 일을 한 다음에 무엇이 돌아왔나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X16','kor',3,'u1',ARRAY['K3-2-u1-C11']::text[],'간추린 것이 서로 다르면 하나가 틀렸다거나 더 많이 적은 쪽이 잘 간추린 것이라고 여긴다','무엇을 하려고 간추렸는지부터 묻기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X17','kor',3,'u1',ARRAY['K3-2-u1-C11','K3-2-u1-C9']::text[],'간추리는 목적과 남길 것을 엇갈리게 짝짓거나 칸(있는 곳·자랑거리·좋은 점)에 맞지 않게 넣는다','그 글을 읽는 사람이 무엇을 할 수 있어야 하나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X18','kor',3,'u1',ARRAY['K3-2-u1-C12']::text[],'내 경험에 어울리는 이야기를 가장 유명하거나 가장 긴 이야기로 고른다','내 마음과 이어지는 이야기인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X19','kor',3,'u1',ARRAY['K3-2-u1-C12']::text[],'실천 다짐을 「모두 잘하겠다」처럼 막연하게 쓰거나 남이 지켜야 할 것을 바라는 말로 쓴다','내가 · 언제 · 무엇을 할지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X20','kor',3,'u1',ARRAY['K3-2-u1-C13']::text[],'받침 ㅎ을 모음 앞에서도 소리 내거나, 자음 앞에서도 ㅎ 소리가 사라진다고 여긴다','받침 ㅎ 바로 뒤가 모음인가 자음인가') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X21','kor',3,'u1',ARRAY['K3-2-u1-C13']::text[],'소리 나는 대로 받침 ㅎ을 빼고 적는다','소리는 [빠아], 글자는 빻아') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K3-2-u1-X22','kor',3,'u1',ARRAY['K3-2-u1-C14']::text[],'낱말을 묶는 이름과 그 아래 낱말을 엇갈리게 묶거나 묶는 이름을 아래 낱말로 여긴다','셋을 한마디로 부르면?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#1','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C1',1,'mc','auto','경험을 또렷하게 떠올릴 때 함께 떠올리면 좋은 것은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":1,"kind":"mc","stem":"경험을 또렷하게 떠올릴 때 함께 떠올리면 좋은 것은 무엇인가요?","options":[{"t":"누구와 있었는지","correct":true},{"t":"그날의 정확한 시각","mis":"K3-2-u1-X01"},{"t":"그때 입은 옷의 값","mis":"K3-2-u1-X01"},{"t":"그날 먹은 반찬의 개수","mis":"K3-2-u1-X01"}],"explanation":["그때의 일을 남에게 말해 준다고 생각해요.","언제·어디에서·무엇을·누구와가 먼저예요.","본 것과 들은 것, 그때 든 마음도 함께 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#2','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C2',1,'ox','auto','작품과 똑같은 일을 겪은 적이 없으면 경험을 떠올릴 수 없어요.',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":2,"concept":"K3-2-u1-C2","difficulty":1,"kind":"ox","stem":"작품과 똑같은 일을 겪은 적이 없으면 경험을 떠올릴 수 없어요.","answer":"X","reason_options":[{"t":"겪은 일이 달라도 그때 든 생각이나 느낌이 이어지면 되기 때문에","correct":true},{"t":"작품과 같은 일을 겪어야만 이어지기 때문에","mis":"K3-2-u1-X02"}],"mis":"K3-2-u1-X02","explanation":["수린·도빈·찬유가 떠올린 일은 서로 달랐어요.","그래도 모두 알맞게 떠올렸어요.","마음이 이어지면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#3','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',1,'mc','auto','「김 서린 창문」에서 말하는 이가 겪고 있는 일은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「김 서린 창문」에서 말하는 이가 겪고 있는 일은 무엇인가요?","options":[{"t":"곁에 없는 친구를 떠올리고 있다","correct":true},{"t":"창문을 깨끗하게 닦고 있다","mis":"K3-2-u1-X07"},{"t":"글씨 쓰기를 연습하고 있다","mis":"K3-2-u1-X07"},{"t":"친구와 함께 창문에 그림을 그리고 있다","mis":"K3-2-u1-X07"}],"explanation":["「네 이름」이라고 했어요.","그 친구는 지금 곁에 없어요.","보고 싶어서 이름을 쓰고 있어요."],"asset":{"type":"passage","lines":["겨울 아침 교실 창문 하얗게 김이 서렸다","손가락으로 네 이름을 썼다","이름이 주르륵 흘러내렸다","닦아도 또 서리는 창문에","또 한 번 네 이름을 썼다"],"title":"시 「김 서린 창문」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#4','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',1,'sa','auto','「돌아선 등」에서 말하는 이가 말 대신 굴린 물건은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u1-C3","difficulty":1,"kind":"sa","stem":"「돌아선 등」에서 말하는 이가 말 대신 굴린 물건은 무엇인가요? 세 글자로 쓰세요.","answer":["지우개"],"explanation":["네 번째 줄을 읽어요.","또르르 굴렸어요.","지우개예요."],"asset":{"type":"passage","lines":["말다툼을 하고 돌아앉았다","네 등만 보인다","말을 걸고 싶은데 목소리가 안 나온다","지우개를 굴렸다 또르르","등이 조금 돌아왔다","나는 아직 아무 말도 안 했는데"],"title":"시 「돌아선 등」"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#5','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C1',2,'mc','auto','친구가 말한 경험 「지난봄 우리 학교 운동장에서 짝과 이어달리기를 했는데 심장이 쿵쿵 뛰었어.」에서 「그때 든 마음」에 해당하는 말은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":5,"concept":"K3-2-u1-C1","difficulty":2,"kind":"mc","stem":"친구가 말한 경험 「지난봄 우리 학교 운동장에서 짝과 이어달리기를 했는데 심장이 쿵쿵 뛰었어.」에서 「그때 든 마음」에 해당하는 말은 무엇인가요?","options":[{"t":"심장이 쿵쿵 뛰었어","correct":true},{"t":"지난봄","mis":"K3-2-u1-X01"},{"t":"우리 학교 운동장에서","mis":"K3-2-u1-X01"},{"t":"짝과","mis":"K3-2-u1-X01"}],"explanation":["지난봄은 언제, 운동장은 어디예요.","짝은 누구와예요.","마음은 「심장이 쿵쿵 뛰었어」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#6','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C2',2,'mc','auto','세 친구의 경험이 모두 「운동회 전날 저녁」과 이어지는 까닭은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":6,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"세 친구의 경험이 모두 「운동회 전날 저녁」과 이어지는 까닭은 무엇인가요?","options":[{"t":"겪은 일은 달라도 다가올 날을 기다리며 떨리던 마음이 같아서","correct":true},{"t":"셋 다 운동회를 겪어서","mis":"K3-2-u1-X02"},{"t":"셋 다 밤에 있었던 일이라서","mis":"K3-2-u1-X02"},{"t":"아무 일이나 떠올려도 되어서","mis":"K3-2-u1-X03"}],"explanation":["도빈이는 학예회, 찬유는 소풍이에요.","겪은 일은 서로 달라요.","떨리고 설레던 마음이 이어져요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"나는 이어달리기 앞 순서라서 손이 떨리던 게 떠올랐어."},{"who":"도빈","text":"나는 운동회 대신 학예회 전날이 떠올랐어. 대사를 까먹을까 봐 걱정했거든."},{"who":"찬유","text":"나는 소풍 가기 전날 밤에 가방을 몇 번이나 열어 본 일이 떠올랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#7','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C3',2,'match','auto','시에 나온 행동과 짐작한 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"K3-2-u1-C3","difficulty":2,"kind":"match","stem":"시에 나온 행동과 짐작한 마음을 알맞게 이으세요.","pairs":[{"l":"닦아도 또 서리는 창문에 또 이름을 썼다","r":"친구가 몹시 보고 싶다"},{"l":"말을 걸고 싶은데 목소리가 안 나온다","r":"미안한데 말이 쉽게 나오지 않는다"},{"l":"지우개를 굴렸다","r":"말 대신 행동으로 마음을 전하고 싶다"}],"mis":"K3-2-u1-X04","explanation":["마음은 시에 그대로 적혀 있지 않아요.","행동을 근거로 짐작해요.","또 썼다 · 목소리가 안 나온다 · 굴렸다가 근거예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#8','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C4',2,'ox','auto','세 친구 가운데 인상 깊은 줄을 바르게 고른 친구는 한 명뿐이에요.',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":8,"concept":"K3-2-u1-C4","difficulty":2,"kind":"ox","stem":"세 친구 가운데 인상 깊은 줄을 바르게 고른 친구는 한 명뿐이에요.","answer":"X","reason_options":[{"t":"마음에 남는 줄은 겪은 일과 생각에 따라 달라 정답이 없기 때문에","correct":true},{"t":"인상 깊은 줄에도 하나의 정답이 있기 때문에","mis":"K3-2-u1-X05"}],"mis":"K3-2-u1-X05","explanation":["셋이 서로 다른 줄을 골랐어요.","겪은 일과 생각이 다르니까요.","여기에는 점수가 없어요."],"asset":{"type":"speech","turns":[{"who":"도빈","text":"나는 「목소리가 안 나온다」가 제일 마음에 남아."},{"who":"수린","text":"나는 「또르르」가 좋아. 소리가 들리는 것 같아."},{"who":"찬유","text":"나는 마지막 두 줄. 말 안 해도 알아준 게 신기해."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#9','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C2',2,'mc','auto','「김 서린 창문」과 이어지는 경험은 어느 것인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「김 서린 창문」과 이어지는 경험은 어느 것인가요?","options":[{"t":"멀리 이사 간 사촌이 보고 싶던 날","correct":true},{"t":"교실 창문을 닦아 본 일","mis":"K3-2-u1-X02"},{"t":"겨울에 눈사람을 만든 일","mis":"K3-2-u1-X02"},{"t":"어제 먹은 저녁 반찬","mis":"K3-2-u1-X03"}],"explanation":["창문이 나오는 일을 찾는 것이 아니에요.","보고 싶은데 못 보는 마음을 찾아요.","사촌이 보고 싶던 날이에요."],"asset":{"type":"passage","lines":["겨울 아침 교실 창문 하얗게 김이 서렸다","손가락으로 네 이름을 썼다","이름이 주르륵 흘러내렸다","닦아도 또 서리는 창문에","또 한 번 네 이름을 썼다"],"title":"시 「김 서린 창문」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_basic#10','kor',3,2,'u1','L02','g3_2_kor_u1_L02_basic','lesson_basic','K3-2-u1-C4',3,'error','auto','친구가 나와 다른 줄을 골랐을 때를 두고 친구들이 정리했어요. 잘못 정리한 친구는 누구인가요?',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":10,"concept":"K3-2-u1-C4","difficulty":3,"kind":"error","stem":"친구가 나와 다른 줄을 골랐을 때를 두고 친구들이 정리했어요. 잘못 정리한 친구는 누구인가요?","options":[{"t":"친구 나 — 「내가 고른 줄이 맞다고 알려 주면 돼.」","correct":true,"mis_target":"K3-2-u1-X05"},{"t":"친구 가 — 「왜 그 줄이 마음에 남았는지 까닭을 물어보자.」","mis":"K3-2-u1-X05"},{"t":"친구 다 — 「다른 것은 틀린 것이 아니니 내 생각도 지우지 않아.」","mis":"K3-2-u1-X05"}],"explanation":["다른 것은 틀린 것이 아니에요.","까닭을 물으면 내가 못 본 것이 보여요.","친구 나가 잘못 정리했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#1','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C1',2,'sa','auto','경험을 떠올릴 때 언제·어디에서·무엇을·누구와, 본 것과 들은 것, 그리고 「그때 든 ○○」을 함께 떠올려요. ○○에 들어갈 두 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":2,"kind":"sa","stem":"경험을 떠올릴 때 언제·어디에서·무엇을·누구와, 본 것과 들은 것, 그리고 「그때 든 ○○」을 함께 떠올려요. ○○에 들어갈 두 글자를 쓰세요.","answer":["마음"],"explanation":["그때 어떤 기분이었는지예요.","설렘·걱정 같은 것이에요.","마음이에요."],"mis":"K3-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#2','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C3',2,'mc','auto','「김 서린 창문」에서 말하는 이의 마음을 짐작할 때 근거로 삼을 것은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":2,"concept":"K3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「김 서린 창문」에서 말하는 이의 마음을 짐작할 때 근거로 삼을 것은 무엇인가요?","options":[{"t":"이름이 흘러내렸는데도 또 한 번 이름을 썼다","correct":true},{"t":"시를 읽는 지금 내 기분","mis":"K3-2-u1-X04"},{"t":"제목이 예쁘고 겨울이 나와서","mis":"K3-2-u1-X04"},{"t":"창문이 하얀색이어서","mis":"K3-2-u1-X04"}],"explanation":["시에 나온 말과 행동이 근거예요.","시에 없는 것을 대면 지어내기가 돼요.","또 한 번 썼다는 행동이 마음을 알려 줘요."],"asset":{"type":"passage","lines":["겨울 아침 교실 창문 하얗게 김이 서렸다","손가락으로 네 이름을 썼다","이름이 주르륵 흘러내렸다","닦아도 또 서리는 창문에","또 한 번 네 이름을 썼다"],"title":"시 「김 서린 창문」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#3','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C2',3,'mc','auto','「돌아선 등」과 이어지는 경험을 알맞게 떠올린 것은 어느 것인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":3,"concept":"K3-2-u1-C2","difficulty":3,"kind":"mc","stem":"「돌아선 등」과 이어지는 경험을 알맞게 떠올린 것은 어느 것인가요?","options":[{"t":"「동생과 다툰 뒤 미안했는데, 말 대신 동생이 좋아하는 과자를 슬쩍 건넸어.」","correct":true},{"t":"「나는 지우개를 새로 샀어.」","mis":"K3-2-u1-X02"},{"t":"「친구 등에 붙은 종이를 떼어 준 적이 있어.」","mis":"K3-2-u1-X02"},{"t":"「어제 운동장에서 줄넘기를 했어.」","mis":"K3-2-u1-X03"}],"explanation":["지우개·등이 나오는 일을 찾는 게 아니에요.","다툰 뒤 말 대신 행동으로 마음을 전한 일을 찾아요.","과자를 건넨 경험이 이어져요."],"asset":{"type":"passage","lines":["말다툼을 하고 돌아앉았다","네 등만 보인다","말을 걸고 싶은데 목소리가 안 나온다","지우개를 굴렸다 또르르","등이 조금 돌아왔다","나는 아직 아무 말도 안 했는데"],"title":"시 「돌아선 등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#4','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C3',3,'ox','auto','「등이 조금 돌아왔다」를 보면 친구도 마음이 조금 풀렸다고 짐작할 수 있어요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":4,"concept":"K3-2-u1-C3","difficulty":3,"kind":"ox","stem":"「등이 조금 돌아왔다」를 보면 친구도 마음이 조금 풀렸다고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"말하는 이가 아무 말도 안 했는데 친구가 몸을 돌리는 행동으로 답했기 때문에","correct":true},{"t":"시에 「마음이 풀렸다」고 그대로 적혀 있기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["시에 마음이 그대로 적혀 있지는 않아요.","등이 돌아온 것은 행동이에요.","행동을 근거로 짐작해요."],"asset":{"type":"passage","lines":["말다툼을 하고 돌아앉았다","네 등만 보인다","말을 걸고 싶은데 목소리가 안 나온다","지우개를 굴렸다 또르르","등이 조금 돌아왔다","나는 아직 아무 말도 안 했는데"],"title":"시 「돌아선 등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#5','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C4',3,'match','auto','「지우개를 굴렸다」를 바꾼 줄과 그 뒤에 올 줄을 이어지게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C4","difficulty":3,"kind":"match","stem":"「지우개를 굴렸다」를 바꾼 줄과 그 뒤에 올 줄을 이어지게 이으세요.","pairs":[{"l":"공책을 한 장 찢어 그림을 그려 밀었다","r":"종이를 슬쩍 끌어갔다"},{"l":"말없이 그 애 몫까지 우유를 가져다 놓았다","r":"우유갑에 빨대가 꽂혔다"},{"l":"그 애가 좋아하는 노래를 작게 흥얼거렸다","r":"어깨가 조금 흔들렸다"}],"mis":"K3-2-u1-X06","explanation":["바꾼 줄에 따라 뒤에 올 줄도 달라져요.","그 행동을 하면 친구가 어떻게 될까요?","종이 · 우유 · 노래에 맞는 반응을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#6','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C2',3,'error','auto','친구들의 경험을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":6,"concept":"K3-2-u1-C2","difficulty":3,"kind":"error","stem":"친구들의 경험을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「창문이 나오지 않으니 셋 다 「김 서린 창문」과 이어지지 않아.」","correct":true,"mis_target":"K3-2-u1-X02"},{"t":"친구 가 — 「셋 다 보고 싶은데 못 보는 마음이 시와 이어져.」","mis":"K3-2-u1-X02"},{"t":"친구 나 — 「겪은 일은 서로 달라도 괜찮아.」","mis":"K3-2-u1-X03"}],"explanation":["세 친구는 창문 이야기를 하지 않았어요.","그래도 보고 싶은 마음이 같아요.","친구 다가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"아율","text":"이 학교로 오기 전 학교 짝이 생각났어. 지금은 못 만나."},{"who":"규안","text":"나는 겨울 방학 동안 할머니 댁에 못 간 게 떠올랐어."},{"who":"시헌","text":"나는 친했던 친구랑 다른 반이 된 날이 떠올랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#7','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C4',3,'mc','auto','「돌아선 등」의 「지우개를 굴렸다 또르르」를 내 경험으로 바꾸어 쓸 때 지킬 것은 무엇인가요?',ARRAY['K3-2-u1-X06']::text[],false,'{"seq":7,"concept":"K3-2-u1-C4","difficulty":3,"kind":"mc","stem":"「돌아선 등」의 「지우개를 굴렸다 또르르」를 내 경험으로 바꾸어 쓸 때 지킬 것은 무엇인가요?","options":[{"t":"뒤에 「등이 조금 돌아왔다」가 오니 친구가 알아챌 수 있는 행동으로 바꾼다","correct":true},{"t":"시와 상관없이 가장 재미있는 일로 바꾼다","mis":"K3-2-u1-X06"},{"t":"「미안해!」라고 큰 소리로 외쳤다로 바꾼다","mis":"K3-2-u1-X06"},{"t":"원래 줄과 글자 수를 똑같이 맞춘다","mis":"K3-2-u1-X06"}],"explanation":["뒤에 오는 줄을 봐요.","마지막 줄은 「아무 말도 안 했는데」예요.","말 없이 친구가 알아챌 행동이어야 해요."],"asset":{"type":"passage","lines":["말다툼을 하고 돌아앉았다","네 등만 보인다","말을 걸고 싶은데 목소리가 안 나온다","지우개를 굴렸다 또르르","등이 조금 돌아왔다","나는 아직 아무 말도 안 했는데"],"title":"시 「돌아선 등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#8','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C2',4,'mc','auto','규안이는 「김 서린 창문」을 읽고 겨울 방학 동안 할머니 댁에 못 간 일을 떠올렸어요. 이 경험으로 시를 감상한 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X04']::text[],false,'{"seq":8,"concept":"K3-2-u1-C2","difficulty":4,"kind":"mc","stem":"규안이는 「김 서린 창문」을 읽고 겨울 방학 동안 할머니 댁에 못 간 일을 떠올렸어요. 이 경험으로 시를 감상한 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"할머니가 보고 싶은데 못 가서 아쉬웠던 마음이 이름을 또 쓰는 말하는 이의 마음과 같아서 시가 가깝게 느껴진다","correct":true},{"t":"할머니 댁에도 창문이 있으니 시와 똑같은 일이다","mis":"K3-2-u1-X02"},{"t":"겨울 방학은 즐거우니 이 시는 신나는 시이다","mis":"K3-2-u1-X04"},{"t":"할머니가 시에 나오지 않으니 이 경험은 시와 이어지지 않는다","mis":"K3-2-u1-X02"}],"explanation":["창문이 같은지 보지 않아요.","보고 싶은 마음이 이어지는지 봐요.","이어진 마음 덕분에 시가 가까워져요."],"asset":{"type":"speech","turns":[{"who":"아율","text":"이 학교로 오기 전 학교 짝이 생각났어. 지금은 못 만나."},{"who":"규안","text":"나는 겨울 방학 동안 할머니 댁에 못 간 게 떠올랐어."},{"who":"시헌","text":"나는 친했던 친구랑 다른 반이 된 날이 떠올랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#9','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C2',4,'essay','teacher','「김 서린 창문」을 읽고 떠오르는 내 경험 하나를 언제·어디에서·누구와가 드러나게 쓰고, 그 경험이 시와 어떤 마음으로 이어지는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":4,"kind":"essay","stem":"「김 서린 창문」을 읽고 떠오르는 내 경험 하나를 언제·어디에서·누구와가 드러나게 쓰고, 그 경험이 시와 어떤 마음으로 이어지는지 쓰세요.","answer_guide":{"answer":"예: 2학년 겨울, 우리 집에서 같은 반이던 친구가 멀리 이사를 갔다. 그 뒤로 놀이터에 가면 그 친구 생각이 났다. 보고 싶은데 만날 수 없는 마음이, 김이 서린 창문에 친구 이름을 또 쓰는 말하는 이의 마음과 이어진다.","scoring_points":["언제·어디에서·누구와가 드러나게 경험을 썼는가","시와 이어지는 마음을 밝혔는가","겉의 물건이 아니라 마음으로 이었는가"]},"explanation":["경험을 또렷하게 떠올려요.","겪은 일은 달라도 돼요.","보고 싶은 마음처럼 이어지는 마음을 써요."],"asset":{"type":"passage","lines":["겨울 아침 교실 창문 하얗게 김이 서렸다","손가락으로 네 이름을 썼다","이름이 주르륵 흘러내렸다","닦아도 또 서리는 창문에","또 한 번 네 이름을 썼다"],"title":"시 「김 서린 창문」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L02_challenge#10','kor',3,2,'u1','L02','g3_2_kor_u1_L02_challenge','lesson_challenge','K3-2-u1-C4',4,'essay','teacher','「돌아선 등」의 네 번째 줄 「지우개를 굴렸다 또르르」를 내가 마음을 풀었던 방법으로 바꾸어 쓰고, 그 뒤에 올 줄도 바꾼 줄과 이어지게 한 줄 쓰세요. 그렇게 바꾼 까닭도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C4","difficulty":4,"kind":"essay","stem":"「돌아선 등」의 네 번째 줄 「지우개를 굴렸다 또르르」를 내가 마음을 풀었던 방법으로 바꾸어 쓰고, 그 뒤에 올 줄도 바꾼 줄과 이어지게 한 줄 쓰세요. 그렇게 바꾼 까닭도 쓰세요.","answer_guide":{"answer":"예: 바꾼 줄 — 쪽지에 웃는 얼굴을 그려 밀었다. 뒤에 올 줄 — 쪽지가 슬쩍 사라졌다. 까닭 — 나는 동생과 다투었을 때 말 대신 그림 쪽지로 마음을 전했고, 말하지 않아도 친구가 알아챌 수 있는 행동이라서 마지막 줄과도 이어진다.","scoring_points":["네 번째 줄을 내 경험으로 바꾸었는가","뒤에 올 줄이 바꾼 줄과 이어지는가","말 없이 알아챌 수 있는 행동인지 까닭을 썼는가"]},"explanation":["내 경험에서 행동을 골라요.","그 행동에 친구가 어떻게 할지 써요.","마지막 줄과도 이어지는지 살펴요."],"asset":{"type":"passage","lines":["말다툼을 하고 돌아앉았다","네 등만 보인다","말을 걸고 싶은데 목소리가 안 나온다","지우개를 굴렸다 또르르","등이 조금 돌아왔다","나는 아직 아무 말도 안 했는데"],"title":"시 「돌아선 등」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#1','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'mc','auto','도빈이가 여러 날 시헌이에게 말을 걸지 못한 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"도빈이가 여러 날 시헌이에게 말을 걸지 못한 까닭은 무엇인가요?","options":[{"t":"먼저 말을 걸면 이상해 보일까 봐 걱정해서","correct":true},{"t":"시헌이가 싫어서","mis":"K3-2-u1-X07"},{"t":"쉬는 시간이 너무 짧아서","mis":"K3-2-u1-X07"},{"t":"선생님이 말을 걸지 말라고 하셔서","mis":"K3-2-u1-X07"}],"explanation":["여섯째 줄을 읽어요.","「이상해 보일까 봐」라고 했어요.","마음이 없어서가 아니라 걱정해서예요."],"asset":{"type":"passage","lines":["가을이 시작될 무렵, 우리 반에 시헌이가 왔다.","선생님께서 이름을 알려 주셨지만 아무도 말을 걸지 않았다.","시헌이는 쉬는 시간마다 창가에 앉아 밖을 봤다.","한 번은 교실 뒤쪽을 기웃거리다가 다시 창밖으로 고개를 돌렸다.","도빈이는 말을 걸고 싶었다.","그런데 먼저 말을 걸면 이상해 보일까 봐 선뜻 다가가지 못했다.","내일은 꼭 말해야지. 그렇게 하루를 미루고, 또 하루를 미뤘다."],"title":"이야기 「나중에 온 아이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#2','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'mc','auto','시헌이의 국이 쏟아졌을 때 도빈이가 한 일은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":2,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"시헌이의 국이 쏟아졌을 때 도빈이가 한 일은 무엇인가요?","options":[{"t":"휴지를 뽑아 들고 달려가 같이 바닥을 닦았다","correct":true},{"t":"다른 아이들과 함께 웃었다","mis":"K3-2-u1-X07"},{"t":"선생님께 달려가 알렸다","mis":"K3-2-u1-X07"},{"t":"모르는 척 자리에 앉았다","mis":"K3-2-u1-X07"}],"explanation":["셋째 줄을 읽어요.","저도 모르게 달려갔어요.","같이 바닥을 닦았어요."],"asset":{"type":"passage","lines":["그날 급식 줄에서 시헌이의 식판이 기울었다.","국이 바닥으로 쏟아졌고, 몇몇 아이가 웃었다.","도빈이는 저도 모르게 휴지를 뽑아 들고 달려갔다.","둘은 아무 말 없이 같이 바닥을 닦았다.","다음 날 아침, 도빈이가 먼저 물었다. “옆에 앉아도 돼?”","시헌이가 고개를 끄덕였다. 도빈이는 멋쩍게 웃었다.","그러고는 생각했다. 미룬 날들이 참 아까웠다고."],"title":"이야기 「나중에 온 아이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#3','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',1,'sa','auto','다음 날 아침 도빈이가 시헌이에게 먼저 한 말을 그대로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C5","difficulty":1,"kind":"sa","stem":"다음 날 아침 도빈이가 시헌이에게 먼저 한 말을 그대로 쓰세요.","answer":["옆에 앉아도 돼?","옆에 앉아도 돼"],"explanation":["다섯째 줄을 읽어요.","따옴표 안의 말이에요.","「옆에 앉아도 돼?」예요."],"asset":{"type":"passage","lines":["그날 급식 줄에서 시헌이의 식판이 기울었다.","국이 바닥으로 쏟아졌고, 몇몇 아이가 웃었다.","도빈이는 저도 모르게 휴지를 뽑아 들고 달려갔다.","둘은 아무 말 없이 같이 바닥을 닦았다.","다음 날 아침, 도빈이가 먼저 물었다. “옆에 앉아도 돼?”","시헌이가 고개를 끄덕였다. 도빈이는 멋쩍게 웃었다.","그러고는 생각했다. 미룬 날들이 참 아까웠다고."],"title":"이야기 「나중에 온 아이」 ②"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#4','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',1,'ox','auto','인물의 마음 짐작에는 하나의 정답만 있어요.',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":4,"concept":"K3-2-u1-C6","difficulty":1,"kind":"ox","stem":"인물의 마음 짐작에는 하나의 정답만 있어요.","answer":"X","reason_options":[{"t":"같은 장면을 읽어도 짐작하는 마음은 사람마다 달라도 되기 때문에","correct":true},{"t":"이야기에 인물의 마음이 하나로 정해져 적혀 있기 때문에","mis":"K3-2-u1-X05"}],"mis":"K3-2-u1-X05","explanation":["마음 짐작은 사람마다 달라요.","다만 근거는 이야기에서 나와야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#5','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C5',2,'match','auto','낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C5","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"기웃거리다","r":"보려고 고개를 자꾸 기울이다"},{"l":"선뜻","r":"망설이지 않고 얼른"},{"l":"멋쩍다","r":"어색하고 쑥스럽다"}],"mis":"K3-2-u1-X08","explanation":["낱말이 나온 줄을 다시 읽어요.","선뜻 다가가지 못했다 · 멋쩍게 웃었다예요.","앞뒤 줄이 뜻을 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#6','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',2,'mc','auto','이야기에서 근거를 찾을 수 있는 짐작은 어느 것인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":6,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"이야기에서 근거를 찾을 수 있는 짐작은 어느 것인가요?","options":[{"t":"도빈이는 몸이 먼저 움직일 만큼 마음이 급했을 것 같다","correct":true},{"t":"도빈이는 원래 청소를 좋아한다","mis":"K3-2-u1-X04"},{"t":"도빈이는 급식 국을 싫어한다","mis":"K3-2-u1-X04"},{"t":"도빈이는 시헌이와 예전부터 친했다","mis":"K3-2-u1-X07"}],"explanation":["「저도 모르게 … 달려갔다」를 봐요.","그래서 몸이 먼저 움직였다고 짐작할 수 있어요.","나머지는 이야기에 없는 내용이에요."],"asset":{"type":"passage","lines":["그날 급식 줄에서 시헌이의 식판이 기울었다.","국이 바닥으로 쏟아졌고, 몇몇 아이가 웃었다.","도빈이는 저도 모르게 휴지를 뽑아 들고 달려갔다.","둘은 아무 말 없이 같이 바닥을 닦았다.","다음 날 아침, 도빈이가 먼저 물었다. “옆에 앉아도 돼?”","시헌이가 고개를 끄덕였다. 도빈이는 멋쩍게 웃었다.","그러고는 생각했다. 미룬 날들이 참 아까웠다고."],"title":"이야기 「나중에 온 아이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#7','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C7',2,'mc','auto','도빈이의 마음과 이어지는 경험은 어느 것인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":7,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"도빈이의 마음과 이어지는 경험은 어느 것인가요?","options":[{"t":"말을 걸고 싶었는데 며칠을 미룬 일","correct":true},{"t":"급식에서 국을 쏟아 본 일","mis":"K3-2-u1-X02"},{"t":"휴지로 책상을 닦아 본 일","mis":"K3-2-u1-X02"},{"t":"운동장에서 공을 찬 일","mis":"K3-2-u1-X03"}],"explanation":["국이나 휴지를 찾는 것이 아니에요.","하고 싶은데 못 했던 마음을 찾아요.","미룬 일이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#8','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C7',2,'mc','auto','도빈이에게 하고 싶은 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":8,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"도빈이에게 하고 싶은 말로 알맞은 것은 무엇인가요?","options":[{"t":"“미룬 날이 아까웠다고 한 걸 보니 너도 많이 망설였구나.”","correct":true},{"t":"“다음부터는 착하게 행동해.”","mis":"K3-2-u1-X09"},{"t":"“시헌이가 먼저 말을 걸었어야지.”","mis":"K3-2-u1-X09"},{"t":"“국을 쏟은 건 시헌이 잘못이야.”","mis":"K3-2-u1-X09"}],"explanation":["가르치는 말이 아니에요.","인물이 한 말을 짚어 줘요.","마음을 알아주는 말을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#9','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',2,'mc','auto','말이 거의 없는 시헌이의 마음은 무엇을 보고 짐작하나요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":9,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"말이 거의 없는 시헌이의 마음은 무엇을 보고 짐작하나요?","options":[{"t":"쉬는 시간마다 창밖을 보고 교실 뒤쪽을 기웃거린 행동","correct":true},{"t":"시헌이의 키와 옷차림","mis":"K3-2-u1-X04"},{"t":"내가 오늘 아침에 느낀 기분","mis":"K3-2-u1-X04"},{"t":"제목에 「아이」라는 말이 들어간 것","mis":"K3-2-u1-X04"}],"explanation":["시헌이는 말이 거의 없어요.","그래서 행동을 봐요.","창밖 보기와 기웃거리기가 근거예요."],"asset":{"type":"passage","lines":["가을이 시작될 무렵, 우리 반에 시헌이가 왔다.","선생님께서 이름을 알려 주셨지만 아무도 말을 걸지 않았다.","시헌이는 쉬는 시간마다 창가에 앉아 밖을 봤다.","한 번은 교실 뒤쪽을 기웃거리다가 다시 창밖으로 고개를 돌렸다.","도빈이는 말을 걸고 싶었다.","그런데 먼저 말을 걸면 이상해 보일까 봐 선뜻 다가가지 못했다.","내일은 꼭 말해야지. 그렇게 하루를 미루고, 또 하루를 미뤘다."],"title":"이야기 「나중에 온 아이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_basic#10','kor',3,2,'u1','L04','g3_2_kor_u1_L04_basic','lesson_basic','K3-2-u1-C6',3,'error','auto','시헌이의 행동으로 마음을 짐작했어요. 근거와 맞지 않게 짐작한 친구는 누구인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":10,"concept":"K3-2-u1-C6","difficulty":3,"kind":"error","stem":"시헌이의 행동으로 마음을 짐작했어요. 근거와 맞지 않게 짐작한 친구는 누구인가요?","options":[{"t":"친구 나 — 「교실 뒤쪽을 기웃거린 걸 보니 친구들과 놀기 싫었을 거야.」","correct":true,"mis_target":"K3-2-u1-X04"},{"t":"친구 가 — 「쉬는 시간마다 창밖을 본 걸 보니 말 걸 사람이 없어 심심했을 것 같아.」","mis":"K3-2-u1-X04"},{"t":"친구 다 — 「기웃거린 걸 보니 끼고 싶은 마음이 있었을 것 같아.」","mis":"K3-2-u1-X04"}],"explanation":["기웃거리다는 보려고 고개를 자꾸 기울이는 거예요.","놀기 싫다면 기웃거리지 않겠지요.","친구 나의 짐작은 근거와 맞지 않아요."],"asset":{"type":"passage","lines":["가을이 시작될 무렵, 우리 반에 시헌이가 왔다.","선생님께서 이름을 알려 주셨지만 아무도 말을 걸지 않았다.","시헌이는 쉬는 시간마다 창가에 앉아 밖을 봤다.","한 번은 교실 뒤쪽을 기웃거리다가 다시 창밖으로 고개를 돌렸다.","도빈이는 말을 걸고 싶었다.","그런데 먼저 말을 걸면 이상해 보일까 봐 선뜻 다가가지 못했다.","내일은 꼭 말해야지. 그렇게 하루를 미루고, 또 하루를 미뤘다."],"title":"이야기 「나중에 온 아이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#1','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C5',2,'sa','auto','「나중에 온 아이」 ①에서 「망설이지 않고 얼른」이라는 뜻의 낱말을 찾아 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C5","difficulty":2,"kind":"sa","stem":"「나중에 온 아이」 ①에서 「망설이지 않고 얼른」이라는 뜻의 낱말을 찾아 두 글자로 쓰세요.","answer":["선뜻"],"explanation":["도빈이가 다가가지 못한 줄을 봐요.","「○○ 다가가지 못했다」예요.","선뜻이에요."],"asset":{"type":"passage","lines":["가을이 시작될 무렵, 우리 반에 시헌이가 왔다.","선생님께서 이름을 알려 주셨지만 아무도 말을 걸지 않았다.","시헌이는 쉬는 시간마다 창가에 앉아 밖을 봤다.","한 번은 교실 뒤쪽을 기웃거리다가 다시 창밖으로 고개를 돌렸다.","도빈이는 말을 걸고 싶었다.","그런데 먼저 말을 걸면 이상해 보일까 봐 선뜻 다가가지 못했다.","내일은 꼭 말해야지. 그렇게 하루를 미루고, 또 하루를 미뤘다."],"title":"이야기 「나중에 온 아이」 ①"},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#2','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',2,'mc','auto','「나중에 온 아이」를 친구에게 권할 때 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X18','K3-2-u1-X13','K3-2-u1-X03']::text[],false,'{"seq":2,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"「나중에 온 아이」를 친구에게 권할 때 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"새 모둠에서 말을 못 걸고 있는 친구라서, 도빈이의 망설이는 마음과 이어질 것 같다","correct":true},{"t":"이야기가 가장 짧아서","mis":"K3-2-u1-X18"},{"t":"국을 쏟는 장면이 웃겨서","mis":"K3-2-u1-X13"},{"t":"그냥 내가 읽은 이야기라서","mis":"K3-2-u1-X03"}],"explanation":["권하는 까닭에는 그 친구의 일이 들어가요.","이야기와 이어질 일을 대요.","망설이는 마음이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#3','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',3,'mc','auto','「도빈이는 멋쩍게 웃었다」에서 짐작할 수 있는 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C6","difficulty":3,"kind":"mc","stem":"「도빈이는 멋쩍게 웃었다」에서 짐작할 수 있는 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"먼저 말을 건 것이 쑥스러웠지만 시헌이가 고개를 끄덕여 기뻤다","correct":true},{"t":"시헌이가 싫어서 억지로 웃었다","mis":"K3-2-u1-X04"},{"t":"바닥 닦는 일이 재미있었다","mis":"K3-2-u1-X04"},{"t":"친구들이 웃어서 화가 났다","mis":"K3-2-u1-X07"}],"explanation":["멋쩍다는 어색하고 쑥스럽다예요.","바로 앞에서 시헌이가 고개를 끄덕였어요.","쑥스럽고 기쁜 마음을 짐작해요."],"asset":{"type":"passage","lines":["그날 급식 줄에서 시헌이의 식판이 기울었다.","국이 바닥으로 쏟아졌고, 몇몇 아이가 웃었다.","도빈이는 저도 모르게 휴지를 뽑아 들고 달려갔다.","둘은 아무 말 없이 같이 바닥을 닦았다.","다음 날 아침, 도빈이가 먼저 물었다. “옆에 앉아도 돼?”","시헌이가 고개를 끄덕였다. 도빈이는 멋쩍게 웃었다.","그러고는 생각했다. 미룬 날들이 참 아까웠다고."],"title":"이야기 「나중에 온 아이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#4','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',3,'ox','auto','「도빈이는 원래 청소를 좋아해서 바닥을 닦았을 것이다.」는 근거 있는 짐작이에요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":4,"concept":"K3-2-u1-C6","difficulty":3,"kind":"ox","stem":"「도빈이는 원래 청소를 좋아해서 바닥을 닦았을 것이다.」는 근거 있는 짐작이에요.","answer":"X","reason_options":[{"t":"이야기 어디에도 도빈이가 청소를 좋아한다는 내용이 없기 때문에","correct":true},{"t":"바닥을 닦았으니 청소를 좋아하는 것이 틀림없기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["근거는 이야기에서 찾아요.","청소를 좋아한다는 말은 없어요.","지어낸 짐작이라 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#5','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',3,'match','auto','시헌이의 행동과 짐작한 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C6","difficulty":3,"kind":"match","stem":"시헌이의 행동과 짐작한 마음을 알맞게 이으세요.","pairs":[{"l":"쉬는 시간마다 창밖을 봤다","r":"말 걸 사람이 없어 심심했을 것 같다"},{"l":"교실 뒤쪽을 기웃거렸다","r":"끼고 싶은 마음이 있었을 것 같다"},{"l":"말없이 고개를 끄덕였다","r":"기다리던 말이라 반가웠을 것 같다"}],"mis":"K3-2-u1-X04","explanation":["말이 없어도 행동이 마음을 알려 줘요.","그 행동을 한 사람이 나라면 어땠을까요?","행동마다 마음을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#6','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',3,'error','auto','인물에게 하고 싶은 말을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":6,"concept":"K3-2-u1-C7","difficulty":3,"kind":"error","stem":"인물에게 하고 싶은 말을 두고 친구들이 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「“시헌아, 넌 왜 먼저 말을 안 걸었어?”라고 따지고 싶어.」","correct":true,"mis_target":"K3-2-u1-X09"},{"t":"친구 가 — 「“시헌아, 창밖만 보던 날 많이 기다렸겠구나.”라고 말하고 싶어.」","mis":"K3-2-u1-X09"},{"t":"친구 나 — 「“도빈아, 휴지 들고 달려간 거 멋졌어.”라고 말하고 싶어.」","mis":"K3-2-u1-X09"}],"explanation":["하고 싶은 말은 마음을 알아주는 말이에요.","따지는 말은 인물 탓이에요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#7','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',3,'mc','auto','수린이의 경험은 이야기 속 누구의 마음과 가장 잘 이어지나요?',ARRAY['K3-2-u1-X07','K3-2-u1-X02']::text[],false,'{"seq":7,"concept":"K3-2-u1-C7","difficulty":3,"kind":"mc","stem":"수린이의 경험은 이야기 속 누구의 마음과 가장 잘 이어지나요?","options":[{"t":"도빈이가 먼저 말을 걸어 준 날의 시헌이","correct":true},{"t":"국이 쏟아질 때 웃은 몇몇 아이","mis":"K3-2-u1-X07"},{"t":"이름을 알려 주신 선생님","mis":"K3-2-u1-X07"},{"t":"휴지를 뽑아 든 도빈이","mis":"K3-2-u1-X02"}],"explanation":["수린이는 누가 먼저 말 걸어 줘서 마음이 놓였어요.","이야기에서 말을 들은 사람은 시헌이예요.","시헌이의 마음과 이어져요."],"asset":{"type":"speech","turns":[{"who":"아율","text":"새 모둠이 됐는데 며칠 동안 아무 말도 못 했어. 속으로만 인사했어."},{"who":"규안","text":"넘어진 아이를 일으켜 주고 싶었는데 몸이 안 움직였어. 지금도 생각나."},{"who":"수린","text":"나는 반대로, 누가 먼저 말 걸어 줘서 마음이 탁 놓였던 날이 떠올랐어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#8','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',4,'mc','auto','「미룬 날들이 참 아까웠다」는 도빈이의 생각과 이어지는 경험으로 감상한 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X09','K3-2-u1-X04']::text[],false,'{"seq":8,"concept":"K3-2-u1-C7","difficulty":4,"kind":"mc","stem":"「미룬 날들이 참 아까웠다」는 도빈이의 생각과 이어지는 경험으로 감상한 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나도 전학 온 친구에게 인사하려다 미룬 적이 있는데, 도빈이가 아까워한 마음을 보니 내일은 먼저 말을 걸어 보고 싶다","correct":true},{"t":"나도 국을 쏟은 적이 있으니 도빈이와 똑같다","mis":"K3-2-u1-X02"},{"t":"도빈이는 앞으로 착한 아이가 되어야 한다","mis":"K3-2-u1-X09"},{"t":"시헌이는 원래 말이 없는 아이라 친구가 필요 없다","mis":"K3-2-u1-X04"}],"explanation":["도빈이의 마음과 이어지는 내 경험을 찾아요.","인물을 가르치지 않아요.","나를 돌아보는 감상이 좋아요."],"asset":{"type":"passage","lines":["그날 급식 줄에서 시헌이의 식판이 기울었다.","국이 바닥으로 쏟아졌고, 몇몇 아이가 웃었다.","도빈이는 저도 모르게 휴지를 뽑아 들고 달려갔다.","둘은 아무 말 없이 같이 바닥을 닦았다.","다음 날 아침, 도빈이가 먼저 물었다. “옆에 앉아도 돼?”","시헌이가 고개를 끄덕였다. 도빈이는 멋쩍게 웃었다.","그러고는 생각했다. 미룬 날들이 참 아까웠다고."],"title":"이야기 「나중에 온 아이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#9','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C6',4,'essay','teacher','시헌이 쪽에서 이야기를 다시 읽고, 시헌이가 고개를 끄덕였을 때의 마음을 짐작해 쓰세요. 짐작의 근거가 된 이야기 속 행동이나 상황을 두 가지 함께 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C6","difficulty":4,"kind":"essay","stem":"시헌이 쪽에서 이야기를 다시 읽고, 시헌이가 고개를 끄덕였을 때의 마음을 짐작해 쓰세요. 짐작의 근거가 된 이야기 속 행동이나 상황을 두 가지 함께 쓰세요.","answer_guide":{"answer":"예: 시헌이는 기다리던 말을 들어서 반갑고 마음이 놓였을 것 같다. 쉬는 시간마다 창가에 앉아 밖을 보고 교실 뒤쪽을 기웃거린 것을 보면 친구들과 어울리고 싶었던 것 같고, 국을 쏟은 날 도빈이가 같이 바닥을 닦아 주었기 때문이다.","scoring_points":["시헌이의 마음을 짐작해 썼는가","이야기 속 행동이나 상황을 근거로 두 가지 들었는가","이야기에 없는 내용을 지어내지 않았는가"]},"explanation":["시헌이는 말이 거의 없어요.","행동과 상황을 근거로 짐작해요.","근거가 있으면 다른 짐작도 좋아요."],"asset":{"type":"passage","lines":["가을이 시작될 무렵, 우리 반에 시헌이가 왔다.","선생님께서 이름을 알려 주셨지만 아무도 말을 걸지 않았다.","시헌이는 쉬는 시간마다 창가에 앉아 밖을 봤다.","한 번은 교실 뒤쪽을 기웃거리다가 다시 창밖으로 고개를 돌렸다.","도빈이는 말을 걸고 싶었다.","그런데 먼저 말을 걸면 이상해 보일까 봐 선뜻 다가가지 못했다.","내일은 꼭 말해야지. 그렇게 하루를 미루고, 또 하루를 미뤘다."],"title":"이야기 「나중에 온 아이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L04_challenge#10','kor',3,2,'u1','L04','g3_2_kor_u1_L04_challenge','lesson_challenge','K3-2-u1-C7',4,'essay','teacher','도빈이나 시헌이 가운데 한 인물에게 하고 싶은 말을 쓰세요. 인물이 한 말이나 행동을 짚어 주고, 그 말과 이어지는 내 경험도 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"도빈이나 시헌이 가운데 한 인물에게 하고 싶은 말을 쓰세요. 인물이 한 말이나 행동을 짚어 주고, 그 말과 이어지는 내 경험도 함께 쓰세요.","answer_guide":{"answer":"예: 도빈아, 국이 쏟아졌을 때 저도 모르게 휴지를 들고 달려간 게 정말 멋졌어. 나도 새 반에서 짝에게 말을 걸까 말까 며칠을 망설였는데, 네가 「옆에 앉아도 돼?」라고 먼저 묻는 걸 보고 용기가 났어.","scoring_points":["인물에게 하고 싶은 말을 썼는가","인물이 한 말이나 행동을 짚었는가","이어지는 내 경험을 함께 썼는가"]},"explanation":["가르치거나 따지는 말이 아니에요.","인물의 말·행동을 짚어 줘요.","내 경험과 이어서 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#1','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',1,'mc','auto','듣기 전에 하는 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":1,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"듣기 전에 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"무엇을 알려고 듣는지 정하고 제목으로 내용을 예상한다","correct":true},{"t":"들을 내용을 미리 다 적어 둔다","mis":"K3-2-u1-X10"},{"t":"아무 생각도 하지 않고 가만히 기다린다","mis":"K3-2-u1-X10"},{"t":"들은 말에 번호를 붙여 정리한다","mis":"K3-2-u1-X10"}],"explanation":["듣기 전에는 아직 들은 것이 없어요.","그래도 목적을 정하고 예상할 수 있어요.","목적이 정해지면 적을 것도 정해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#2','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',1,'mc','auto','말하는 사람이 중요한 내용을 알려 줄 때 쓰는 말은 어느 것인가요?',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":2,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"말하는 사람이 중요한 내용을 알려 줄 때 쓰는 말은 어느 것인가요?","options":[{"t":"가장 중요한 것은","correct":true},{"t":"음, 그러니까","mis":"K3-2-u1-X11"},{"t":"아까 뭐였더라","mis":"K3-2-u1-X11"},{"t":"저기, 있잖아","mis":"K3-2-u1-X11"}],"explanation":["그 말 뒤에 중요한 내용이 따라와요.","첫째·둘째·따라서도 그래요.","「가장 중요한 것은」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#3','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',1,'ox','auto','들은 말을 하나도 빠뜨리지 않고 받아 적어야 잘 간추린 거예요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":3,"concept":"K3-2-u1-C9","difficulty":1,"kind":"ox","stem":"들은 말을 하나도 빠뜨리지 않고 받아 적어야 잘 간추린 거예요.","answer":"X","reason_options":[{"t":"다 받아 적으면 손이 아프고 무엇이 중요한지 남지 않기 때문에","correct":true},{"t":"하나라도 빠뜨리면 틀린 것이기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["간추리기는 줄이는 일이 아니에요.","무엇이 중요한지 생각해 다시 정리해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#4','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',1,'mc','auto','수린이가 선생님께 처음 여쭌 것은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C9","difficulty":1,"kind":"mc","stem":"수린이가 선생님께 처음 여쭌 것은 무엇인가요?","options":[{"t":"읽고 싶은 책을 어떻게 고르면 좋은지","correct":true},{"t":"도서관이 몇 시에 문을 닫는지","mis":"K3-2-u1-X07"},{"t":"책을 어디에 꽂아야 하는지","mis":"K3-2-u1-X07"},{"t":"선생님이 좋아하는 책이 무엇인지","mis":"K3-2-u1-X07"}],"explanation":["수린이의 첫 말을 읽어요.","「어떻게 고르면 좋을까요?」라고 했어요.","책 고르는 법을 여쭈었어요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#5','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',2,'match','auto','수린이의 질문과 선생님의 대답을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C9","difficulty":2,"kind":"match","stem":"수린이의 질문과 선생님의 대답을 알맞게 이으세요.","pairs":[{"l":"책을 어떻게 고를까요?","r":"앞쪽 두세 쪽을 읽어 보고 고른다"},{"l":"너무 어려우면요?","r":"끝까지 안 읽어도 되고 나중에 다시 와도 된다"},{"l":"자꾸 잊어버려요.","r":"마음에 남는 한 줄만 적어 둔다"}],"mis":"K3-2-u1-X17","explanation":["질문마다 대답을 찾아요.","첫째 · 둘째 · 이것만 기억하세요 뒤를 봐요.","짝지은 표가 곧 간추린 것이에요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#6','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',2,'mc','auto','다 듣고 나서 하는 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X10','K3-2-u1-X13']::text[],false,'{"seq":6,"concept":"K3-2-u1-C8","difficulty":2,"kind":"mc","stem":"다 듣고 나서 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"번호나 화살표 같은 기호로 나누어 정리한다","correct":true},{"t":"제목을 보고 나올 내용을 예상한다","mis":"K3-2-u1-X10"},{"t":"무엇을 알려고 들을지 정한다","mis":"K3-2-u1-X10"},{"t":"말하는 사람의 말투를 흉내 낸다","mis":"K3-2-u1-X13"}],"explanation":["예상과 목적은 듣기 전에 해요.","들은 후에는 정리해요.","기호로 나누고 궁금한 것을 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#7','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',2,'mc','auto','선생님의 말씀에서 중요한 내용을 알려 주는 말이 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":7,"concept":"K3-2-u1-C8","difficulty":2,"kind":"mc","stem":"선생님의 말씀에서 중요한 내용을 알려 주는 말이 아닌 것은 무엇인가요?","options":[{"t":"저는 3학년 수린입니다","correct":true},{"t":"첫째","mis":"K3-2-u1-X11"},{"t":"둘째","mis":"K3-2-u1-X11"},{"t":"이것만 기억하세요","mis":"K3-2-u1-X11"}],"explanation":["첫째 · 둘째 · 이것만 기억하세요 뒤에 방법이 왔어요.","수린이의 인사는 표지어가 아니에요.","「저는 3학년 수린입니다」예요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#8','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C9',2,'mc','auto','다음 시간에 친구에게 책 고르는 법을 알려 주려고 간추린다면 무엇을 남겨야 할까요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13']::text[],false,'{"seq":8,"concept":"K3-2-u1-C9","difficulty":2,"kind":"mc","stem":"다음 시간에 친구에게 책 고르는 법을 알려 주려고 간추린다면 무엇을 남겨야 할까요?","options":[{"t":"선생님이 알려 준 방법 세 가지","correct":true},{"t":"주고받은 말을 하나도 빠뜨리지 않고","mis":"K3-2-u1-X12"},{"t":"선생님의 말투와 웃던 장면","mis":"K3-2-u1-X13"},{"t":"수린이가 몇 학년인지","mis":"K3-2-u1-X13"}],"explanation":["친구가 이것을 보고 책을 골라야 해요.","그러려면 방법이 남아야 해요.","방법 세 가지예요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#9','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',2,'ox','auto','듣기 전에 내가 아는 것이나 겪은 일을 떠올리면 더 잘 들을 수 있어요.',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":9,"concept":"K3-2-u1-C8","difficulty":2,"kind":"ox","stem":"듣기 전에 내가 아는 것이나 겪은 일을 떠올리면 더 잘 들을 수 있어요.","answer":"O","reason_options":[{"t":"아는 것과 이어 들으면 무엇이 중요한지 알아채기 쉽기 때문에","correct":true},{"t":"아는 것을 떠올리면 들을 필요가 없어지기 때문에","mis":"K3-2-u1-X10"}],"mis":"K3-2-u1-X10","explanation":["듣기 전에 할 일이에요.","아는 것과 이어 들어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_basic#10','kor',3,2,'u1','L06','g3_2_kor_u1_L06_basic','lesson_basic','K3-2-u1-C8',3,'error','auto','간추리며 듣는 세 걸음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X11','K3-2-u1-X10']::text[],false,'{"seq":10,"concept":"K3-2-u1-C8","difficulty":3,"kind":"error","stem":"간추리며 듣는 세 걸음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「첫째·둘째 같은 말은 다 듣고 나서 찾아 적는 거야.」","correct":true,"mis_target":"K3-2-u1-X11"},{"t":"친구 가 — 「듣기 전에 무엇을 알려고 듣는지 정해.」","mis":"K3-2-u1-X10"},{"t":"친구 나 — 「다 들은 뒤에는 더 궁금한 것을 적어 둬.」","mis":"K3-2-u1-X10"}],"explanation":["표지어는 듣는 중에 귀를 세우는 말이에요.","들리면 바로 간단히 적어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#1','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',2,'sa','auto','말하는 사람이 「첫째」, 「둘째」 다음 방법을 말할 때 쓰는 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C8","difficulty":2,"kind":"sa","stem":"말하는 사람이 「첫째」, 「둘째」 다음 방법을 말할 때 쓰는 말을 두 글자로 쓰세요.","answer":["셋째"],"explanation":["순서를 알려 주는 말이에요.","첫째 → 둘째 → ?","셋째예요."],"mis":"K3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#2','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',2,'mc','auto','「골랐는데 너무 어려우면 어떻게 하지요?」에 대한 선생님의 대답은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X07']::text[],false,'{"seq":2,"concept":"K3-2-u1-C9","difficulty":2,"kind":"mc","stem":"「골랐는데 너무 어려우면 어떻게 하지요?」에 대한 선생님의 대답은 무엇인가요?","options":[{"t":"끝까지 안 읽어도 되고 나중에 다시 와도 된다","correct":true},{"t":"앞쪽 두세 쪽을 읽어 본다","mis":"K3-2-u1-X17"},{"t":"마음에 남는 한 줄만 적는다","mis":"K3-2-u1-X17"},{"t":"더 어려운 책을 골라 읽는다","mis":"K3-2-u1-X07"}],"explanation":["수린이의 둘째 질문이에요.","선생님은 「둘째」로 답했어요.","나중에 다시 와도 돼요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#3','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',3,'mc','auto','「책 고르는 법을 물었어요」를 간추린 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C9","difficulty":3,"kind":"mc","stem":"「책 고르는 법을 물었어요」를 간추린 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"책은 앞쪽 두세 쪽을 읽어 보고 고르고, 어려우면 나중에 다시 와도 되며, 읽은 뒤에는 마음에 남는 한 줄만 적는다","correct":true},{"t":"수린이가 인사를 하고 3학년이라고 말했다. 선생님이 첫째라고 말했다.","mis":"K3-2-u1-X12"},{"t":"선생님이 친절하게 웃으며 대답해 주셔서 좋았다.","mis":"K3-2-u1-X13"},{"t":"책은 끝까지 다 읽고 읽은 것을 모두 적어 두어야 한다.","mis":"K3-2-u1-X07"}],"explanation":["질문마다 대답을 남겨요.","인사·말투는 덜어 내요.","방법 세 가지가 남은 것을 골라요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#4','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',3,'ox','auto','「음, 그러니까」가 들리면 바로 뒤의 말을 꼭 적어야 해요.',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":4,"concept":"K3-2-u1-C8","difficulty":3,"kind":"ox","stem":"「음, 그러니까」가 들리면 바로 뒤의 말을 꼭 적어야 해요.","answer":"X","reason_options":[{"t":"「음, 그러니까」는 생각하며 내는 말이라 뒤에 중요한 내용이 온다고 볼 수 없기 때문에","correct":true},{"t":"말하는 사람이 내는 말은 모두 중요한 곳을 알려 주는 말이기 때문에","mis":"K3-2-u1-X11"}],"mis":"K3-2-u1-X11","explanation":["표지어는 뒤에 중요한 내용이 따라와요.","「음, 그러니까」는 그렇지 않아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#5','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',3,'match','auto','간추리며 듣는 세 걸음과 할 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C8","difficulty":3,"kind":"match","stem":"간추리며 듣는 세 걸음과 할 일을 알맞게 이으세요.","pairs":[{"l":"듣기 전","r":"목적을 정하고 제목으로 예상한다"},{"l":"듣는 중","r":"표지어에 귀를 세우고 간단히 적는다"},{"l":"들은 후","r":"기호로 나누어 정리하고 궁금한 것을 적는다"}],"mis":"K3-2-u1-X10","explanation":["듣기 전 · 듣는 중 · 들은 후예요.","걸음마다 할 일이 달라요.","세 걸음을 차례대로 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#6','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',3,'error','auto','면담을 질문과 대답으로 간추린 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X12','K3-2-u1-X11']::text[],false,'{"seq":6,"concept":"K3-2-u1-C9","difficulty":3,"kind":"error","stem":"면담을 질문과 대답으로 간추린 것을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「「자꾸 잊어버려요」에 대한 대답은 「앞쪽 두세 쪽을 읽는다」야.」","correct":true,"mis_target":"K3-2-u1-X17"},{"t":"친구 가 — 「질문과 대답을 짝지으면 표가 곧 간추린 것이 돼.」","mis":"K3-2-u1-X12"},{"t":"친구 다 — 「「이것만 기억하세요」 뒤에 중요한 대답이 왔어.」","mis":"K3-2-u1-X11"}],"explanation":["「자꾸 잊어버려요」의 대답을 찾아요.","「마음에 남는 한 줄만 적어 두세요」예요.","친구 나가 잘못 짝지었어요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#7','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',3,'mc','auto','제목 「책 고르는 법을 물었어요」를 보고 듣기 전에 예상한 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":7,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"제목 「책 고르는 법을 물었어요」를 보고 듣기 전에 예상한 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"책을 고르는 방법을 묻고 답하는 내용이 나올 것이다","correct":true},{"t":"도서관 건물을 짓는 이야기가 나올 것이다","mis":"K3-2-u1-X10"},{"t":"책을 파는 가게의 가격이 나올 것이다","mis":"K3-2-u1-X10"},{"t":"제목만으로는 아무것도 알 수 없다","mis":"K3-2-u1-X10"}],"explanation":["제목에 「책 고르는 법」과 「물었어요」가 있어요.","무엇을 묻고 답할지 짐작해요.","책 고르는 방법이 나오겠지요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#8','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',4,'mc','auto','선생님의 「다 적지 말고 마음에 남는 한 줄만 적어 두세요」가 이 단원에서 배우는 간추리기와 닮은 까닭은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X07']::text[],false,'{"seq":8,"concept":"K3-2-u1-C9","difficulty":4,"kind":"mc","stem":"선생님의 「다 적지 말고 마음에 남는 한 줄만 적어 두세요」가 이 단원에서 배우는 간추리기와 닮은 까닭은 무엇인가요?","options":[{"t":"다 옮기지 않고 무엇이 중요한지 생각해 골라 남기기 때문이다","correct":true},{"t":"적는 글자 수가 같기 때문이다","mis":"K3-2-u1-X12"},{"t":"재미있는 말만 고르기 때문이다","mis":"K3-2-u1-X13"},{"t":"책 제목을 외우기 때문이다","mis":"K3-2-u1-X07"}],"explanation":["다 적으면 남는 것이 없어요.","중요한 것을 골라 남겨요.","간추리기도 그렇게 해요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#9','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C8',4,'essay','teacher','학교 알림 방송을 듣는다고 생각하고, 간추리며 듣는 세 걸음(듣기 전·듣는 중·들은 후)에 맞추어 내가 할 일을 하나씩 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C8","difficulty":4,"kind":"essay","stem":"학교 알림 방송을 듣는다고 생각하고, 간추리며 듣는 세 걸음(듣기 전·듣는 중·들은 후)에 맞추어 내가 할 일을 하나씩 쓰세요.","answer_guide":{"answer":"예: 듣기 전 — 「현장 체험 학습 안내」라는 제목을 듣고 무엇을 챙겨야 하는지 알려고 듣기로 정한다. 듣는 중 — 「첫째」, 「가장 중요한 것은」이 들리면 바로 뒤의 말을 공책에 번호를 붙여 적는다. 들은 후 — 적은 것을 번호대로 다시 정리하고, 비가 오면 어떻게 하는지 궁금한 점을 적어 둔다.","scoring_points":["세 걸음으로 나누어 썼는가","걸음마다 알맞은 할 일을 썼는가","목적·표지어·기호나 궁금한 점이 드러나는가"]},"explanation":["듣기 전에는 목적과 예상이에요.","듣는 중에는 표지어예요.","들은 후에는 정리와 궁금한 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L06_challenge#10','kor',3,2,'u1','L06','g3_2_kor_u1_L06_challenge','lesson_challenge','K3-2-u1-C9',4,'essay','teacher','「책 고르는 법을 물었어요」를 질문과 대답으로 짝지어 번호를 붙여 간추리고, 더 궁금한 점을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C9","difficulty":4,"kind":"essay","stem":"「책 고르는 법을 물었어요」를 질문과 대답으로 짝지어 번호를 붙여 간추리고, 더 궁금한 점을 하나 쓰세요.","answer_guide":{"answer":"예: ① 책을 어떻게 고를까요? — 앞쪽 두세 쪽을 읽어 보고 고른다. ② 너무 어려우면요? — 끝까지 안 읽어도 되고 나중에 다시 와도 된다. ③ 자꾸 잊어버려요. — 마음에 남는 한 줄만 적어 둔다. 궁금한 점 — 마음에 남는 한 줄은 어디에 적어 두면 좋을까?","scoring_points":["질문과 대답을 바르게 짝지었는가","번호를 붙여 나누어 정리했는가","더 궁금한 점을 썼는가"]},"explanation":["질문마다 대답을 찾아요.","번호로 나누면 한눈에 보여요.","궁금한 점은 다음에 알아볼 거리예요."],"asset":{"type":"speech","turns":[{"who":"수린","text":"안녕하세요. 저는 3학년 수린입니다. 읽고 싶은 책을 어떻게 고르면 좋을까요?"},{"who":"선생님","text":"첫째, 앞쪽을 두세 쪽 읽어 보세요. 그 두세 쪽이 재미있으면 대개 끝까지 재미있어요."},{"who":"수린","text":"골랐는데 너무 어려우면 어떻게 하지요?"},{"who":"선생님","text":"둘째, 끝까지 안 읽어도 괜찮아요. 다른 책을 읽다가 나중에 다시 와도 돼요."},{"who":"수린","text":"읽은 것을 자꾸 잊어버려요."},{"who":"선생님","text":"이것만 기억하세요. 다 적지 말고 마음에 남는 한 줄만 적어 두세요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#1','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'mc','auto','규안이가 화를 낸 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":1,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"규안이가 화를 낸 까닭은 무엇인가요?","options":[{"t":"누가 자기를 따라 하며 놀린다고 여겨서","correct":true},{"t":"산길이 너무 가팔라서","mis":"K3-2-u1-X07"},{"t":"할머니가 나물을 다 캐 가서","mis":"K3-2-u1-X07"},{"t":"야호 소리가 너무 작아서","mis":"K3-2-u1-X07"}],"explanation":["규안이가 한 말을 읽어요.","「누구야? 왜 따라 해!」라고 했어요.","놀린다고 여겼어요."],"asset":{"type":"passage","lines":["[장면] 규안이가 뒷산 골짜기 꼭대기에 올라선다.","[말] 규안 — “야호!”","[장면] 잠시 뒤 똑같은 “야호!”가 되돌아온다.","[말] 규안 — “누구야? 왜 따라 해!”","[장면] 규안이가 얼굴을 붉힌다.","[말] 골짜기 — “누구야? 왜 따라 해!”","[장면] 똑같이 사나운 소리가 돌아온다."],"title":"이야기 「소리 돌려주는 골짜기」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#2','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'mc','auto','이야기를 간추릴 때 잡아야 할 것이 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":2,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"이야기를 간추릴 때 잡아야 할 것이 아닌 것은 무엇인가요?","options":[{"t":"가장 웃겼던 한 장면","correct":true},{"t":"인물의 특성","mis":"K3-2-u1-X14"},{"t":"일이 일어난 차례","mis":"K3-2-u1-X14"},{"t":"원인과 결과","mis":"K3-2-u1-X14"}],"explanation":["셋을 잡으면 이야기의 뼈대가 남아요.","인물 · 차례 · 원인과 결과예요.","웃긴 장면은 뼈대가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#3','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'sa','auto','할머니는 골짜기가 돌려주는 소리를 무엇이라고 했나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C10","difficulty":1,"kind":"sa","stem":"할머니는 골짜기가 돌려주는 소리를 무엇이라고 했나요? 세 글자로 쓰세요.","answer":["메아리"],"explanation":["할머니의 말을 읽어요.","「그게 ○○○야.」","메아리예요."],"asset":{"type":"passage","lines":["[장면] 규안이가 소리칠수록 더 사나운 소리가 돌아온다.","[장면] 규안이가 지쳐 바위에 앉는다.","[말] 나물을 캐던 할머니 — “골짜기는 준 것을 그대로 돌려준단다. 그게 메아리야.”","[말] 규안 — “미안해!”","[장면] 부드러운 “미안해!”가 되돌아온다.","[장면] 규안이가 웃으며 산을 내려온다."],"title":"이야기 「소리 돌려주는 골짜기」 ②"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#4','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',1,'ox','auto','재미있던 부분만 남기면 이야기를 잘 간추린 거예요.',ARRAY['K3-2-u1-X13']::text[],false,'{"seq":4,"concept":"K3-2-u1-C10","difficulty":1,"kind":"ox","stem":"재미있던 부분만 남기면 이야기를 잘 간추린 거예요.","answer":"X","reason_options":[{"t":"재미있는 것이 꼭 중요한 것은 아니라서 이야기의 뼈대가 빠질 수 있기 때문에","correct":true},{"t":"재미있는 부분이 곧 가장 중요한 내용이기 때문에","mis":"K3-2-u1-X13"}],"mis":"K3-2-u1-X13","explanation":["재미있는 것과 중요한 것은 달라요.","뼈대가 남아야 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#5','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'match','auto','원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":2,"kind":"match","stem":"원인과 결과를 알맞게 이으세요.","pairs":[{"l":"규안이가 반갑게 “야호!” 하고 외쳤다","r":"똑같은 “야호!”가 돌아왔다"},{"l":"규안이가 사납게 소리쳤다","r":"더 사나운 소리가 돌아왔다"},{"l":"규안이가 “미안해!” 하고 외쳤다","r":"부드러운 “미안해!”가 돌아왔다"}],"mis":"K3-2-u1-X15","explanation":["규안이가 준 소리를 봐요.","골짜기는 준 것을 그대로 돌려줘요.","준 것이 곧 돌아온 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#6','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','친구의 이야기 소개에서 잘못된 곳은 무엇인가요?',ARRAY['K3-2-u1-X07','K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"친구의 이야기 소개에서 잘못된 곳은 무엇인가요?","options":[{"t":"일이 일어난 차례가 뒤바뀌고 왜 화를 냈는지가 빠졌다","correct":true},{"t":"낱말이 너무 어렵다","mis":"K3-2-u1-X07"},{"t":"목소리가 너무 작다","mis":"K3-2-u1-X13"},{"t":"이야기를 너무 길게 했다","mis":"K3-2-u1-X12"}],"explanation":["웃으며 내려온 일이 화낸 일보다 먼저 나왔어요.","왜 화를 냈는지도 없어요.","차례와 까닭이 빠졌어요."],"asset":{"type":"passage","lines":["“어떤 애가 산에서 소리를 질렀는데요, 나중에 웃으면서 내려왔어요.","아, 그리고 화도 냈어요. 할머니도 나왔고요. 끝이에요.”"],"title":"친구의 이야기 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#7','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','「소리 돌려주는 골짜기」의 뼈대가 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X14']::text[],false,'{"seq":7,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「소리 돌려주는 골짜기」의 뼈대가 아닌 것은 무엇인가요?","options":[{"t":"할머니가 나물을 캐고 있었다","correct":true},{"t":"같은 소리가 되돌아왔다","mis":"K3-2-u1-X13"},{"t":"규안이가 놀리는 줄 알고 화를 냈다","mis":"K3-2-u1-X14"},{"t":"할머니가 메아리라고 알려 주었다","mis":"K3-2-u1-X14"}],"explanation":["그 일을 빼면 이야기가 이어지나요?","나물을 캔 일은 빼도 이어져요.","틀린 말은 아니지만 뼈대가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#8','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','규안이는 어떤 특성을 지닌 인물인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":8,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"규안이는 어떤 특성을 지닌 인물인가요?","options":[{"t":"오해하면 쉽게 화를 내지만 알고 나면 바로 사과한다","correct":true},{"t":"처음부터 끝까지 조용하고 차분하다","mis":"K3-2-u1-X07"},{"t":"할머니 말을 듣지 않는다","mis":"K3-2-u1-X07"},{"t":"산에 오르기 싫어한다","mis":"K3-2-u1-X07"}],"explanation":["규안이의 말과 행동을 봐요.","「왜 따라 해!」 · 「미안해!」예요.","화를 냈다가 사과했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#9','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',2,'mc','auto','간추린 글이 잘 되었는지 살피는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13']::text[],false,'{"seq":9,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"간추린 글이 잘 되었는지 살피는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"읽고 나서 왜 그랬고 그래서 어떻게 되었는지가 남아 있는지 본다","correct":true},{"t":"본문과 글자 수가 같은지 본다","mis":"K3-2-u1-X12"},{"t":"가장 웃긴 장면이 들어갔는지 본다","mis":"K3-2-u1-X13"},{"t":"인물 이름이 몇 번 나오는지 센다","mis":"K3-2-u1-X12"}],"explanation":["간추린 것이 한 편으로 읽혀야 해요.","「왜」와 「그래서」가 남아 있나요?","빠졌으면 채워 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_basic#10','kor',3,2,'u1','L07','g3_2_kor_u1_L07_basic','lesson_basic','K3-2-u1-C10',3,'error','auto','일이 일어난 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":10,"concept":"K3-2-u1-C10","difficulty":3,"kind":"error","stem":"일이 일어난 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「다정하게 외쳐 다정한 소리가 돌아온 다음에 규안이가 사납게 소리쳤어.」","correct":true,"mis_target":"K3-2-u1-X14"},{"t":"친구 가 — 「규안이가 처음에 골짜기에서 크게 외쳤어.」","mis":"K3-2-u1-X14"},{"t":"친구 나 — 「더 사나운 소리가 돌아와서 규안이가 지쳤어.」","mis":"K3-2-u1-X14"}],"explanation":["외침 → 사나운 소리침 → 지침 → 다정한 외침이에요.","다정한 외침은 맨 끝이에요.","친구 다가 차례를 뒤바꿨어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#1','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',2,'sa','auto','「힘이 다 빠져 기운이 없다」는 뜻의 낱말을 이야기에서 찾아 「~다」로 끝나게 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C10","difficulty":2,"kind":"sa","stem":"「힘이 다 빠져 기운이 없다」는 뜻의 낱말을 이야기에서 찾아 「~다」로 끝나게 쓰세요.","answer":["지치다"],"explanation":["규안이가 바위에 앉기 전이에요.","「○○ 바위에 앉는다」예요.","지치다예요."],"asset":{"type":"passage","lines":["[장면] 규안이가 소리칠수록 더 사나운 소리가 돌아온다.","[장면] 규안이가 지쳐 바위에 앉는다.","[말] 나물을 캐던 할머니 — “골짜기는 준 것을 그대로 돌려준단다. 그게 메아리야.”","[말] 규안 — “미안해!”","[장면] 부드러운 “미안해!”가 되돌아온다.","[장면] 규안이가 웃으며 산을 내려온다."],"title":"이야기 「소리 돌려주는 골짜기」 ②"},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#2','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',2,'mc','auto','「사납다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":2,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「사납다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"거칠고 억세다","correct":true},{"t":"힘이 다 빠져 기운이 없다","mis":"K3-2-u1-X08"},{"t":"부딪혀 되돌아오는 소리","mis":"K3-2-u1-X08"},{"t":"부드럽고 다정하다","mis":"K3-2-u1-X08"}],"explanation":["「사나운 소리」를 떠올려요.","「미안해!」와 반대 느낌이에요.","거칠고 억세다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#3','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'mc','auto','「소리 돌려주는 골짜기」를 간추려 쓴 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X14']::text[],false,'{"seq":3,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「소리 돌려주는 골짜기」를 간추려 쓴 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"규안이는 골짜기에서 소리쳤다가 같은 소리가 돌아오자 놀리는 줄 알고 화를 냈다. 메아리라는 것을 알고 다정하게 외치자 다정한 소리가 돌아왔다.","correct":true},{"t":"규안이가 뒷산 골짜기 꼭대기에 올라선다. 잠시 뒤 똑같은 야호가 되돌아온다.","mis":"K3-2-u1-X12"},{"t":"할머니가 나물을 캐다가 말을 걸었는데 그 장면이 제일 재미있었다.","mis":"K3-2-u1-X13"},{"t":"규안이가 웃으며 산을 내려왔다. 그 전에 화를 냈다.","mis":"K3-2-u1-X14"}],"explanation":["차례와 중요한 일이 다 들어가야 해요.","본문 옮기기 · 재미만 남기기는 아니에요.","한 편으로 읽히는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#4','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'ox','auto','「골짜기에 바위가 있었다」는 틀린 내용이라서 간추린 글에서 빼요.',ARRAY['K3-2-u1-X13']::text[],false,'{"seq":4,"concept":"K3-2-u1-C10","difficulty":3,"kind":"ox","stem":"「골짜기에 바위가 있었다」는 틀린 내용이라서 간추린 글에서 빼요.","answer":"X","reason_options":[{"t":"틀린 내용이 아니라 이야기의 뼈대가 아닌 덜 중요한 내용이라서 빼는 것이기 때문에","correct":true},{"t":"간추리기는 틀린 내용을 걸러 내는 일이기 때문에","mis":"K3-2-u1-X13"}],"mis":"K3-2-u1-X13","explanation":["바위는 이야기에 실제로 나와요.","틀린 것이 아니라 덜 중요한 것이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#5','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'match','auto','이야기를 간추리는 방법과 이 이야기에서 찾은 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C10","difficulty":3,"kind":"match","stem":"이야기를 간추리는 방법과 이 이야기에서 찾은 것을 알맞게 이으세요.","pairs":[{"l":"인물의 특성","r":"오해하면 화를 내지만 알면 바로 사과한다"},{"l":"일이 일어난 차례","r":"외침 → 화냄 → 지침 → 다정한 외침"},{"l":"원인과 결과","r":"준 소리를 골짜기가 그대로 돌려준다"}],"mis":"K3-2-u1-X14","explanation":["인물은 어떤 아이인지예요.","차례는 일이 일어난 순서예요.","원인과 결과는 왜 · 그래서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#6','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'error','auto','이야기를 간추리는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X14']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":3,"kind":"error","stem":"이야기를 간추리는 방법을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「본문 두 줄을 그대로 옮겨 적으면 빠진 것이 없으니 제일 좋아.」","correct":true,"mis_target":"K3-2-u1-X12"},{"t":"친구 나 — 「「왜」와 「그래서」가 빠지면 채워 써야 해.」","mis":"K3-2-u1-X14"},{"t":"친구 다 — 「간추린 것이 한 편으로 읽히는지 소리 내어 읽어 봐.」","mis":"K3-2-u1-X14"}],"explanation":["옮겨 쓰기는 간추리기가 아니에요.","뼈대를 골라 다시 정리해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#7','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',3,'mc','auto','할머니의 「골짜기는 준 것을 그대로 돌려준단다」라는 말은 이야기에서 어떤 구실을 하나요?',ARRAY['K3-2-u1-X13','K3-2-u1-X15','K3-2-u1-X14']::text[],false,'{"seq":7,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"할머니의 「골짜기는 준 것을 그대로 돌려준단다」라는 말은 이야기에서 어떤 구실을 하나요?","options":[{"t":"규안이가 까닭을 깨닫고 행동을 바꾸게 하는 원인이 된다","correct":true},{"t":"이야기와 상관없이 덧붙인 말이다","mis":"K3-2-u1-X13"},{"t":"규안이가 더 크게 화를 내게 만든다","mis":"K3-2-u1-X15"},{"t":"이야기가 시작되었음을 알려 준다","mis":"K3-2-u1-X14"}],"explanation":["할머니 말 다음에 무슨 일이 있었나요?","규안이가 「미안해!」 하고 외쳤어요.","행동이 바뀐 원인이에요."],"asset":{"type":"passage","lines":["[장면] 규안이가 소리칠수록 더 사나운 소리가 돌아온다.","[장면] 규안이가 지쳐 바위에 앉는다.","[말] 나물을 캐던 할머니 — “골짜기는 준 것을 그대로 돌려준단다. 그게 메아리야.”","[말] 규안 — “미안해!”","[장면] 부드러운 “미안해!”가 되돌아온다.","[장면] 규안이가 웃으며 산을 내려온다."],"title":"이야기 「소리 돌려주는 골짜기」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#8','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',4,'mc','auto','이 이야기를 「준 것이 돌아온다」라는 한마디로 간추렸어요. 이 한마디를 뒷받침하는 원인과 결과를 바르게 모은 것은 무엇인가요?',ARRAY['K3-2-u1-X15']::text[],false,'{"seq":8,"concept":"K3-2-u1-C10","difficulty":4,"kind":"mc","stem":"이 이야기를 「준 것이 돌아온다」라는 한마디로 간추렸어요. 이 한마디를 뒷받침하는 원인과 결과를 바르게 모은 것은 무엇인가요?","options":[{"t":"사나운 소리 → 더 사나운 소리, “미안해!” → 부드러운 “미안해!”","correct":true},{"t":"사나운 소리 → 부드러운 “미안해!”, “미안해!” → 더 사나운 소리","mis":"K3-2-u1-X15"},{"t":"할머니가 나물을 캠 → 규안이가 화를 냄","mis":"K3-2-u1-X15"},{"t":"바위에 앉음 → 메아리가 생김","mis":"K3-2-u1-X15"}],"explanation":["규안이가 준 소리와 돌아온 소리를 짝지어요.","사나우면 사납게, 다정하면 다정하게예요.","그래서 준 것이 돌아와요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#9','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',4,'essay','teacher','「소리 돌려주는 골짜기」를 일이 일어난 차례에 따라 네 문장으로 간추리세요. 왜 그랬고 그래서 어떻게 되었는지가 드러나게 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"「소리 돌려주는 골짜기」를 일이 일어난 차례에 따라 네 문장으로 간추리세요. 왜 그랬고 그래서 어떻게 되었는지가 드러나게 쓰세요.","answer_guide":{"answer":"예: 규안이가 골짜기 꼭대기에서 「야호!」 하고 외쳤더니 같은 소리가 되돌아왔다. 규안이는 누가 따라 하며 놀리는 줄 알고 사납게 소리쳤고, 더 사나운 소리가 돌아오자 지쳐 버렸다. 할머니가 골짜기는 준 것을 그대로 돌려주는 메아리라고 알려 주었다. 그래서 규안이가 「미안해!」 하고 외치자 부드러운 소리가 돌아와 규안이는 웃으며 내려왔다.","scoring_points":["네 문장으로 차례에 맞게 간추렸는가","왜 화를 냈는지(원인)를 썼는가","그래서 어떻게 되었는지(결과)를 썼는가"]},"explanation":["차례대로 써요.","「왜」를 빠뜨리지 않아요.","「그래서」로 끝을 맺어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L07_challenge#10','kor',3,2,'u1','L07','g3_2_kor_u1_L07_challenge','lesson_challenge','K3-2-u1-C10',4,'essay','teacher','친구의 이야기 소개에서 빠진 것을 하나 쓰고, 듣는 사람이 알아들을 수 있게 소개를 다시 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"친구의 이야기 소개에서 빠진 것을 하나 쓰고, 듣는 사람이 알아들을 수 있게 소개를 다시 쓰세요.","answer_guide":{"answer":"예: 빠진 것 — 규안이가 왜 화를 냈는지가 빠졌다. 다시 쓴 소개 — 규안이가 산골짜기에서 소리를 질렀는데 같은 소리가 돌아오자 놀리는 줄 알고 화를 냈어요. 할머니가 메아리라고 알려 주어서 「미안해!」 하고 외쳤더니 부드러운 소리가 돌아와 웃으며 내려왔어요.","scoring_points":["빠진 것(차례나 까닭)을 바르게 찾았는가","일이 일어난 차례대로 다시 썼는가","원인과 결과가 드러나게 썼는가"]},"explanation":["듣는 사람이 「왜?」를 묻지 않게 해요.","차례를 바로잡아요.","까닭과 결과를 넣어요."],"asset":{"type":"passage","lines":["“어떤 애가 산에서 소리를 질렀는데요, 나중에 웃으면서 내려왔어요.","아, 그리고 화도 냈어요. 할머니도 나왔고요. 끝이에요.”"],"title":"친구의 이야기 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#1','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'mc','auto','「우리 학교 자랑거리」를 듣고 학교 안내 게시판에 붙일 글을 쓰려면 무엇을 적어야 할까요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12']::text[],false,'{"seq":1,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"「우리 학교 자랑거리」를 듣고 학교 안내 게시판에 붙일 글을 쓰려면 무엇을 적어야 할까요?","options":[{"t":"있는 곳과 좋은 점","correct":true},{"t":"소개한 사람의 목소리와 말투","mis":"K3-2-u1-X13"},{"t":"소개한 차례까지 통째로 그대로","mis":"K3-2-u1-X12"},{"t":"소개가 몇 분 걸렸는지","mis":"K3-2-u1-X13"}],"explanation":["안내 글을 읽는 사람을 떠올려요.","그곳을 찾아가고 쓸 수 있어야 해요.","있는 곳과 좋은 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#2','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'mc','auto','목적을 정하지 않고 들으면 어떻게 될 수 있나요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":2,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"목적을 정하지 않고 들으면 어떻게 될 수 있나요?","options":[{"t":"다 적다가 아무것도 남지 않을 수 있다","correct":true},{"t":"무엇을 적을지 저절로 정해진다","mis":"K3-2-u1-X10"},{"t":"더 빨리 간추릴 수 있다","mis":"K3-2-u1-X10"},{"t":"말하는 사람이 대신 정리해 준다","mis":"K3-2-u1-X10"}],"explanation":["목적이 있어야 적을 것이 정해져요.","목적이 없으면 다 적게 돼요.","그러면 남는 것이 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#3','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'sa','auto','「밭을 길게 돋우어 놓은 줄」이라는 뜻의 낱말을 소개에서 찾아 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C11","difficulty":1,"kind":"sa","stem":"「밭을 길게 돋우어 놓은 줄」이라는 뜻의 낱말을 소개에서 찾아 두 글자로 쓰세요.","answer":["이랑"],"explanation":["뒤뜰 텃밭 소개를 읽어요.","「한 ○○씩 맡아」예요.","이랑이에요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#4','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',1,'ox','auto','같은 소개를 들어도 무엇을 하려고 적느냐에 따라 남길 것이 달라요.',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":4,"concept":"K3-2-u1-C11","difficulty":1,"kind":"ox","stem":"같은 소개를 들어도 무엇을 하려고 적느냐에 따라 남길 것이 달라요.","answer":"O","reason_options":[{"t":"친구에게 알려 주려고 적을 때와 내가 다시 가 보려고 적을 때 필요한 것이 다르기 때문에","correct":true},{"t":"바르게 간추린 답은 하나뿐이기 때문에","mis":"K3-2-u1-X16"}],"mis":"K3-2-u1-X16","explanation":["목적이 바뀌면 남길 것도 바뀌어요.","그래서 간추리기에는 하나의 정답이 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#5','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'match','auto','곳과 자랑거리를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C11","difficulty":2,"kind":"match","stem":"곳과 자랑거리를 알맞게 이으세요.","pairs":[{"l":"도서관 남쪽 창가","r":"오후에 길게 드는 볕"},{"l":"운동장 구석 느티나무","r":"여름에 넓게 드리우는 그늘"},{"l":"급식실 앞 복도","r":"해마다 바뀌는 학년별 그림판"}],"mis":"K3-2-u1-X17","explanation":["그곳이 남다른 까닭을 한 가지씩 찾아요.","볕 · 그늘 · 그림판이에요.","이 표가 안내 글의 뼈대가 돼요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#6','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','안내 글에 넣을 중요한 내용은 어느 것인가요?',ARRAY['K3-2-u1-X13']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"안내 글에 넣을 중요한 내용은 어느 것인가요?","options":[{"t":"뒤뜰 텃밭 — 학년마다 한 이랑씩 맡아 기름","correct":true},{"t":"네 곳이 차례로 말했다","mis":"K3-2-u1-X13"},{"t":"모두 「저는」으로 말을 시작했다","mis":"K3-2-u1-X13"},{"t":"소개하는 목소리가 또렷했다","mis":"K3-2-u1-X13"}],"explanation":["안내 글을 읽는 사람이 쓸 수 있어야 해요.","말한 차례나 말투는 필요 없어요.","곳과 자랑거리를 남겨요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#7','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','「드리우다」의 뜻으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X08']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"「드리우다」의 뜻으로 알맞은 것은 무엇인가요?","options":[{"t":"그늘이나 빛을 넓게 늘어뜨리다","correct":true},{"t":"포근하고 편안하다","mis":"K3-2-u1-X08"},{"t":"밭을 길게 돋우어 놓은 줄","mis":"K3-2-u1-X08"},{"t":"보려고 고개를 자꾸 기울이다","mis":"K3-2-u1-X08"}],"explanation":["「그늘을 드리워서」를 떠올려요.","그늘이 넓게 퍼져요.","넓게 늘어뜨리다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#8','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','느티나무를 세 칸(있는 곳·자랑거리·좋은 점)으로 나눌 때 「좋은 점」 칸에 들어갈 것은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X13']::text[],false,'{"seq":8,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"느티나무를 세 칸(있는 곳·자랑거리·좋은 점)으로 나눌 때 「좋은 점」 칸에 들어갈 것은 무엇인가요?","options":[{"t":"아래가 시원하고 긴 의자에 앉아 쉴 수 있다","correct":true},{"t":"운동장 구석","mis":"K3-2-u1-X17"},{"t":"여름에 넓게 드리우는 그늘","mis":"K3-2-u1-X17"},{"t":"「저는」으로 말을 시작했다","mis":"K3-2-u1-X13"}],"explanation":["운동장 구석은 있는 곳이에요.","넓은 그늘은 자랑거리예요.","우리에게 어떻게 좋은지가 좋은 점이에요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#9','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',2,'mc','auto','찬유가 궁금한 점을 적어 둔 것이 좋은 까닭은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X16','K3-2-u1-X07']::text[],false,'{"seq":9,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"찬유가 궁금한 점을 적어 둔 것이 좋은 까닭은 무엇인가요?","options":[{"t":"다음에 무엇을 더 알아볼지가 생기기 때문에","correct":true},{"t":"궁금한 점을 적으면 글이 길어지기 때문에","mis":"K3-2-u1-X17"},{"t":"궁금한 점은 모두 틀린 생각이기 때문에","mis":"K3-2-u1-X16"},{"t":"소개한 사람이 그렇게 하라고 했기 때문에","mis":"K3-2-u1-X07"}],"explanation":["찬유는 지난해 그림이 궁금했어요.","궁금한 점은 다음 공부거리가 돼요.","더 알아볼 것이 생겨요."],"asset":{"type":"passage","lines":["기억에 남는 곳: 복도 그림판","생각이나 느낌: 해마다 바뀐다는 말이 좋았다. 내 그림도 걸릴 수 있겠다.","궁금한 점: 지난해 그림은 어디에 보관할까?"],"title":"찬유가 적은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_basic#10','kor',3,2,'u1','L09','g3_2_kor_u1_L09_basic','lesson_basic','K3-2-u1-C11',3,'error','auto','두 친구가 같은 소개를 서로 다르게 간추렸을 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":10,"concept":"K3-2-u1-C11","difficulty":3,"kind":"error","stem":"두 친구가 같은 소개를 서로 다르게 간추렸을 때를 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「더 많이 적은 쪽이 잘 간추린 거야.」","correct":true,"mis_target":"K3-2-u1-X16"},{"t":"친구 가 — 「무엇을 하려고 간추렸는지 먼저 물어보자.」","mis":"K3-2-u1-X16"},{"t":"친구 다 — 「목적에 맞았는지는 따져 볼 수 있어.」","mis":"K3-2-u1-X16"}],"explanation":["많이 적었다고 잘 간추린 것은 아니에요.","목적이 다르면 남긴 것도 달라요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#1','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',2,'sa','auto','「포근하고 편안하다」는 뜻의 낱말을 소개에서 찾아 「~하다」로 끝나게 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C11","difficulty":2,"kind":"sa","stem":"「포근하고 편안하다」는 뜻의 낱말을 소개에서 찾아 「~하다」로 끝나게 쓰세요.","answer":["아늑하다"],"explanation":["도서관 창가 소개를 읽어요.","볕이 들어 「○○해요」예요.","아늑하다예요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#2','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',2,'mc','auto','반 「한 줄 소개판」을 만들려고 느티나무를 간추린다면 무엇을 남길까요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13']::text[],false,'{"seq":2,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"반 「한 줄 소개판」을 만들려고 느티나무를 간추린다면 무엇을 남길까요?","options":[{"t":"여름에 넓게 그늘을 드리운다","correct":true},{"t":"운동장 구석에 서 있고 아래에 긴 의자가 두 개 있으며 여름이면 그늘이 넓다는 것 전부","mis":"K3-2-u1-X12"},{"t":"「저는」으로 말을 시작했다","mis":"K3-2-u1-X13"},{"t":"네 곳 가운데 둘째로 말했다","mis":"K3-2-u1-X13"}],"explanation":["한 줄 소개판에는 한 줄만 들어가요.","가장 남다른 점 한 가지를 남겨요.","넓은 그늘이에요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#3','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'mc','auto','뒤뜰 텃밭을 세 칸으로 바르게 정리한 것은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X07','K3-2-u1-X13']::text[],false,'{"seq":3,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"뒤뜰 텃밭을 세 칸으로 바르게 정리한 것은 무엇인가요?","options":[{"t":"있는 곳 — 학교 뒤뜰 / 자랑거리 — 학년마다 한 이랑씩 기름 / 좋은 점 — 직접 길러 볼 수 있음","correct":true},{"t":"있는 곳 — 한 이랑씩 / 자랑거리 — 학교 뒤뜰 / 좋은 점 — 「저는」","mis":"K3-2-u1-X17"},{"t":"있는 곳 — 급식실 앞 / 자랑거리 — 그림판 / 좋은 점 — 해마다 바뀜","mis":"K3-2-u1-X07"},{"t":"있는 곳 — 학교 뒤뜰 / 자랑거리 — 「저는」으로 말함 / 좋은 점 — 네 곳이 말함","mis":"K3-2-u1-X13"}],"explanation":["칸마다 묻는 것이 달라요.","어디 · 무엇이 남다른가 · 어떻게 좋은가예요.","칸에 맞게 넣은 것을 골라요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#4','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'ox','auto','칸을 나누어 적으면 빠진 것이 바로 보여요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":4,"concept":"K3-2-u1-C11","difficulty":3,"kind":"ox","stem":"칸을 나누어 적으면 빠진 것이 바로 보여요.","answer":"O","reason_options":[{"t":"있는 곳·자랑거리·좋은 점 가운데 어느 칸이 비었는지 드러나기 때문에","correct":true},{"t":"칸에 맞추어 들은 말을 모두 옮겨 적기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["칸은 빈자리를 보여 줘요.","빈 칸이 곧 빠진 것이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#5','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'match','auto','간추리는 목적과 남길 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C11","difficulty":3,"kind":"match","stem":"간추리는 목적과 남길 것을 알맞게 이으세요.","pairs":[{"l":"한 줄 소개판을 만들려고","r":"가장 남다른 점 한 가지"},{"l":"친구에게 알려 주려고","r":"있는 곳과 좋은 점"},{"l":"내가 다시 가 보려고","r":"가는 길과 갈 수 있는 때"}],"mis":"K3-2-u1-X17","explanation":["그 글을 읽는 사람이 무엇을 해야 할까요?","목적이 정해지면 남길 것도 정해져요.","목적마다 남길 것을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#6','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'error','auto','듣고 글로 정리하는 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X10','K3-2-u1-X12','K3-2-u1-X17']::text[],false,'{"seq":6,"concept":"K3-2-u1-C11","difficulty":3,"kind":"error","stem":"듣고 글로 정리하는 차례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「칸을 다 채운 다음에 무엇을 하려고 들었는지 정하면 돼.」","correct":true,"mis_target":"K3-2-u1-X10"},{"t":"친구 가 — 「들으며 몇 가지로 나누어 간단히 적어.」","mis":"K3-2-u1-X12"},{"t":"친구 나 — 「마지막에 목적에 맞게 한 편의 글로 다시 써.」","mis":"K3-2-u1-X17"}],"explanation":["목적은 듣기 전에 정해요.","그래야 무엇을 적을지 알아요.","친구 다가 차례를 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#7','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',3,'mc','auto','찬유가 적은 것을 「친구에게 알려 주는 글」로 바꿀 때 더 넣어야 할 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X07']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"찬유가 적은 것을 「친구에게 알려 주는 글」로 바꿀 때 더 넣어야 할 것은 무엇인가요?","options":[{"t":"복도 그림판이 급식실 앞 복도에 있다는 것","correct":true},{"t":"찬유가 좋아하는 색","mis":"K3-2-u1-X13"},{"t":"소개한 사람의 목소리","mis":"K3-2-u1-X13"},{"t":"다른 학교의 그림판","mis":"K3-2-u1-X07"}],"explanation":["친구가 그곳을 찾아가야 해요.","찬유의 메모에는 있는 곳이 없어요.","있는 곳을 넣어요."],"asset":{"type":"passage","lines":["기억에 남는 곳: 복도 그림판","생각이나 느낌: 해마다 바뀐다는 말이 좋았다. 내 그림도 걸릴 수 있겠다.","궁금한 점: 지난해 그림은 어디에 보관할까?"],"title":"찬유가 적은 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#8','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',4,'mc','auto','두 친구가 같은 소개를 서로 다르게 간추렸어요. 다르게 간추린 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":8,"concept":"K3-2-u1-C11","difficulty":4,"kind":"mc","stem":"두 친구가 같은 소개를 서로 다르게 간추렸어요. 다르게 간추린 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"친구 가는 자랑거리와 좋은 점을 알리려고, 친구 나는 찾아가 앉을 곳을 기억하려고 적어서 남긴 것이 다르다","correct":true},{"t":"친구 나가 잘못 들어서 다르다","mis":"K3-2-u1-X16"},{"t":"친구 가가 좋은 점을 더 많이 적었으니 친구 가만 맞다","mis":"K3-2-u1-X16"},{"t":"바르게 간추린 답이 하나인데 둘 다 못 찾았다","mis":"K3-2-u1-X16"}],"explanation":["둘 다 소개에 있는 내용이에요.","무엇을 남겼는지 보면 목적이 보여요.","목적이 달라서 남긴 것이 달라요."],"asset":{"type":"passage","lines":["친구 가 — 도서관 창가: 오후 볕, 아늑함 / 느티나무: 여름 그늘이 넓음","친구 나 — 도서관 창가: 남쪽 / 느티나무: 운동장 구석, 긴 의자 둘"],"title":"두 친구가 간추린 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#9','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',4,'essay','teacher','「우리 학교 자랑거리」 가운데 두 곳을 골라 세 칸(있는 곳·자랑거리·좋은 점)으로 정리하고, 그것을 이어 학교 안내 게시판에 붙일 글을 한 편 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"「우리 학교 자랑거리」 가운데 두 곳을 골라 세 칸(있는 곳·자랑거리·좋은 점)으로 정리하고, 그것을 이어 학교 안내 게시판에 붙일 글을 한 편 쓰세요.","answer_guide":{"answer":"예: 세 칸 — 도서관 창가: 도서관 남쪽 창가 / 오후에 길게 드는 볕 / 아늑해서 책 읽기 좋음. 느티나무: 운동장 구석 / 여름에 넓게 드리우는 그늘 / 시원하고 긴 의자에서 쉴 수 있음. 안내 글 — 우리 학교 자랑거리를 소개합니다. 도서관 남쪽 창가는 오후에 볕이 길게 들어 아늑해서 책 읽기에 좋습니다. 운동장 구석 느티나무는 여름에 그늘을 넓게 드리워 시원하고, 아래 긴 의자에 앉아 쉴 수 있습니다.","scoring_points":["두 곳을 세 칸으로 바르게 나누었는가","칸의 내용을 이어 한 편의 글로 썼는가","안내 글을 읽는 사람에게 필요한 것을 남겼는가"]},"explanation":["칸을 먼저 채워요.","빠진 칸이 없는지 봐요.","칸을 이어 한 편으로 써요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L09_challenge#10','kor',3,2,'u1','L09','g3_2_kor_u1_L09_challenge','lesson_challenge','K3-2-u1-C11',4,'essay','teacher','같은 소개를 듣고 친구와 내가 서로 다르게 간추렸다면 어떻게 하면 좋을지 쓰고, 그렇게 해야 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"같은 소개를 듣고 친구와 내가 서로 다르게 간추렸다면 어떻게 하면 좋을지 쓰고, 그렇게 해야 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 누가 틀렸는지 따지기 전에 서로 무엇을 하려고 간추렸는지 물어본다. 간추리기에는 하나의 정답이 없고 목적이 다르면 남길 것도 달라지기 때문이다. 대신 각자 간추린 것이 자기 목적에 맞았는지는 함께 따져 볼 수 있다.","scoring_points":["목적을 묻겠다고 썼는가","간추리기에 하나의 정답이 없다는 까닭을 썼는가","목적에 맞았는지 따져 볼 수 있음을 썼는가"]},"explanation":["다르다고 틀린 것은 아니에요.","목적부터 물어요.","목적에 맞았는지는 따져 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#1','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',1,'mc','auto','내 경험에 어울리는 이야기를 고르는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X18']::text[],false,'{"seq":1,"concept":"K3-2-u1-C12","difficulty":1,"kind":"mc","stem":"내 경험에 어울리는 이야기를 고르는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"겪은 일이나 그때 마음이 이어지는 이야기를 고른다","correct":true},{"t":"가장 유명한 이야기를 고른다","mis":"K3-2-u1-X18"},{"t":"가장 긴 이야기를 고른다","mis":"K3-2-u1-X18"},{"t":"제목이 가장 짧은 이야기를 고른다","mis":"K3-2-u1-X18"}],"explanation":["1차시에 배운 것을 떠올려요.","마음이 이어지면 돼요.","유명함이나 길이는 기준이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#2','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',1,'mc','auto','안내에서 「둘째」 뒤에 온 중요한 내용은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X13']::text[],false,'{"seq":2,"concept":"K3-2-u1-C12","difficulty":1,"kind":"mc","stem":"안내에서 「둘째」 뒤에 온 중요한 내용은 무엇인가요?","options":[{"t":"제자리에 꽂거나 반납대에 두기","correct":true},{"t":"정해진 날까지 돌려주기","mis":"K3-2-u1-X17"},{"t":"책에 표시하지 않기","mis":"K3-2-u1-X17"},{"t":"안내가 네 줄이었다","mis":"K3-2-u1-X13"}],"explanation":["「둘째」 뒤를 읽어요.","읽고 난 책을 어디에 둘지예요.","제자리나 반납대예요."],"asset":{"type":"passage","lines":["첫째, 빌린 책은 정해진 날까지 돌려주세요. 기다리는 사람이 있어요.","둘째, 읽고 난 책은 제자리에 꽂거나 반납대에 두세요. 자리를 모르면 반납대가 더 나아요.","셋째, 책에는 표시를 하지 마세요. 연필로 그은 줄도 지워 주세요.","이것만 기억하세요. 다음 사람이 그대로 읽을 수 있게 두는 거예요."],"title":"안내 「도서관을 함께 쓰는 약속」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#3','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',1,'ox','auto','받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ 소리가 나지 않아요.',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":3,"concept":"K3-2-u1-C13","difficulty":1,"kind":"ox","stem":"받침 ㅎ 뒤에 모음으로 시작하는 말이 오면 ㅎ 소리가 나지 않아요.","answer":"O","reason_options":[{"t":"「빻아」가 [빠아]로 소리 나는 것처럼 모음 앞에서 ㅎ 소리가 사라지기 때문에","correct":true},{"t":"받침 ㅎ은 언제나 소리 나지 않기 때문에","mis":"K3-2-u1-X20"}],"mis":"K3-2-u1-X20","explanation":["「빻아」를 소리 내어 봐요.","[빠아]로 소리 나요.","모음 앞에서만 사라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#4','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',1,'mc','auto','「빻아」는 어떻게 소리 나나요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":4,"concept":"K3-2-u1-C13","difficulty":1,"kind":"mc","stem":"「빻아」는 어떻게 소리 나나요?","options":[{"t":"[빠아]","correct":true},{"t":"[빤아]","mis":"K3-2-u1-X20"},{"t":"[빠하]","mis":"K3-2-u1-X20"},{"t":"[빧아]","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 뒤에 모음 ㅏ가 왔어요.","ㅎ 소리가 나지 않아요.","[빠아]예요. 쓸 때는 「빻아」 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#5','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',2,'match','auto','경험과 어울리는 이야기를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C12","difficulty":2,"kind":"match","stem":"경험과 어울리는 이야기를 알맞게 이으세요.","pairs":[{"l":"말을 걸고 싶었는데 며칠을 미뤘다","r":"「나중에 온 아이」"},{"l":"화를 냈더니 더 큰 화가 돌아왔다","r":"「소리 돌려주는 골짜기」"},{"l":"멀리 간 친구가 자꾸 떠오른다","r":"「김 서린 창문」"}],"mis":"K3-2-u1-X02","explanation":["그 이야기의 인물은 어떤 마음이었나요?","미룬 마음 · 돌아온 화 · 보고 싶은 마음이에요.","마음이 이어지는 짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#6','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C12',2,'mc','auto','실천 다짐으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":6,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"실천 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"“빌린 날에 공책에 돌려줄 날을 적어 둔다.”","correct":true},{"t":"“앞으로 모든 약속을 다 잘 지키겠다.”","mis":"K3-2-u1-X19"},{"t":"“우리 반 친구들이 책을 아꼈으면 좋겠다.”","mis":"K3-2-u1-X19"},{"t":"“도서관 선생님이 더 크게 안내해 주시면 좋겠다.”","mis":"K3-2-u1-X19"}],"explanation":["다짐을 읽고 바로 무엇을 할지 알아야 해요.","내가 할 한 가지예요.","언제 · 무엇을이 들어간 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#7','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',2,'mc','auto','받침 ㅎ 소리가 나지 않는 것은 어느 것인가요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":7,"concept":"K3-2-u1-C13","difficulty":2,"kind":"mc","stem":"받침 ㅎ 소리가 나지 않는 것은 어느 것인가요?","options":[{"t":"찧으면","correct":true},{"t":"빻고","mis":"K3-2-u1-X20"},{"t":"찧다","mis":"K3-2-u1-X20"},{"t":"빻지","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 바로 뒤를 봐요.","「으」는 모음으로 시작해요.","찧으면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#8','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C14',2,'mc','auto','「피리 · 북 · 장구」를 한 이름으로 묶은 것은 무엇인가요?',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":8,"concept":"K3-2-u1-C14","difficulty":2,"kind":"mc","stem":"「피리 · 북 · 장구」를 한 이름으로 묶은 것은 무엇인가요?","options":[{"t":"악기","correct":true},{"t":"채소","mis":"K3-2-u1-X22"},{"t":"계절","mis":"K3-2-u1-X22"},{"t":"피리","mis":"K3-2-u1-X22"}],"explanation":["셋을 한마디로 불러요.","소리를 내는 물건이에요.","악기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#9','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C14',2,'mc','auto','「무 · 오이 · 상추」를 묶는 이름은 무엇인가요?',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":9,"concept":"K3-2-u1-C14","difficulty":2,"kind":"mc","stem":"「무 · 오이 · 상추」를 묶는 이름은 무엇인가요?","options":[{"t":"채소","correct":true},{"t":"과일","mis":"K3-2-u1-X22"},{"t":"악기","mis":"K3-2-u1-X22"},{"t":"오이","mis":"K3-2-u1-X22"}],"explanation":["밭에서 길러 먹는 것이에요.","오이는 그 가운데 하나예요.","채소예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_basic#10','kor',3,2,'u1','L11','g3_2_kor_u1_L11_basic','lesson_basic','K3-2-u1-C13',3,'error','auto','받침 ㅎ을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X21','K3-2-u1-X20']::text[],false,'{"seq":10,"concept":"K3-2-u1-C13","difficulty":3,"kind":"error","stem":"받침 ㅎ을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「「찧어」는 소리 나는 대로 「찌어」라고 써야 해.」","correct":true,"mis_target":"K3-2-u1-X21"},{"t":"친구 가 — 「「빻아」는 [빠아]로 소리 나.」","mis":"K3-2-u1-X20"},{"t":"친구 나 — 「「빻고」는 뒤가 자음이라 ㅎ 소리가 그냥 사라지지 않아.」","mis":"K3-2-u1-X20"}],"explanation":["소리만 사라져요.","쓸 때는 받침 ㅎ을 그대로 써요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#1','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C13',2,'sa','auto','「찧어」는 어떻게 소리 나나요? 대괄호 없이 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C13","difficulty":2,"kind":"sa","stem":"「찧어」는 어떻게 소리 나나요? 대괄호 없이 두 글자로 쓰세요.","answer":["찌어"],"explanation":["받침 ㅎ 뒤에 모음 ㅓ가 왔어요.","ㅎ 소리가 사라져요.","[찌어]예요."],"mis":"K3-2-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#2','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',2,'mc','auto','안내에서 「이것만 기억하세요」 뒤에 온 말은 무엇인가요?',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":2,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"안내에서 「이것만 기억하세요」 뒤에 온 말은 무엇인가요?","options":[{"t":"다음 사람이 그대로 읽을 수 있게 두는 거예요.","correct":true},{"t":"기다리는 사람이 있어요.","mis":"K3-2-u1-X11"},{"t":"연필로 그은 줄도 지워 주세요.","mis":"K3-2-u1-X11"},{"t":"자리를 모르면 반납대가 더 나아요.","mis":"K3-2-u1-X11"}],"explanation":["「이것만 기억하세요」는 표지어예요.","바로 뒤의 말이 가장 중요해요.","다음 사람을 위한 말이에요."],"asset":{"type":"passage","lines":["첫째, 빌린 책은 정해진 날까지 돌려주세요. 기다리는 사람이 있어요.","둘째, 읽고 난 책은 제자리에 꽂거나 반납대에 두세요. 자리를 모르면 반납대가 더 나아요.","셋째, 책에는 표시를 하지 마세요. 연필로 그은 줄도 지워 주세요.","이것만 기억하세요. 다음 사람이 그대로 읽을 수 있게 두는 거예요."],"title":"안내 「도서관을 함께 쓰는 약속」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#3','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',3,'mc','auto','「도서관을 함께 쓰는 약속」을 간추린 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X12','K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C12","difficulty":3,"kind":"mc","stem":"「도서관을 함께 쓰는 약속」을 간추린 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"① 정해진 날까지 돌려주기 ② 제자리나 반납대에 두기 ③ 책에 표시하지 않기 — 다음 사람이 그대로 읽게","correct":true},{"t":"안내가 네 줄이었고 「첫째」로 시작했다","mis":"K3-2-u1-X13"},{"t":"첫째, 빌린 책은 정해진 날까지 돌려주세요. 기다리는 사람이 있어요. 둘째, …","mis":"K3-2-u1-X12"},{"t":"도서관에서는 조용히 해야 한다","mis":"K3-2-u1-X07"}],"explanation":["표지어 뒤의 내용을 남겨요.","번호로 나누면 한눈에 보여요.","안내에 없는 말은 넣지 않아요."],"asset":{"type":"passage","lines":["첫째, 빌린 책은 정해진 날까지 돌려주세요. 기다리는 사람이 있어요.","둘째, 읽고 난 책은 제자리에 꽂거나 반납대에 두세요. 자리를 모르면 반납대가 더 나아요.","셋째, 책에는 표시를 하지 마세요. 연필로 그은 줄도 지워 주세요.","이것만 기억하세요. 다음 사람이 그대로 읽을 수 있게 두는 거예요."],"title":"안내 「도서관을 함께 쓰는 약속」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#4','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',3,'ox','auto','「우리 반 친구들이 책을 아꼈으면 좋겠다.」는 좋은 실천 다짐이에요.',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":4,"concept":"K3-2-u1-C12","difficulty":3,"kind":"ox","stem":"「우리 반 친구들이 책을 아꼈으면 좋겠다.」는 좋은 실천 다짐이에요.","answer":"X","reason_options":[{"t":"내가 할 일이 아니라 남이 지켜 주기를 바라는 말이기 때문에","correct":true},{"t":"모두에게 좋은 말이니 다짐이 되기 때문에","mis":"K3-2-u1-X19"}],"mis":"K3-2-u1-X19","explanation":["실천 다짐은 내가 할 일이에요.","남에게 바라는 말은 다짐이 아니에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#5','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C14',3,'match','auto','묶는 이름과 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C14","difficulty":3,"kind":"match","stem":"묶는 이름과 낱말을 알맞게 이으세요.","pairs":[{"l":"과일","r":"사과 · 배 · 감"},{"l":"탈것","r":"자전거 · 버스 · 기차"},{"l":"학용품","r":"연필 · 지우개 · 자"}],"mis":"K3-2-u1-X22","explanation":["셋을 한마디로 부르면 무엇일까요?","먹는 것 · 타는 것 · 공부할 때 쓰는 것이에요.","묶는 이름을 찾아 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#6','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',3,'error','auto','내 경험에 어울리는 이야기를 고르며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X18','K3-2-u1-X02']::text[],false,'{"seq":6,"concept":"K3-2-u1-C12","difficulty":3,"kind":"error","stem":"내 경험에 어울리는 이야기를 고르며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「「나중에 온 아이」가 가장 기니까 내 경험에 제일 잘 어울려.」","correct":true,"mis_target":"K3-2-u1-X18"},{"t":"친구 가 — 「다툰 뒤 말없이 화해한 내 경험에는 「돌아선 등」이 어울려.」","mis":"K3-2-u1-X18"},{"t":"친구 다 — 「겪은 일이 똑같지 않아도 마음이 이어지면 돼.」","mis":"K3-2-u1-X02"}],"explanation":["길이는 고르는 기준이 아니에요.","내 마음과 이어지는지 봐요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#7','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C13',3,'mc','auto','받침 ㅎ 소리가 나지 않는 말끼리 묶은 것은 무엇인가요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":7,"concept":"K3-2-u1-C13","difficulty":3,"kind":"mc","stem":"받침 ㅎ 소리가 나지 않는 말끼리 묶은 것은 무엇인가요?","options":[{"t":"빻아서, 찧으면","correct":true},{"t":"빻고, 찧다","mis":"K3-2-u1-X20"},{"t":"빻아서, 빻고","mis":"K3-2-u1-X20"},{"t":"찧다, 찧으면","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 뒤에 모음이 오는 것을 찾아요.","아서 · 으면은 모음으로 시작해요.","빻아서, 찧으면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#8','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',4,'mc','auto','「앞으로 모든 약속을 다 잘 지키겠다.」를 안내 내용에 맞게 고친 다짐으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X19','K3-2-u1-X07']::text[],false,'{"seq":8,"concept":"K3-2-u1-C12","difficulty":4,"kind":"mc","stem":"「앞으로 모든 약속을 다 잘 지키겠다.」를 안내 내용에 맞게 고친 다짐으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“책을 다 읽으면 그날 바로 반납대에 둔다.”","correct":true},{"t":"“도서관 약속을 아주아주 잘 지키겠다.”","mis":"K3-2-u1-X19"},{"t":"“친구들이 책에 줄을 긋지 않으면 좋겠다.”","mis":"K3-2-u1-X19"},{"t":"“도서관에서 뛰지 않겠다.”","mis":"K3-2-u1-X07"}],"explanation":["막연한 다짐은 아무것도 안 하게 돼요.","안내 가운데 내가 할 한 가지를 골라요.","언제 · 무엇을이 들어가게 고쳐요."],"asset":{"type":"passage","lines":["첫째, 빌린 책은 정해진 날까지 돌려주세요. 기다리는 사람이 있어요.","둘째, 읽고 난 책은 제자리에 꽂거나 반납대에 두세요. 자리를 모르면 반납대가 더 나아요.","셋째, 책에는 표시를 하지 마세요. 연필로 그은 줄도 지워 주세요.","이것만 기억하세요. 다음 사람이 그대로 읽을 수 있게 두는 거예요."],"title":"안내 「도서관을 함께 쓰는 약속」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#9','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C12',4,'essay','teacher','기억에 남는 내 경험 하나를 언제·어디에서·누구와가 드러나게 쓰고, 이 단원에서 읽은 작품 가운데 그 경험에 어울리는 것을 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C12","difficulty":4,"kind":"essay","stem":"기억에 남는 내 경험 하나를 언제·어디에서·누구와가 드러나게 쓰고, 이 단원에서 읽은 작품 가운데 그 경험에 어울리는 것을 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 지난 학기 우리 반 교실에서 새로 온 친구에게 같이 놀자고 말하고 싶었는데 며칠이나 미뤘다. 이 경험에는 「나중에 온 아이」가 어울린다. 도빈이도 말을 걸고 싶었는데 이상해 보일까 봐 미뤘고, 미룬 날들이 아까웠다고 한 마음이 내 마음과 같기 때문이다.","scoring_points":["경험을 언제·어디에서·누구와가 드러나게 썼는가","어울리는 작품을 골랐는가","마음이 이어진다는 까닭을 썼는가"]},"explanation":["경험부터 또렷하게 적어요.","이어지는 작품을 골라요.","까닭에는 이어지는 마음을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_L11_challenge#10','kor',3,2,'u1','L11','g3_2_kor_u1_L11_challenge','lesson_challenge','K3-2-u1-C13',4,'essay','teacher','「빻아」를 넣어 문장을 하나 만들고, 「빻아」가 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C13","difficulty":4,"kind":"essay","stem":"「빻아」를 넣어 문장을 하나 만들고, 「빻아」가 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「할머니께서 깨를 절구에 빻아 주셨다.」에서 「빻아」는 [빠아]로 소리 난다. 받침 ㅎ 뒤에 모음으로 시작하는 말이 와서 ㅎ 소리가 나지 않기 때문이다. 그래도 쓸 때는 소리만 사라질 뿐이니 받침 ㅎ을 살려 「빻아」라고 쓴다.","scoring_points":["「빻아」를 넣어 문장을 만들었는가","[빠아]로 소리 난다고 썼는가","쓸 때는 그대로 쓴다는 것과 까닭을 썼는가"]},"explanation":["모음 앞 받침 ㅎ이에요.","소리는 [빠아]예요.","글자는 빻아 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#1','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C1',1,'mc','auto','친구가 말한 경험 「어제 저녁 우리 집 마당에서 동생과 비눗방울을 불었는데 무지개색이 보여 신났어.」에서 「어디에서」에 해당하는 말은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 말한 경험 「어제 저녁 우리 집 마당에서 동생과 비눗방울을 불었는데 무지개색이 보여 신났어.」에서 「어디에서」에 해당하는 말은 무엇인가요?","options":[{"t":"우리 집 마당에서","correct":true},{"t":"어제 저녁","mis":"K3-2-u1-X01"},{"t":"동생과","mis":"K3-2-u1-X01"},{"t":"신났어","mis":"K3-2-u1-X01"}],"explanation":["어제 저녁은 언제예요.","동생과는 누구와예요.","어디에서는 우리 집 마당이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#2','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C2',1,'mc','auto','「반쪽 우산」과 이어지는 경험은 어느 것인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":2,"concept":"K3-2-u1-C2","difficulty":1,"kind":"mc","stem":"「반쪽 우산」과 이어지는 경험은 어느 것인가요?","options":[{"t":"친구가 내 짐을 들어 주어 고마웠던 날","correct":true},{"t":"비 오는 날 장화를 산 일","mis":"K3-2-u1-X02"},{"t":"우산을 잃어버린 일","mis":"K3-2-u1-X02"},{"t":"어제 본 만화 영화","mis":"K3-2-u1-X03"}],"explanation":["우산이나 비를 찾는 게 아니에요.","나를 챙겨 준 친구가 고마운 마음을 찾아요.","짐을 들어 준 날이에요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#3','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C3',1,'mc','auto','「반쪽 우산」에서 말하는 이가 겪은 일은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「반쪽 우산」에서 말하는 이가 겪은 일은 무엇인가요?","options":[{"t":"우산 하나를 짝꿍과 함께 쓰고 집에 왔다","correct":true},{"t":"혼자 비를 맞으며 뛰었다","mis":"K3-2-u1-X07"},{"t":"우산을 새로 샀다","mis":"K3-2-u1-X07"},{"t":"짝꿍과 말다툼을 했다","mis":"K3-2-u1-X07"}],"explanation":["첫 줄 「우산은 하나뿐」을 봐요.","짝꿍이 우산을 기울였어요.","함께 쓰고 집 앞까지 왔어요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#4','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C5',1,'mc','auto','서아의 가슴이 조마조마했던 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"서아의 가슴이 조마조마했던 까닭은 무엇인가요?","options":[{"t":"빌린 줄넘기의 손잡이가 빠져서","correct":true},{"t":"체육 시간이 끝나서","mis":"K3-2-u1-X07"},{"t":"하율이가 화를 내서","mis":"K3-2-u1-X07"},{"t":"줄넘기를 잘 못해서","mis":"K3-2-u1-X07"}],"explanation":["조마조마하기 바로 앞을 읽어요.","손잡이가 툭 빠졌어요.","빌린 물건이라 걱정했어요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#5','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C8',1,'mc','auto','「텃밭 물 주기 안내」를 듣기 전에 할 일로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":5,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"「텃밭 물 주기 안내」를 듣기 전에 할 일로 알맞은 것은 무엇인가요?","options":[{"t":"제목을 보고 물 주는 방법이 나올 것이라고 예상한다","correct":true},{"t":"안내를 미리 다 적어 둔다","mis":"K3-2-u1-X10"},{"t":"아무 생각 없이 기다린다","mis":"K3-2-u1-X10"},{"t":"들은 뒤에 궁금한 점부터 적는다","mis":"K3-2-u1-X10"}],"explanation":["듣기 전에는 목적과 예상이에요.","제목이 힌트예요.","물 주는 방법을 예상해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#6','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',1,'mc','auto','이야기를 간추릴 때 잡을 것이 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"이야기를 간추릴 때 잡을 것이 아닌 것은 무엇인가요?","options":[{"t":"인물이 입은 옷 색깔","correct":true},{"t":"인물의 특성","mis":"K3-2-u1-X14"},{"t":"일이 일어난 차례","mis":"K3-2-u1-X14"},{"t":"원인과 결과","mis":"K3-2-u1-X14"}],"explanation":["셋을 잡으면 뼈대가 남아요.","인물 · 차례 · 원인과 결과예요.","옷 색깔은 뼈대가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#7','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C11',1,'mc','auto','간추리기에 하나의 정답이 없는 까닭은 무엇인가요?',ARRAY['K3-2-u1-X16','K3-2-u1-X12']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"간추리기에 하나의 정답이 없는 까닭은 무엇인가요?","options":[{"t":"무엇을 하려고 간추렸는지에 따라 남길 것이 달라서","correct":true},{"t":"누구나 잘못 듣기 때문에","mis":"K3-2-u1-X16"},{"t":"들은 말을 다 적으면 되기 때문에","mis":"K3-2-u1-X12"},{"t":"간추리기는 아무렇게나 해도 되기 때문에","mis":"K3-2-u1-X16"}],"explanation":["목적이 다르면 남길 것도 달라요.","그래도 목적에 맞았는지는 따져요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#8','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C13',1,'mc','auto','「찧어」는 어떻게 소리 나나요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":8,"concept":"K3-2-u1-C13","difficulty":1,"kind":"mc","stem":"「찧어」는 어떻게 소리 나나요?","options":[{"t":"[찌어]","correct":true},{"t":"[찌허]","mis":"K3-2-u1-X20"},{"t":"[찐어]","mis":"K3-2-u1-X20"},{"t":"[찓어]","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 뒤에 모음 ㅓ가 왔어요.","ㅎ 소리가 나지 않아요.","[찌어]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#9','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C1',2,'mc','auto','「반쪽 우산」을 읽고 떠올린 경험을 말할 때, 언제·어디에서·누구와·마음이 모두 드러난 것은 어느 것인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":9,"concept":"K3-2-u1-C1","difficulty":2,"kind":"mc","stem":"「반쪽 우산」을 읽고 떠올린 경험을 말할 때, 언제·어디에서·누구와·마음이 모두 드러난 것은 어느 것인가요?","options":[{"t":"「지난여름 학교 앞에서 언니가 자기 모자를 씌워 줘서 고마웠어.」","correct":true},{"t":"「고마웠어.」","mis":"K3-2-u1-X01"},{"t":"「지난여름에 비가 왔어.」","mis":"K3-2-u1-X01"},{"t":"「우산은 파란색이었어.」","mis":"K3-2-u1-X01"}],"explanation":["지난여름 · 학교 앞 · 언니 · 고마웠어가 있어요.","다른 것은 빠진 것이 많아요.","첫 번째가 모두 드러나요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#10','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C3',2,'mc','auto','「반쪽 우산」에서 말하는 이에게 오래 남은 것은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":10,"concept":"K3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「반쪽 우산」에서 말하는 이에게 오래 남은 것은 무엇인가요?","options":[{"t":"짝꿍이 집 앞에서 한 「내일 보자」라는 한마디","correct":true},{"t":"젖은 어깨의 차가움","mis":"K3-2-u1-X07"},{"t":"우산의 색깔","mis":"K3-2-u1-X07"},{"t":"빗소리","mis":"K3-2-u1-X07"}],"explanation":["마지막 줄을 읽어요.","「그 한마디가 오래 남았다」예요.","「내일 보자」예요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#11','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C6',2,'mc','auto','서아의 마음을 근거 있게 짐작한 것은 어느 것인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":11,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"서아의 마음을 근거 있게 짐작한 것은 어느 것인가요?","options":[{"t":"모른 척 고개를 숙인 것을 보면 들킬까 봐 마음이 불편했을 것 같다","correct":true},{"t":"서아는 원래 하율이를 싫어했을 것 같다","mis":"K3-2-u1-X04"},{"t":"서아는 줄넘기 모으기를 좋아할 것 같다","mis":"K3-2-u1-X04"},{"t":"서아는 체육 시간을 싫어할 것 같다","mis":"K3-2-u1-X04"}],"explanation":["근거는 이야기에 나온 행동이에요.","고개를 숙인 행동을 봐요.","나머지는 이야기에 없어요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#12','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C7',2,'mc','auto','서아에게 하고 싶은 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":12,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"서아에게 하고 싶은 말로 알맞은 것은 무엇인가요?","options":[{"t":"“집에 가는 길에 하율이를 불러 세운 건 용기가 필요했겠다.”","correct":true},{"t":"“다음부터는 남의 물건을 빌리지 마.”","mis":"K3-2-u1-X09"},{"t":"“처음부터 말했어야지.”","mis":"K3-2-u1-X09"},{"t":"“하율이가 줄넘기를 잘못 만든 거야.”","mis":"K3-2-u1-X09"}],"explanation":["가르치거나 탓하는 말이 아니에요.","서아가 한 행동을 짚어요.","불러 세운 용기를 알아줘요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#13','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C9',2,'mc','auto','「텃밭 물 주기 안내」를 질문과 대답으로 간추릴 때 「물은 어디에 주나요?」의 대답은 무엇인가요?',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":13,"concept":"K3-2-u1-C9","difficulty":2,"kind":"mc","stem":"「텃밭 물 주기 안내」를 질문과 대답으로 간추릴 때 「물은 어디에 주나요?」의 대답은 무엇인가요?","options":[{"t":"잎이 아니라 뿌리 쪽 흙에 천천히","correct":true},{"t":"아침 수업 전에","mis":"K3-2-u1-X17"},{"t":"이랑 옆 기록판에","mis":"K3-2-u1-X17"},{"t":"마른 날에만","mis":"K3-2-u1-X17"}],"explanation":["「둘째」 뒤를 읽어요.","어디에 주는지 말했어요.","뿌리 쪽 흙이에요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#14','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',2,'match','auto','「빠진 손잡이」의 원인과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"K3-2-u1-C10","difficulty":2,"kind":"match","stem":"「빠진 손잡이」의 원인과 결과를 알맞게 이으세요.","pairs":[{"l":"손잡이가 툭 빠졌다","r":"가슴이 조마조마했다"},{"l":"모른 척 고개를 숙였다","r":"그날 내내 공기놀이도 재미가 없었다"},{"l":"사실대로 말하고 사과했다","r":"마음이 후련했다"}],"mis":"K3-2-u1-X15","explanation":["왜 그랬는지 먼저 찾아요.","그래서 어떻게 되었는지 이어요.","숨기면 불편, 말하면 후련이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#15','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C11',2,'mc','auto','「텃밭 물 주기 안내」로 반 「한 줄 소개판」을 만든다면 무엇을 남겨야 할까요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13']::text[],false,'{"seq":15,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"「텃밭 물 주기 안내」로 반 「한 줄 소개판」을 만든다면 무엇을 남겨야 할까요?","options":[{"t":"흙을 눌러 보고 마른 날에만 물 주기","correct":true},{"t":"첫째부터 셋째까지 들은 말 전부","mis":"K3-2-u1-X12"},{"t":"「음, 그러니까」라고 말한 것","mis":"K3-2-u1-X13"},{"t":"안내가 네 줄이었다는 것","mis":"K3-2-u1-X13"}],"explanation":["한 줄에는 한 가지만 들어가요.","가장 중요한 것을 남겨요.","「가장 중요한 것은」 뒤의 내용이에요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#16','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C12',2,'mc','auto','「텃밭 물 주기 안내」를 듣고 쓴 실천 다짐으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":16,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"「텃밭 물 주기 안내」를 듣고 쓴 실천 다짐으로 알맞은 것은 무엇인가요?","options":[{"t":"“물을 주기 전에 흙을 손가락으로 눌러 본다.”","correct":true},{"t":"“텃밭 일을 모두 잘하겠다.”","mis":"K3-2-u1-X19"},{"t":"“다른 반이 물을 잘 주면 좋겠다.”","mis":"K3-2-u1-X19"},{"t":"“텃밭을 많이 사랑하겠다.”","mis":"K3-2-u1-X19"}],"explanation":["내가 할 한 가지예요.","무엇을 할지 바로 알 수 있어야 해요.","흙을 눌러 보는 다짐이에요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#17','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C4',3,'error','auto','「반쪽 우산」을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":17,"concept":"K3-2-u1-C4","difficulty":3,"kind":"error","stem":"「반쪽 우산」을 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「「짝꿍 어깨」 줄을 고른 친구는 틀렸어. 인상 깊은 줄은 「내일 보자」가 정답이야.」","correct":true,"mis_target":"K3-2-u1-X05"},{"t":"친구 가 — 「나는 짝꿍 어깨가 젖은 줄이 마음에 남아.」","mis":"K3-2-u1-X05"},{"t":"친구 나 — 「너는 왜 그 줄을 골랐는지 궁금해.」","mis":"K3-2-u1-X05"}],"explanation":["인상 깊은 줄에는 정답이 없어요.","다르면 까닭을 물어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#18','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C6',3,'error','auto','서아의 마음을 짐작한 것을 두고 말했어요. 이야기에 근거가 없는 짐작을 한 친구는 누구인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":18,"concept":"K3-2-u1-C6","difficulty":3,"kind":"error","stem":"서아의 마음을 짐작한 것을 두고 말했어요. 이야기에 근거가 없는 짐작을 한 친구는 누구인가요?","options":[{"t":"친구 다 — 「서아는 원래 물건을 잘 망가뜨리는 아이라서 그랬을 거야.」","correct":true,"mis_target":"K3-2-u1-X04"},{"t":"친구 가 — 「모른 척 고개를 숙인 걸 보니 들킬까 봐 겁났을 거야.」","mis":"K3-2-u1-X04"},{"t":"친구 나 — 「공기놀이도 재미없었다니 계속 마음에 걸렸을 거야.」","mis":"K3-2-u1-X04"}],"explanation":["이야기에 나온 행동을 근거로 해요.","「원래 잘 망가뜨린다」는 말은 없어요.","친구 다는 지어냈어요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#19','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C8',3,'error','auto','간추리며 듣는 걸음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X10']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"error","stem":"간추리며 듣는 걸음을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「들으면서 모든 말을 빠짐없이 받아 적어야 해.」","correct":true,"mis_target":"K3-2-u1-X12"},{"t":"친구 나 — 「듣기 전에 제목으로 내용을 짐작해 봐.」","mis":"K3-2-u1-X10"},{"t":"친구 다 — 「다 들은 뒤에는 더 궁금한 것을 적어 둬.」","mis":"K3-2-u1-X10"}],"explanation":["다 받아 적으면 남는 것이 없어요.","표지어 뒤를 간단히 적어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#20','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C10',3,'error','auto','「빠진 손잡이」를 간추리는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":20,"concept":"K3-2-u1-C10","difficulty":3,"kind":"error","stem":"「빠진 손잡이」를 간추리는 방법을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「「서아가 사과해서 후련했다.」 한 문장이면 충분해.」","correct":true,"mis_target":"K3-2-u1-X14"},{"t":"친구 가 — 「손잡이를 빠뜨리고 숨긴 일부터 차례대로 써야 해.」","mis":"K3-2-u1-X14"},{"t":"친구 다 — 「왜 몰래 넣었는지도 써야 뒤가 이어져.」","mis":"K3-2-u1-X14"}],"explanation":["너무 줄이면 무슨 이야기인지 몰라요.","차례와 까닭이 남아야 해요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#21','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C11',3,'error','auto','두 친구가 「텃밭 물 주기 안내」를 서로 다르게 간추렸어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X16','K3-2-u1-X17']::text[],false,'{"seq":21,"concept":"K3-2-u1-C11","difficulty":3,"kind":"error","stem":"두 친구가 「텃밭 물 주기 안내」를 서로 다르게 간추렸어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「내가 더 길게 적었으니 내 것이 맞아.」","correct":true,"mis_target":"K3-2-u1-X16"},{"t":"친구 가 — 「너는 무엇을 하려고 적었어?」","mis":"K3-2-u1-X16"},{"t":"친구 나 — 「나는 물 당번 확인표를 만들려고 셋째만 적었어.」","mis":"K3-2-u1-X17"}],"explanation":["길게 적었다고 맞는 것은 아니에요.","목적부터 물어요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#22','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C12',3,'error','auto','실천 다짐을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X19']::text[],false,'{"seq":22,"concept":"K3-2-u1-C12","difficulty":3,"kind":"error","stem":"실천 다짐을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「“텃밭을 아주 소중히 하겠다.”라고 쓰면 무엇을 할지 다 알 수 있어.」","correct":true,"mis_target":"K3-2-u1-X19"},{"t":"친구 나 — 「언제·무엇을이 들어가야 지키기 쉬워.」","mis":"K3-2-u1-X19"},{"t":"친구 다 — 「남이 할 일이 아니라 내가 할 한 가지를 써.」","mis":"K3-2-u1-X19"}],"explanation":["막연한 다짐은 아무것도 안 하게 돼요.","언제 · 무엇을이 필요해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#23','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C2',4,'mc','auto','「반쪽 우산」과 「돌아선 등」을 함께 읽고 두 시와 모두 이어지는 경험을 고르면 무엇인가요?',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":23,"concept":"K3-2-u1-C2","difficulty":4,"kind":"mc","stem":"「반쪽 우산」과 「돌아선 등」을 함께 읽고 두 시와 모두 이어지는 경험을 고르면 무엇인가요?","options":[{"t":"친구에게 마음을 말로 하지 못하고 행동으로 전했던 일","correct":true},{"t":"비 오는 날 지우개를 산 일","mis":"K3-2-u1-X02"},{"t":"친구와 우산을 바꾼 일","mis":"K3-2-u1-X02"},{"t":"두 시에 나오는 물건을 모두 가진 일","mis":"K3-2-u1-X02"}],"explanation":["두 시의 말하는 이는 모두 말을 못 했어요.","대신 걸음을 맞추고, 지우개를 굴렸어요.","말 대신 행동으로 전한 마음이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#24','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C2',4,'essay','teacher','「반쪽 우산」과 이어지는 내 경험을 언제·어디에서·누구와·그때 마음이 드러나게 쓰고, 그 경험이 시의 어떤 줄과 어떤 마음으로 이어지는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C2","difficulty":4,"kind":"essay","stem":"「반쪽 우산」과 이어지는 내 경험을 언제·어디에서·누구와·그때 마음이 드러나게 쓰고, 그 경험이 시의 어떤 줄과 어떤 마음으로 이어지는지 쓰세요.","answer_guide":{"answer":"예: 지난봄 학교 운동장에서 넘어졌을 때 짝이 보건실까지 부축해 주었다. 고마웠는데 쑥스러워 고맙다는 말을 못 했다. 「나는 아무 말도 못 하고 걸음만 맞추었다」는 줄처럼, 나를 챙겨 준 친구가 고마운데 말이 나오지 않던 마음이 이어진다.","scoring_points":["언제·어디에서·누구와·마음이 드러나게 경험을 썼는가","이어지는 시의 줄을 밝혔는가","겉의 일이 아니라 마음으로 이었는가"]},"explanation":["경험을 또렷하게 적어요.","시에서 이어지는 줄을 찾아요.","같은 마음으로 이어요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_a#25','kor',3,2,'u1','','g3_2_kor_u1_review_a','unit_review','K3-2-u1-C7',4,'essay','teacher','서아나 하율이 가운데 한 인물에게 하고 싶은 말을 쓰세요. 인물이 한 말이나 행동을 짚어 주고, 그 말과 이어지는 내 경험도 함께 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C7","difficulty":4,"kind":"essay","stem":"서아나 하율이 가운데 한 인물에게 하고 싶은 말을 쓰세요. 인물이 한 말이나 행동을 짚어 주고, 그 말과 이어지는 내 경험도 함께 쓰세요.","answer_guide":{"answer":"예: 서아야, 집에 가는 길에 하율이를 불러 세워 「미안해.」라고 말한 건 정말 용기 있는 일이야. 나도 동생 장난감을 고장 내고 하루 동안 말 못 해서 밥맛이 없었는데, 말하고 나니 마음이 가벼워졌어. 너도 그래서 후련했을 것 같아.","scoring_points":["인물에게 하고 싶은 말을 썼는가","인물이 한 말이나 행동을 짚었는가","이어지는 내 경험을 함께 썼는가"]},"explanation":["가르치거나 탓하지 않아요.","인물의 말·행동을 짚어요.","내 경험과 이어서 써요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#1','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C1',1,'mc','auto','친구가 말한 경험 「어제 저녁 우리 집 마당에서 동생과 비눗방울을 불었는데 무지개색이 보여 신났어.」에서 「누구와」에 해당하는 말은 무엇인가요?',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":1,"kind":"mc","stem":"친구가 말한 경험 「어제 저녁 우리 집 마당에서 동생과 비눗방울을 불었는데 무지개색이 보여 신났어.」에서 「누구와」에 해당하는 말은 무엇인가요?","options":[{"t":"동생과","correct":true},{"t":"어제 저녁","mis":"K3-2-u1-X01"},{"t":"우리 집 마당에서","mis":"K3-2-u1-X01"},{"t":"무지개색이 보여","mis":"K3-2-u1-X01"}],"explanation":["함께 있던 사람을 찾아요.","비눗방울을 같이 불었어요.","동생과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#2','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C2',1,'ox','auto','「반쪽 우산」과 이어지는 경험을 떠올리려면 비 오는 날 겪은 일이어야 해요.',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":2,"concept":"K3-2-u1-C2","difficulty":1,"kind":"ox","stem":"「반쪽 우산」과 이어지는 경험을 떠올리려면 비 오는 날 겪은 일이어야 해요.","answer":"X","reason_options":[{"t":"비가 오지 않은 날이라도 고마운 마음이 이어지면 되기 때문에","correct":true},{"t":"시에 비가 나오니 비 오는 날이어야 하기 때문에","mis":"K3-2-u1-X02"}],"mis":"K3-2-u1-X02","explanation":["겉에 나온 것이 같을 필요는 없어요.","마음이 이어지면 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#3','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C3',1,'sa','auto','「반쪽 우산」에서 축축이 젖어 간 곳은 짝꿍의 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"sa","stem":"「반쪽 우산」에서 축축이 젖어 간 곳은 짝꿍의 어디인가요? 두 글자로 쓰세요.","answer":["어깨"],"explanation":["셋째 줄을 읽어요.","「짝꿍 ○○가 축축이」예요.","어깨예요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"},"mis":"K3-2-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#4','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C5',1,'mc','auto','손잡이가 빠진 뒤 서아는 줄넘기를 어떻게 했나요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"mc","stem":"손잡이가 빠진 뒤 서아는 줄넘기를 어떻게 했나요?","options":[{"t":"하율이 사물함에 살금살금 넣어 두었다","correct":true},{"t":"하율이에게 바로 돌려주며 사과했다","mis":"K3-2-u1-X07"},{"t":"집에 가져갔다","mis":"K3-2-u1-X07"},{"t":"선생님께 맡겼다","mis":"K3-2-u1-X07"}],"explanation":["셋째 줄을 읽어요.","살금살금 넣어 두었어요.","하율이 사물함이에요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#5','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C8',1,'mc','auto','「텃밭 물 주기 안내」에서 중요한 내용을 알려 주는 말이 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":5,"concept":"K3-2-u1-C8","difficulty":1,"kind":"mc","stem":"「텃밭 물 주기 안내」에서 중요한 내용을 알려 주는 말이 아닌 것은 무엇인가요?","options":[{"t":"음, 그러니까","correct":true},{"t":"첫째","mis":"K3-2-u1-X11"},{"t":"셋째","mis":"K3-2-u1-X11"},{"t":"가장 중요한 것은","mis":"K3-2-u1-X11"}],"explanation":["뒤에 중요한 내용이 따라오는 말을 찾아요.","「음, 그러니까」는 생각하며 내는 말이에요.","그 말은 표지어가 아니에요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#6','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',1,'ox','auto','간추리기는 줄이는 일이 아니라 다시 정리하는 일이에요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":1,"kind":"ox","stem":"간추리기는 줄이는 일이 아니라 다시 정리하는 일이에요.","answer":"O","reason_options":[{"t":"중요한 것을 골라 차례와 까닭이 드러나게 다시 세우기 때문에","correct":true},{"t":"글자 수만 줄이면 되기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["간추리기는 무엇이 중요한지 생각하는 일이에요.","골라서 다시 세워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#7','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C11',1,'ox','auto','두 친구가 간추린 것이 다르면 둘 중 하나는 틀린 것이에요.',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":1,"kind":"ox","stem":"두 친구가 간추린 것이 다르면 둘 중 하나는 틀린 것이에요.","answer":"X","reason_options":[{"t":"목적이 다르면 남긴 것이 달라질 수 있기 때문에","correct":true},{"t":"같은 것을 들었으면 간추린 것도 똑같아야 하기 때문에","mis":"K3-2-u1-X16"}],"mis":"K3-2-u1-X16","explanation":["다르다고 틀린 것은 아니에요.","목적부터 물어봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#8','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C13',1,'ox','auto','「빻아」를 쓸 때는 소리 나는 대로 「빠아」라고 써요.',ARRAY['K3-2-u1-X21']::text[],false,'{"seq":8,"concept":"K3-2-u1-C13","difficulty":1,"kind":"ox","stem":"「빻아」를 쓸 때는 소리 나는 대로 「빠아」라고 써요.","answer":"X","reason_options":[{"t":"소리만 사라질 뿐 쓸 때는 받침 ㅎ을 그대로 쓰기 때문에","correct":true},{"t":"소리 나는 대로 써야 바른 글이기 때문에","mis":"K3-2-u1-X21"}],"mis":"K3-2-u1-X21","explanation":["소리는 [빠아]예요.","글자는 빻아예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#9','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C2',2,'mc','auto','「반쪽 우산」과 이어지는 경험을 떠올린 친구는 누구인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"mc","stem":"「반쪽 우산」과 이어지는 경험을 떠올린 친구는 누구인가요?","options":[{"t":"「무거운 가방을 같이 들어 준 친구에게 고맙다는 말을 못 했어.」","correct":true},{"t":"「나는 우산이 세 개 있어.」","mis":"K3-2-u1-X02"},{"t":"「비 오는 날 웅덩이를 밟았어.」","mis":"K3-2-u1-X02"},{"t":"「어제 숙제를 다 했어.」","mis":"K3-2-u1-X03"}],"explanation":["우산·비가 나오는 경험을 찾는 게 아니에요.","고마운데 말을 못 한 마음이에요.","가방을 들어 준 친구 경험이에요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#10','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C3',2,'mc','auto','「나는 아무 말도 못 하고 걸음만 맞추었다」에서 짐작할 수 있는 마음으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":10,"concept":"K3-2-u1-C3","difficulty":2,"kind":"mc","stem":"「나는 아무 말도 못 하고 걸음만 맞추었다」에서 짐작할 수 있는 마음으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"고맙지만 쑥스러워 말이 나오지 않았다","correct":true},{"t":"짝꿍이 미워서 말하기 싫었다","mis":"K3-2-u1-X04"},{"t":"비가 와서 신이 났다","mis":"K3-2-u1-X04"},{"t":"빨리 집에 가고 싶어 뛰었다","mis":"K3-2-u1-X07"}],"explanation":["짝꿍은 나를 챙겨 주었어요.","말 대신 걸음을 맞추었어요.","고마운데 쑥스러운 마음이에요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#11','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C6',2,'ox','auto','「하율이가 줄넘기를 들고 고개를 갸웃했다」에서 하율이가 줄넘기가 이상하다고 느꼈다고 짐작할 수 있어요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":11,"concept":"K3-2-u1-C6","difficulty":2,"kind":"ox","stem":"「하율이가 줄넘기를 들고 고개를 갸웃했다」에서 하율이가 줄넘기가 이상하다고 느꼈다고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"빠졌던 손잡이가 있는 줄넘기를 들고 갸웃한 행동이 근거이기 때문에","correct":true},{"t":"하율이의 마음이 글에 그대로 적혀 있기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["갸웃하는 것은 이상할 때 하는 행동이에요.","마음은 글에 없지만 행동이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#12','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C7',2,'mc','auto','하율이에게 하고 싶은 말로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X09','K3-2-u1-X04']::text[],false,'{"seq":12,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"하율이에게 하고 싶은 말로 알맞은 것은 무엇인가요?","options":[{"t":"“손잡이를 끼우며 고맙다고 한 걸 보니 서아 마음을 알아주었구나.”","correct":true},{"t":"“줄넘기를 아무에게나 빌려주면 안 돼.”","mis":"K3-2-u1-X09"},{"t":"“서아에게 화를 냈어야지.”","mis":"K3-2-u1-X09"},{"t":"“너는 원래 착한 아이야.”","mis":"K3-2-u1-X04"}],"explanation":["하율이가 한 말과 행동을 봐요.","손잡이를 끼우며 고맙다고 했어요.","그것을 짚어 주는 말이에요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#13','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C8',2,'mc','auto','「텃밭 물 주기 안내」에서 「셋째」 뒤에 온 중요한 내용은 무엇인가요?',ARRAY['K3-2-u1-X17','K3-2-u1-X13']::text[],false,'{"seq":13,"concept":"K3-2-u1-C8","difficulty":2,"kind":"mc","stem":"「텃밭 물 주기 안내」에서 「셋째」 뒤에 온 중요한 내용은 무엇인가요?","options":[{"t":"물을 준 뒤 기록판에 이름 적기","correct":true},{"t":"아침 수업 전에 주기","mis":"K3-2-u1-X17"},{"t":"뿌리 쪽 흙에 주기","mis":"K3-2-u1-X17"},{"t":"한낮에는 물이 금방 마름","mis":"K3-2-u1-X13"}],"explanation":["「셋째」 뒤를 읽어요.","물을 준 뒤에 할 일이에요.","기록판에 이름 적기예요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#14','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',2,'mc','auto','「빠진 손잡이」에서 일이 일어난 차례대로 바르게 놓은 것은 무엇인가요?',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":14,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「빠진 손잡이」에서 일이 일어난 차례대로 바르게 놓은 것은 무엇인가요?","options":[{"t":"손잡이가 빠짐 → 몰래 사물함에 넣음 → 모른 척함 → 사실대로 말함","correct":true},{"t":"사실대로 말함 → 손잡이가 빠짐 → 몰래 넣음 → 모른 척함","mis":"K3-2-u1-X14"},{"t":"몰래 넣음 → 손잡이가 빠짐 → 사실대로 말함 → 모른 척함","mis":"K3-2-u1-X14"},{"t":"모른 척함 → 사실대로 말함 → 손잡이가 빠짐 → 몰래 넣음","mis":"K3-2-u1-X14"}],"explanation":["체육 시간 → 다음 날 → 집에 가는 길이에요.","빠진 일이 맨 먼저예요.","사실대로 말한 것이 맨 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#15','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C11',2,'match','auto','「텃밭 물 주기 안내」를 간추리는 목적과 남길 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K3-2-u1-C11","difficulty":2,"kind":"match","stem":"「텃밭 물 주기 안내」를 간추리는 목적과 남길 것을 알맞게 이으세요.","pairs":[{"l":"물 당번 확인표를 만들려고","r":"물을 준 뒤 기록판에 이름 적기"},{"l":"처음 물을 주는 동생에게 알려 주려고","r":"언제·어디에 주는지"},{"l":"한 줄 소개판을 만들려고","r":"가장 중요한 한 가지"}],"mis":"K3-2-u1-X17","explanation":["그 글을 읽는 사람을 떠올려요.","목적이 정해지면 남길 것도 정해져요.","목적마다 남길 것을 이어요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#16','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C13',2,'mc','auto','다음 가운데 받침 ㅎ 소리가 나지 않는 말은 무엇인가요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":16,"concept":"K3-2-u1-C13","difficulty":2,"kind":"mc","stem":"다음 가운데 받침 ㅎ 소리가 나지 않는 말은 무엇인가요?","options":[{"t":"빻으니","correct":true},{"t":"빻고","mis":"K3-2-u1-X20"},{"t":"찧지","mis":"K3-2-u1-X20"},{"t":"찧다","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 바로 뒤를 봐요.","「으」는 모음으로 시작해요.","빻으니예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#17','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C4',3,'mc','auto','「반쪽 우산」의 넷째 줄 「나는 아무 말도 못 하고 걸음만 맞추었다」를 내 행동으로 바꿀 때, 다섯째 줄 「“내일 보자”」와 이어지게 바꾼 것은 무엇인가요?',ARRAY['K3-2-u1-X06']::text[],false,'{"seq":17,"concept":"K3-2-u1-C4","difficulty":3,"kind":"mc","stem":"「반쪽 우산」의 넷째 줄 「나는 아무 말도 못 하고 걸음만 맞추었다」를 내 행동으로 바꿀 때, 다섯째 줄 「“내일 보자”」와 이어지게 바꾼 것은 무엇인가요?","options":[{"t":"나는 짝꿍 가방을 대신 들어 주었다","correct":true},{"t":"나는 혼자 앞서 뛰어갔다","mis":"K3-2-u1-X06"},{"t":"나는 우산을 빼앗아 들었다","mis":"K3-2-u1-X06"},{"t":"나는 짝꿍에게 화를 냈다","mis":"K3-2-u1-X06"}],"explanation":["뒤에 「내일 보자」가 와요.","사이가 좋아지는 행동이어야 해요.","가방을 들어 준 행동이 이어져요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#18','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C6',3,'mc','auto','「서아는 마음이 후련했다」에서 짐작할 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":18,"concept":"K3-2-u1-C6","difficulty":3,"kind":"mc","stem":"「서아는 마음이 후련했다」에서 짐작할 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"숨기는 동안 무거웠던 마음이 사실대로 말하자 가벼워졌다","correct":true},{"t":"줄넘기를 다시 빌릴 수 있어 신났다","mis":"K3-2-u1-X04"},{"t":"하율이를 이겨서 기뻤다","mis":"K3-2-u1-X04"},{"t":"하율이가 줄넘기를 버려서 시원했다","mis":"K3-2-u1-X07"}],"explanation":["후련하다는 답답하던 마음이 풀리는 거예요.","앞에서 서아는 내내 불편했어요.","말하고 나니 가벼워졌어요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#19','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C8',3,'mc','auto','「텃밭 물 주기 안내」를 간추린 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X07']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"「텃밭 물 주기 안내」를 간추린 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"① 아침 수업 전에 ② 뿌리 쪽 흙에 천천히 ③ 준 뒤 기록판에 이름 — 가장 중요: 흙을 눌러 보고 마른 날에만","correct":true},{"t":"첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요. 둘째, …","mis":"K3-2-u1-X12"},{"t":"선생님이 「음, 그러니까」라고 하셔서 웃겼다","mis":"K3-2-u1-X13"},{"t":"물은 많이 줄수록 좋다","mis":"K3-2-u1-X07"}],"explanation":["표지어 뒤의 내용을 번호로 나누어요.","옮겨 쓰기·재미는 아니에요.","안내에 없는 말은 넣지 않아요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#20','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',3,'mc','auto','「빠진 손잡이」를 간추린 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X14']::text[],false,'{"seq":20,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"「빠진 손잡이」를 간추린 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"서아는 빌린 줄넘기의 손잡이를 빠뜨리고 조마조마해서 몰래 돌려놓았다. 내내 마음이 불편했던 서아가 사실대로 사과하자 하율이가 고맙다고 해 마음이 후련했다.","correct":true},{"t":"체육 시간에 서아는 하율이의 줄넘기를 빌렸다. 힘껏 돌리다가 손잡이가 툭 빠졌다.","mis":"K3-2-u1-X12"},{"t":"서아가 공기놀이를 했는데 재미없었다는 부분이 제일 재미있었다.","mis":"K3-2-u1-X13"},{"t":"서아는 하율이에게 사과했다. 그 전에 손잡이가 빠졌다.","mis":"K3-2-u1-X14"}],"explanation":["차례와 원인·결과가 다 들어가야 해요.","옮겨 쓰기 · 재미만 남기기는 아니에요.","한 편으로 읽히는 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#21','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C11',3,'mc','auto','친구 하나는 「아침 수업 전 · 뿌리 쪽 흙 · 기록판」을, 친구 둘은 「흙을 눌러 보고 마른 날에만」을 남겼어요. 다르게 간추린 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":21,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"친구 하나는 「아침 수업 전 · 뿌리 쪽 흙 · 기록판」을, 친구 둘은 「흙을 눌러 보고 마른 날에만」을 남겼어요. 다르게 간추린 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"하나는 물 주는 방법을 모두 알려 주려고, 둘은 한 줄 소개판에 가장 중요한 것만 넣으려고 간추렸다","correct":true},{"t":"둘 다 잘못 들었다","mis":"K3-2-u1-X16"},{"t":"하나가 더 많이 적었으니 하나만 맞다","mis":"K3-2-u1-X16"},{"t":"간추리기에는 하나의 정답이 있다","mis":"K3-2-u1-X16"}],"explanation":["둘 다 안내에 있는 내용이에요.","남긴 것을 보면 목적이 보여요.","목적이 달라서 남긴 것이 달라요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#22','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C13',3,'mc','auto','「빻고」와 「빻아」의 소리를 바르게 설명한 것은 무엇인가요?',ARRAY['K3-2-u1-X20']::text[],false,'{"seq":22,"concept":"K3-2-u1-C13","difficulty":3,"kind":"mc","stem":"「빻고」와 「빻아」의 소리를 바르게 설명한 것은 무엇인가요?","options":[{"t":"「빻아」는 뒤가 모음이라 ㅎ 소리가 나지 않고, 「빻고」는 뒤가 자음이라 그렇지 않다","correct":true},{"t":"둘 다 ㅎ 소리가 나지 않는다","mis":"K3-2-u1-X20"},{"t":"둘 다 ㅎ 소리를 그대로 낸다","mis":"K3-2-u1-X20"},{"t":"「빻고」만 ㅎ 소리가 나지 않는다","mis":"K3-2-u1-X20"}],"explanation":["받침 ㅎ 바로 뒤를 봐요.","아는 모음, 고는 자음으로 시작해요.","모음 앞에서만 사라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#23','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C10',4,'mc','auto','「빠진 손잡이」에서 「그날 내내 공기놀이도 재미가 없었다」는 이야기에서 어떤 구실을 하나요?',ARRAY['K3-2-u1-X13','K3-2-u1-X04','K3-2-u1-X14']::text[],false,'{"seq":23,"concept":"K3-2-u1-C10","difficulty":4,"kind":"mc","stem":"「빠진 손잡이」에서 「그날 내내 공기놀이도 재미가 없었다」는 이야기에서 어떤 구실을 하나요?","options":[{"t":"숨긴 마음이 계속 불편했다는 것을 보여 주어 서아가 사실대로 말하게 된 까닭이 된다","correct":true},{"t":"이야기와 상관없는 재미있는 장면이다","mis":"K3-2-u1-X13"},{"t":"서아가 공기놀이를 싫어한다는 것을 알려 준다","mis":"K3-2-u1-X04"},{"t":"이야기가 끝났음을 알려 준다","mis":"K3-2-u1-X14"}],"explanation":["그 뒤에 서아가 무엇을 했나요?","하율이를 불러 세워 사과했어요.","불편한 마음이 사과의 원인이에요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#24','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C6',4,'essay','teacher','「빠진 손잡이」 ①에서 서아의 마음이 드러나는 장면 두 곳을 찾아, 장면마다 서아의 마음을 짐작하고 그렇게 짐작한 근거를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C6","difficulty":4,"kind":"essay","stem":"「빠진 손잡이」 ①에서 서아의 마음이 드러나는 장면 두 곳을 찾아, 장면마다 서아의 마음을 짐작하고 그렇게 짐작한 근거를 쓰세요.","answer_guide":{"answer":"예: 손잡이가 빠졌을 때 서아는 빌린 물건을 망가뜨려 걱정되었을 것이다. 「가슴이 조마조마했다」고 했기 때문이다. 하율이가 고개를 갸웃할 때 서아는 들킬까 봐 마음이 불편했을 것이다. 모른 척 고개를 숙이고 그날 내내 공기놀이도 재미가 없었기 때문이다.","scoring_points":["서아의 마음이 드러나는 장면 두 곳을 찾았는가","장면마다 마음을 짐작했는가","이야기 속 말·행동을 근거로 들었는가"]},"explanation":["장면을 먼저 찾아요.","마음을 짐작해요.","근거는 이야기 속 행동이에요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_b#25','kor',3,2,'u1','','g3_2_kor_u1_review_b','unit_review','K3-2-u1-C8',4,'essay','teacher','「텃밭 물 주기 안내」를 간추리며 듣는다고 생각하고, 듣기 전·듣는 중·들은 후에 할 일을 안내 내용에 맞추어 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C8","difficulty":4,"kind":"essay","stem":"「텃밭 물 주기 안내」를 간추리며 듣는다고 생각하고, 듣기 전·듣는 중·들은 후에 할 일을 안내 내용에 맞추어 하나씩 쓰세요.","answer_guide":{"answer":"예: 듣기 전 — 「텃밭 물 주기 안내」라는 제목을 보고 물을 언제, 어떻게 주는지 알려고 듣기로 정한다. 듣는 중 — 「첫째」, 「둘째」, 「셋째」, 「가장 중요한 것은」이 들리면 바로 뒤의 말을 번호를 붙여 적는다. 들은 후 — 적은 것을 번호대로 정리하고, 비가 온 다음 날에도 물을 주어야 하는지 궁금한 점을 적는다.","scoring_points":["세 걸음으로 나누어 썼는가","걸음마다 안내 내용에 맞는 할 일을 썼는가","목적·표지어·정리와 궁금한 점이 드러나는가"]},"explanation":["듣기 전은 목적과 예상이에요.","듣는 중은 표지어예요.","들은 후는 정리와 궁금한 점이에요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#1','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C1',1,'ox','auto','경험을 떠올릴 때 그때 입은 옷의 값까지 떠올려야 해요.',ARRAY['K3-2-u1-X01']::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":1,"kind":"ox","stem":"경험을 떠올릴 때 그때 입은 옷의 값까지 떠올려야 해요.","answer":"X","reason_options":[{"t":"언제·어디에서·누구와·본 것·마음이면 경험이 또렷해지고 옷값은 필요 없기 때문에","correct":true},{"t":"옷값을 모르면 경험을 말할 수 없기 때문에","mis":"K3-2-u1-X01"}],"mis":"K3-2-u1-X01","explanation":["남에게 말해 줄 때 필요한 것을 떠올려요.","옷값은 없어도 알아들어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#2','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C2',1,'mc','auto','겪은 일이 달라도 작품과 이어질 수 있게 해 주는 것은 무엇인가요?',ARRAY['K3-2-u1-X02','K3-2-u1-X03']::text[],false,'{"seq":2,"concept":"K3-2-u1-C2","difficulty":1,"kind":"mc","stem":"겪은 일이 달라도 작품과 이어질 수 있게 해 주는 것은 무엇인가요?","options":[{"t":"그때 든 생각이나 느낌","correct":true},{"t":"겪은 날짜","mis":"K3-2-u1-X02"},{"t":"나온 물건의 이름","mis":"K3-2-u1-X02"},{"t":"아무 일이나","mis":"K3-2-u1-X03"}],"explanation":["1차시와 13차시에 만난 물음이에요.","겪은 일이 아니라 마음이에요.","생각이나 느낌이 이어지면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#3','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C3',1,'ox','auto','「짝꿍 어깨가 축축이 젖어 갔다」를 보면 짝꿍이 자기보다 나를 더 챙겼다고 짐작할 수 있어요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"ox","stem":"「짝꿍 어깨가 축축이 젖어 갔다」를 보면 짝꿍이 자기보다 나를 더 챙겼다고 짐작할 수 있어요.","answer":"O","reason_options":[{"t":"우산을 내 쪽으로 기울여 자기 어깨가 젖은 행동이 근거이기 때문에","correct":true},{"t":"시에 「나를 챙겼다」라고 그대로 적혀 있기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["시에 마음이 그대로 적혀 있지 않아요.","우산을 기울인 행동을 봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#4','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C5',1,'sa','auto','「빠진 손잡이」 ①에서 「소리가 나지 않게 가만가만 움직이는 모양」을 나타내는 말을 찾아 네 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"sa","stem":"「빠진 손잡이」 ①에서 「소리가 나지 않게 가만가만 움직이는 모양」을 나타내는 말을 찾아 네 글자로 쓰세요.","answer":["살금살금"],"explanation":["사물함에 넣는 줄을 봐요.","「○○○○ 넣어 두었다」예요.","살금살금이에요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"},"mis":"K3-2-u1-X08"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#5','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C8',1,'ox','auto','다 듣고 나서는 번호나 화살표 같은 기호로 나누어 정리하면 좋아요.',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":5,"concept":"K3-2-u1-C8","difficulty":1,"kind":"ox","stem":"다 듣고 나서는 번호나 화살표 같은 기호로 나누어 정리하면 좋아요.","answer":"O","reason_options":[{"t":"기호로 나누면 중요한 내용이 한눈에 보이기 때문에","correct":true},{"t":"기호는 듣기 전에만 쓰는 것이기 때문에","mis":"K3-2-u1-X10"}],"mis":"K3-2-u1-X10","explanation":["들은 후에 하는 일이에요.","기호로 나누어 정리해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#6','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',1,'mc','auto','「빠진 손잡이」에서 서아가 마음이 후련해진 까닭은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"「빠진 손잡이」에서 서아가 마음이 후련해진 까닭은 무엇인가요?","options":[{"t":"하율이에게 사실대로 말하고 사과했기 때문에","correct":true},{"t":"줄넘기를 새로 샀기 때문에","mis":"K3-2-u1-X07"},{"t":"하율이가 모른 척해 주었기 때문에","mis":"K3-2-u1-X07"},{"t":"공기놀이에서 이겼기 때문에","mis":"K3-2-u1-X07"}],"explanation":["원인과 결과를 찾아요.","서아가 「미안해.」라고 말했어요.","사실대로 말해서 후련해졌어요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#7','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',1,'mc','auto','듣기 전에 목적을 정하면 좋은 점은 무엇인가요?',ARRAY['K3-2-u1-X10','K3-2-u1-X12']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"듣기 전에 목적을 정하면 좋은 점은 무엇인가요?","options":[{"t":"무엇을 적을지가 정해진다","correct":true},{"t":"들을 필요가 없어진다","mis":"K3-2-u1-X10"},{"t":"말하는 사람이 천천히 말한다","mis":"K3-2-u1-X10"},{"t":"모든 말을 다 받아 적을 수 있다","mis":"K3-2-u1-X12"}],"explanation":["목적은 듣기 전에 정해요.","그러면 적을 것이 보여요.","무엇을 적을지 정해져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#8','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C14',1,'mc','auto','「사과 · 배 · 감」을 묶는 이름은 무엇인가요?',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":8,"concept":"K3-2-u1-C14","difficulty":1,"kind":"mc","stem":"「사과 · 배 · 감」을 묶는 이름은 무엇인가요?","options":[{"t":"과일","correct":true},{"t":"채소","mis":"K3-2-u1-X22"},{"t":"사과","mis":"K3-2-u1-X22"},{"t":"계절","mis":"K3-2-u1-X22"}],"explanation":["셋을 한마디로 불러요.","나무에 열리는 먹을거리예요.","과일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#9','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C2',2,'ox','auto','「나는 줄넘기를 해 본 적이 없으니 「빠진 손잡이」와 이어지는 경험이 없어.」라는 생각은 알맞아요.',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"ox","stem":"「나는 줄넘기를 해 본 적이 없으니 「빠진 손잡이」와 이어지는 경험이 없어.」라는 생각은 알맞아요.","answer":"X","reason_options":[{"t":"줄넘기가 아니어도 잘못을 사실대로 말하고 후련했던 경험이면 이어지기 때문에","correct":true},{"t":"이야기와 같은 물건이 나와야 이어지기 때문에","mis":"K3-2-u1-X02"}],"mis":"K3-2-u1-X02","explanation":["같은 물건이 아니라 같은 마음이에요.","잘못을 말하고 후련했던 일을 떠올려요.","그래서 X예요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#10','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C3',2,'ox','auto','「반쪽 우산」에는 말하는 이의 마음이 「고맙다」라고 그대로 적혀 있어요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":10,"concept":"K3-2-u1-C3","difficulty":2,"kind":"ox","stem":"「반쪽 우산」에는 말하는 이의 마음이 「고맙다」라고 그대로 적혀 있어요.","answer":"X","reason_options":[{"t":"시에는 마음이 그대로 적혀 있지 않아 걸음을 맞춘 것 같은 행동으로 짐작해야 하기 때문에","correct":true},{"t":"마음은 늘 시에 그대로 쓰여 있기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["시 어디에도 「고맙다」는 없어요.","행동으로 짐작해요.","그래서 X예요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#11','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C6',2,'mc','auto','근거 있는 짐작이 되려면 어떻게 해야 하나요?',ARRAY['K3-2-u1-X05','K3-2-u1-X04']::text[],false,'{"seq":11,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"근거 있는 짐작이 되려면 어떻게 해야 하나요?","options":[{"t":"이야기에 나온 상황·말·행동에서 근거를 댄다","correct":true},{"t":"누구나 똑같이 짐작해야 한다","mis":"K3-2-u1-X05"},{"t":"글에 없어도 그럴듯하면 된다","mis":"K3-2-u1-X04"},{"t":"내 기분과 같으면 된다","mis":"K3-2-u1-X04"}],"explanation":["짐작은 사람마다 달라도 돼요.","근거는 이야기에서 나와요.","상황·말·행동이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#12','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C7',2,'ox','auto','인물에게 하고 싶은 말은 인물이 무엇을 잘못했는지 가르쳐 주는 말이 가장 좋아요.',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":12,"concept":"K3-2-u1-C7","difficulty":2,"kind":"ox","stem":"인물에게 하고 싶은 말은 인물이 무엇을 잘못했는지 가르쳐 주는 말이 가장 좋아요.","answer":"X","reason_options":[{"t":"인물의 말·행동을 짚어 마음을 알아주는 말이 감상을 깊게 하기 때문에","correct":true},{"t":"인물은 늘 잘못을 배워야 하기 때문에","mis":"K3-2-u1-X09"}],"mis":"K3-2-u1-X09","explanation":["훈계 한 줄은 감상이 아니에요.","인물의 말·행동을 짚어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#13','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C8',2,'ox','auto','「텃밭 물 주기 안내」의 「음, 그러니까」는 중요한 내용을 알려 주는 말이에요.',ARRAY['K3-2-u1-X11']::text[],false,'{"seq":13,"concept":"K3-2-u1-C8","difficulty":2,"kind":"ox","stem":"「텃밭 물 주기 안내」의 「음, 그러니까」는 중요한 내용을 알려 주는 말이에요.","answer":"X","reason_options":[{"t":"「음, 그러니까」는 생각하며 내는 말이고 중요한 것을 알려 준 말은 뒤의 「가장 중요한 것은」이기 때문에","correct":true},{"t":"안내하는 사람이 한 말은 모두 중요하기 때문에","mis":"K3-2-u1-X11"}],"mis":"K3-2-u1-X11","explanation":["같은 줄에 두 말이 있어요.","표지어는 「가장 중요한 것은」이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#14','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',2,'mc','auto','「빠진 손잡이」를 간추릴 때 뼈대가 아닌 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X14']::text[],false,'{"seq":14,"concept":"K3-2-u1-C10","difficulty":2,"kind":"mc","stem":"「빠진 손잡이」를 간추릴 때 뼈대가 아닌 것은 무엇인가요?","options":[{"t":"줄넘기를 빌린 때가 체육 시간이었다","correct":true},{"t":"손잡이가 빠졌다","mis":"K3-2-u1-X13"},{"t":"서아가 몰래 넣어 두었다","mis":"K3-2-u1-X14"},{"t":"서아가 사실대로 사과했다","mis":"K3-2-u1-X14"}],"explanation":["그 일을 빼도 이야기가 이어지나요?","체육 시간은 빼도 이어져요.","나머지는 빼면 이어지지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#15','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',2,'ox','auto','같은 안내를 들어도 물 당번 확인표를 만들 때와 동생에게 알려 줄 때 남길 것이 달라요.',ARRAY['K3-2-u1-X16']::text[],false,'{"seq":15,"concept":"K3-2-u1-C11","difficulty":2,"kind":"ox","stem":"같은 안내를 들어도 물 당번 확인표를 만들 때와 동생에게 알려 줄 때 남길 것이 달라요.","answer":"O","reason_options":[{"t":"무엇을 하려고 간추리는지에 따라 필요한 내용이 다르기 때문에","correct":true},{"t":"바르게 간추린 것은 언제나 하나뿐이기 때문에","mis":"K3-2-u1-X16"}],"mis":"K3-2-u1-X16","explanation":["목적이 다르면 남길 것도 달라요.","그래서 하나의 정답이 없어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#16','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C14',2,'ox','auto','「봄 · 여름 · 가을」을 묶는 이름은 「날씨」예요.',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":16,"concept":"K3-2-u1-C14","difficulty":2,"kind":"ox","stem":"「봄 · 여름 · 가을」을 묶는 이름은 「날씨」예요.","answer":"X","reason_options":[{"t":"봄·여름·가을은 계절의 이름이기 때문에","correct":true},{"t":"날씨가 바뀌는 때라서 날씨로 묶기 때문에","mis":"K3-2-u1-X22"}],"mis":"K3-2-u1-X22","explanation":["봄·여름·가을·겨울을 떠올려요.","이것들은 계절이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#17','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C3',3,'error','auto','「반쪽 우산」에서 말하는 이의 마음을 짐작했어요. 근거가 알맞지 않은 친구는 누구인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":17,"concept":"K3-2-u1-C3","difficulty":3,"kind":"error","stem":"「반쪽 우산」에서 말하는 이의 마음을 짐작했어요. 근거가 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 가 — 「제목이 「반쪽 우산」이니 말하는 이는 반쪽만 기뻤을 거야.」","correct":true,"mis_target":"K3-2-u1-X04"},{"t":"친구 나 — 「걸음만 맞춘 걸 보니 말은 못 해도 고마웠나 봐.」","mis":"K3-2-u1-X04"},{"t":"친구 다 — 「「내일 보자」가 오래 남은 걸 보니 그 말이 좋았나 봐.」","mis":"K3-2-u1-X04"}],"explanation":["근거는 시에 나온 말과 행동이에요.","제목의 낱말만으로는 근거가 안 돼요.","친구 가가 알맞지 않아요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#18','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C7',3,'error','auto','인물에게 하고 싶은 말을 두고 친구들이 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K3-2-u1-X09']::text[],false,'{"seq":18,"concept":"K3-2-u1-C7","difficulty":3,"kind":"error","stem":"인물에게 하고 싶은 말을 두고 친구들이 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「“하율아, 서아한테 왜 화 안 냈어? 화냈어야지.”」","correct":true,"mis_target":"K3-2-u1-X09"},{"t":"친구 가 — 「“서아야, 불러 세울 때 떨렸지? 용기 낸 거 멋져.”」","mis":"K3-2-u1-X09"},{"t":"친구 다 — 「“하율아, 「고마워」라고 해 준 덕분에 서아가 후련했겠다.”」","mis":"K3-2-u1-X09"}],"explanation":["하고 싶은 말은 마음을 알아주는 말이에요.","따지거나 가르치는 말이 아니에요.","친구 나가 알맞지 않아요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#19','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C8',3,'mc','auto','「텃밭 물 주기 안내」를 듣고 더 궁금한 점으로 적기에 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X11','K3-2-u1-X13']::text[],false,'{"seq":19,"concept":"K3-2-u1-C8","difficulty":3,"kind":"mc","stem":"「텃밭 물 주기 안내」를 듣고 더 궁금한 점으로 적기에 가장 알맞은 것은 무엇인가요?","options":[{"t":"비가 온 다음 날에도 물을 주어야 할까?","correct":true},{"t":"첫째는 무엇이었지?","mis":"K3-2-u1-X11"},{"t":"안내한 선생님은 무슨 옷을 입었을까?","mis":"K3-2-u1-X13"},{"t":"기록판은 몇 글자일까?","mis":"K3-2-u1-X13"}],"explanation":["궁금한 점은 더 알아볼 거리예요.","안내 내용과 이어져야 해요.","비 온 다음 날이 알맞아요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#20','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',3,'mc','auto','서아의 특성으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":20,"concept":"K3-2-u1-C10","difficulty":3,"kind":"mc","stem":"서아의 특성으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"잘못을 숨기려다가도 결국 사실대로 말하는 용기가 있다","correct":true},{"t":"물건을 일부러 망가뜨리는 아이다","mis":"K3-2-u1-X07"},{"t":"처음부터 아무 걱정이 없는 아이다","mis":"K3-2-u1-X07"},{"t":"친구를 싫어하는 아이다","mis":"K3-2-u1-X07"}],"explanation":["서아의 행동을 처음부터 끝까지 봐요.","숨겼다가 불러 세워 사과했어요.","용기를 낸 아이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#21','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',3,'mc','auto','듣고 글로 정리하는 차례로 바른 것은 무엇인가요?',ARRAY['K3-2-u1-X10']::text[],false,'{"seq":21,"concept":"K3-2-u1-C11","difficulty":3,"kind":"mc","stem":"듣고 글로 정리하는 차례로 바른 것은 무엇인가요?","options":[{"t":"목적 정하기 → 나누어 간단히 적기 → 칸 채우고 빠진 것 찾기 → 한 편의 글로 쓰기","correct":true},{"t":"한 편의 글로 쓰기 → 목적 정하기 → 나누어 적기 → 빠진 것 찾기","mis":"K3-2-u1-X10"},{"t":"나누어 적기 → 한 편의 글로 쓰기 → 목적 정하기 → 빠진 것 찾기","mis":"K3-2-u1-X10"},{"t":"빠진 것 찾기 → 목적 정하기 → 한 편의 글로 쓰기 → 나누어 적기","mis":"K3-2-u1-X10"}],"explanation":["목적은 듣기 전에 정해요.","들으며 적고, 들은 뒤 칸을 채워요.","맨 끝에 한 편의 글로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#22','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C13',3,'error','auto','받침 ㅎ의 소리와 쓰기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K3-2-u1-X20','K3-2-u1-X21']::text[],false,'{"seq":22,"concept":"K3-2-u1-C13","difficulty":3,"kind":"error","stem":"받침 ㅎ의 소리와 쓰기를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「받침 ㅎ은 어디에서든 소리 내지 않아.」","correct":true,"mis_target":"K3-2-u1-X20"},{"t":"친구 가 — 「모음 앞에서만 ㅎ 소리가 사라져.」","mis":"K3-2-u1-X20"},{"t":"친구 다 — 「소리가 사라져도 쓸 때는 받침 ㅎ을 그대로 써.」","mis":"K3-2-u1-X21"}],"explanation":["「빻고」를 떠올려요.","뒤가 자음이면 그냥 사라지지 않아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#23','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C11',4,'mc','auto','처음 물을 주는 동생에게 알려 주려고 「텃밭 물 주기 안내」를 간추린 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X12','K3-2-u1-X13','K3-2-u1-X07']::text[],false,'{"seq":23,"concept":"K3-2-u1-C11","difficulty":4,"kind":"mc","stem":"처음 물을 주는 동생에게 알려 주려고 「텃밭 물 주기 안내」를 간추린 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"아침 수업 전에 흙을 손가락으로 눌러 봐서 말랐으면 뿌리 쪽 흙에 천천히 주고, 준 뒤에는 기록판에 이름을 적어.","correct":true},{"t":"첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요. 둘째, 잎이 아니라 …","mis":"K3-2-u1-X12"},{"t":"선생님이 「음, 그러니까」라고 하셔서 재미있었어.","mis":"K3-2-u1-X13"},{"t":"물은 많이 줄수록 잘 자라.","mis":"K3-2-u1-X07"}],"explanation":["동생이 직접 물을 줄 수 있어야 해요.","언제 · 어디에 · 가장 중요한 것 · 준 뒤 할 일이에요.","동생이 알아듣게 다시 정리해요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#24','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C10',4,'essay','teacher','「빠진 손잡이」를 일이 일어난 차례에 따라 세 문장으로 간추리세요. 왜 그랬고 그래서 어떻게 되었는지가 드러나게 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C10","difficulty":4,"kind":"essay","stem":"「빠진 손잡이」를 일이 일어난 차례에 따라 세 문장으로 간추리세요. 왜 그랬고 그래서 어떻게 되었는지가 드러나게 쓰세요.","answer_guide":{"answer":"예: 서아는 하율이에게 빌린 줄넘기의 손잡이를 빠뜨리고 조마조마해서 몰래 사물함에 넣어 두었다. 하율이가 이상해하자 서아는 모른 척했지만 하루 내내 마음이 불편했다. 그래서 집에 가는 길에 사실대로 사과했고, 하율이가 고맙다고 하자 마음이 후련해졌다.","scoring_points":["세 문장으로 차례에 맞게 간추렸는가","왜 그랬는지(원인)를 썼는가","그래서 어떻게 되었는지(결과)를 썼는가"]},"explanation":["차례대로 써요.","조마조마한 마음이 원인이에요.","후련해진 것이 결과예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_c#25','kor',3,2,'u1','','g3_2_kor_u1_review_c','unit_review','K3-2-u1-C12',4,'essay','teacher','「텃밭 물 주기 안내」 가운데 내가 오늘부터 할 한 가지를 골라 언제·무엇을이 드러나게 실천 다짐을 쓰고, 왜 그 다짐을 골랐는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C12","difficulty":4,"kind":"essay","stem":"「텃밭 물 주기 안내」 가운데 내가 오늘부터 할 한 가지를 골라 언제·무엇을이 드러나게 실천 다짐을 쓰고, 왜 그 다짐을 골랐는지 쓰세요.","answer_guide":{"answer":"예: 다짐 — 우리 반 물 주기 날 아침에 물을 주기 전에 흙을 손가락으로 눌러 보고 말랐을 때만 준다. 까닭 — 안내에서 가장 중요한 것이라고 했고, 나는 지난번에 젖은 흙에도 물을 또 준 적이 있어서 내가 꼭 지켜야 할 일이기 때문이다.","scoring_points":["내가 할 한 가지를 골랐는가","언제·무엇을이 드러나게 썼는가","그 다짐을 고른 까닭을 썼는가"]},"explanation":["모두 잘하겠다는 다짐은 아니에요.","내가 할 한 가지예요.","언제 · 무엇을을 넣어요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#1','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C1',1,'sa','auto','경험을 떠올리는 틀 「언제 · 어디에서 · 무엇을 · ○○○」에서 ○○○에 들어갈 세 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K3-2-u1-C1","difficulty":1,"kind":"sa","stem":"경험을 떠올리는 틀 「언제 · 어디에서 · 무엇을 · ○○○」에서 ○○○에 들어갈 세 글자를 쓰세요.","answer":["누구와"],"explanation":["함께 있던 사람이에요.","「누구」에 「와」가 붙어요.","누구와예요."],"mis":"K3-2-u1-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#2','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C2',1,'mc','auto','「빠진 손잡이」 ①과 이어지는 경험은 어느 것인가요?',ARRAY['K3-2-u1-X02']::text[],false,'{"seq":2,"concept":"K3-2-u1-C2","difficulty":1,"kind":"mc","stem":"「빠진 손잡이」 ①과 이어지는 경험은 어느 것인가요?","options":[{"t":"친구 물건을 망가뜨리고 말할까 말까 조마조마했던 일","correct":true},{"t":"체육 시간에 줄넘기를 한 일","mis":"K3-2-u1-X02"},{"t":"사물함을 정리한 일","mis":"K3-2-u1-X02"},{"t":"공기놀이를 한 일","mis":"K3-2-u1-X02"}],"explanation":["줄넘기나 사물함을 찾는 게 아니에요.","서아의 조마조마한 마음을 찾아요.","망가뜨리고 걱정한 일이에요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#3','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C3',1,'mc','auto','「반쪽 우산」에서 말하는 이의 마음을 짐작할 근거로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":3,"concept":"K3-2-u1-C3","difficulty":1,"kind":"mc","stem":"「반쪽 우산」에서 말하는 이의 마음을 짐작할 근거로 알맞은 것은 무엇인가요?","options":[{"t":"아무 말도 못 하고 걸음만 맞추었다","correct":true},{"t":"제목에 「우산」이 들어 있다","mis":"K3-2-u1-X04"},{"t":"시를 읽는 지금 내 기분","mis":"K3-2-u1-X04"},{"t":"비는 차갑다는 것","mis":"K3-2-u1-X04"}],"explanation":["시에 나온 행동을 찾아요.","말하는 이가 한 일이에요.","걸음을 맞춘 행동이 근거예요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#4','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C5',1,'ox','auto','서아는 그날 내내 공기놀이를 재미있게 했어요.',ARRAY['K3-2-u1-X07']::text[],false,'{"seq":4,"concept":"K3-2-u1-C5","difficulty":1,"kind":"ox","stem":"서아는 그날 내내 공기놀이를 재미있게 했어요.","answer":"X","reason_options":[{"t":"마음이 불편해 그날 내내 공기놀이도 재미가 없었다고 했기 때문에","correct":true},{"t":"친구들과 놀았으니 재미있었을 것이기 때문에","mis":"K3-2-u1-X07"}],"mis":"K3-2-u1-X07","explanation":["마지막 줄을 읽어요.","「재미가 없었다」고 했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#5','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C8',1,'sa','auto','안내에서 「가장 중요한 것은」 뒤에 흙을 무엇으로 눌러 보라고 했나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"K3-2-u1-C8","difficulty":1,"kind":"sa","stem":"안내에서 「가장 중요한 것은」 뒤에 흙을 무엇으로 눌러 보라고 했나요? 세 글자로 쓰세요.","answer":["손가락"],"explanation":["마지막 줄을 읽어요.","표지어 뒤에 중요한 것이 와요.","손가락이에요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"},"mis":"K3-2-u1-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#6','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',1,'mc','auto','재미있는 것과 중요한 것에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X13','K3-2-u1-X14']::text[],false,'{"seq":6,"concept":"K3-2-u1-C10","difficulty":1,"kind":"mc","stem":"재미있는 것과 중요한 것에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"재미있는 부분이 꼭 이야기의 뼈대는 아니다","correct":true},{"t":"재미있는 부분이 언제나 가장 중요하다","mis":"K3-2-u1-X13"},{"t":"재미없는 부분은 모두 틀린 내용이다","mis":"K3-2-u1-X13"},{"t":"중요한 내용은 늘 맨 끝에만 나온다","mis":"K3-2-u1-X14"}],"explanation":["재미있는 것 ≠ 중요한 것이에요.","뼈대가 중요해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#7','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C11',1,'mc','auto','내가 텃밭에 물을 줄 때 지키려고 「텃밭 물 주기 안내」를 간추린다면 무엇을 남겨야 할까요?',ARRAY['K3-2-u1-X13','K3-2-u1-X11']::text[],false,'{"seq":7,"concept":"K3-2-u1-C11","difficulty":1,"kind":"mc","stem":"내가 텃밭에 물을 줄 때 지키려고 「텃밭 물 주기 안내」를 간추린다면 무엇을 남겨야 할까요?","options":[{"t":"언제·어디에 주는지, 마른 날에만 준다는 것, 주고 나서 할 일","correct":true},{"t":"안내한 선생님의 목소리","mis":"K3-2-u1-X13"},{"t":"「음, 그러니까」라고 말한 곳","mis":"K3-2-u1-X11"},{"t":"안내가 몇 줄이었는지","mis":"K3-2-u1-X13"}],"explanation":["내가 직접 물을 줄 거예요.","그러려면 방법이 남아야 해요.","언제 · 어디에 · 마른 날에만 · 주고 나서예요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#8','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C14',1,'sa','auto','「연필 · 지우개 · 자」를 한 이름으로 묶어 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K3-2-u1-C14","difficulty":1,"kind":"sa","stem":"「연필 · 지우개 · 자」를 한 이름으로 묶어 세 글자로 쓰세요.","answer":["학용품"],"explanation":["공부할 때 쓰는 물건이에요.","세 글자예요.","학용품이에요."],"mis":"K3-2-u1-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#9','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C2',2,'match','auto','작품과 이어지는 경험을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"K3-2-u1-C2","difficulty":2,"kind":"match","stem":"작품과 이어지는 경험을 알맞게 이으세요.","pairs":[{"l":"「반쪽 우산」","r":"친구가 나를 챙겨 주어 고마운데 말을 못 한 일"},{"l":"「빠진 손잡이」","r":"잘못을 숨겼다가 사실대로 말하고 후련했던 일"},{"l":"「돌아선 등」","r":"다툰 뒤 말 대신 행동으로 화해한 일"}],"mis":"K3-2-u1-X02","explanation":["작품마다 인물의 마음을 떠올려요.","고마움 · 후련함 · 말 없는 화해예요.","마음이 이어지는 짝을 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#10','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C3',2,'match','auto','「반쪽 우산」의 행동과 짐작한 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"K3-2-u1-C3","difficulty":2,"kind":"match","stem":"「반쪽 우산」의 행동과 짐작한 마음을 알맞게 이으세요.","pairs":[{"l":"짝꿍이 우산을 내 쪽으로 기울였다","r":"나를 먼저 챙겨 주고 싶다"},{"l":"아무 말도 못 하고 걸음만 맞추었다","r":"고마운데 쑥스럽다"},{"l":"「내일 보자」 그 한마디가 오래 남았다","r":"짝꿍과 더 가까워져 기쁘다"}],"mis":"K3-2-u1-X04","explanation":["누가 한 행동인지 먼저 봐요.","행동이 마음을 알려 줘요.","행동마다 마음을 이어요."],"asset":{"type":"passage","lines":["갑자기 비가 내렸다 우산은 하나뿐","짝꿍이 우산을 내 쪽으로 기울였다","짝꿍 어깨가 축축이 젖어 갔다","나는 아무 말도 못 하고 걸음만 맞추었다","집 앞에서 “내일 보자” 그 한마디가 오래 남았다"],"title":"시 「반쪽 우산」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#11','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C6',2,'mc','auto','하율이가 「말해 줘서 고마워.」라고 한 것에서 짐작할 수 있는 하율이의 마음은 무엇인가요?',ARRAY['K3-2-u1-X04','K3-2-u1-X07']::text[],false,'{"seq":11,"concept":"K3-2-u1-C6","difficulty":2,"kind":"mc","stem":"하율이가 「말해 줘서 고마워.」라고 한 것에서 짐작할 수 있는 하율이의 마음은 무엇인가요?","options":[{"t":"줄넘기보다 서아가 솔직하게 말해 준 것이 반가웠다","correct":true},{"t":"줄넘기 때문에 몹시 화가 났다","mis":"K3-2-u1-X04"},{"t":"서아와 다시는 놀고 싶지 않았다","mis":"K3-2-u1-X04"},{"t":"손잡이를 새로 사야 해서 속상했다","mis":"K3-2-u1-X07"}],"explanation":["하율이의 말을 봐요.","「원래 잘 빠져」 · 「고마워」라고 했어요.","솔직하게 말한 것이 반가웠어요."],"asset":{"type":"passage","lines":["집에 가는 길에 서아는 하율이를 불러 세웠다.","“어제 내가 손잡이를 빠뜨렸어. 미안해.”","하율이가 손잡이를 꾹 끼우며 말했다.","“이거 원래 잘 빠져. 말해 줘서 고마워.”","서아는 마음이 후련했다."],"title":"이야기 「빠진 손잡이」 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#12','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C7',2,'mc','auto','「빠진 손잡이」를 친구에게 권하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X18','K3-2-u1-X02']::text[],false,'{"seq":12,"concept":"K3-2-u1-C7","difficulty":2,"kind":"mc","stem":"「빠진 손잡이」를 친구에게 권하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"잘못을 말할까 망설이는 친구에게 서아가 후련해진 마음이 힘이 될 것 같아서","correct":true},{"t":"가장 유명한 이야기라서","mis":"K3-2-u1-X18"},{"t":"줄넘기가 나와서","mis":"K3-2-u1-X02"},{"t":"가장 짧은 이야기라서","mis":"K3-2-u1-X18"}],"explanation":["권하는 까닭에는 그 친구의 일이 들어가요.","이야기와 이어질 마음을 대요.","망설이는 친구에게 권해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#13','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C8',2,'match','auto','안내의 표지어와 그 뒤에 온 중요한 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":13,"concept":"K3-2-u1-C8","difficulty":2,"kind":"match","stem":"안내의 표지어와 그 뒤에 온 중요한 내용을 알맞게 이으세요.","pairs":[{"l":"첫째","r":"아침 수업 전에 준다"},{"l":"둘째","r":"뿌리 쪽 흙에 천천히 준다"},{"l":"가장 중요한 것은","r":"흙을 눌러 보고 마른 날에만 준다"}],"mis":"K3-2-u1-X11","explanation":["표지어 뒤를 읽어요.","그 뒤에 중요한 내용이 따라와요.","표지어마다 내용을 이어요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#14','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',2,'ox','auto','「빠진 손잡이」를 간추릴 때 서아가 왜 몰래 넣어 두었는지는 빼도 돼요.',ARRAY['K3-2-u1-X14']::text[],false,'{"seq":14,"concept":"K3-2-u1-C10","difficulty":2,"kind":"ox","stem":"「빠진 손잡이」를 간추릴 때 서아가 왜 몰래 넣어 두었는지는 빼도 돼요.","answer":"X","reason_options":[{"t":"몰래 넣은 까닭(조마조마한 마음)이 빠지면 뒤의 일이 왜 일어났는지 알 수 없기 때문에","correct":true},{"t":"까닭보다 일어난 일만 남기면 되기 때문에","mis":"K3-2-u1-X14"}],"mis":"K3-2-u1-X14","explanation":["원인을 빼면 「왜?」가 남아요.","조마조마한 마음이 원인이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#15','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C11',2,'mc','auto','간추린 것이 목적에 맞았는지 따져 보는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X16','K3-2-u1-X13']::text[],false,'{"seq":15,"concept":"K3-2-u1-C11","difficulty":2,"kind":"mc","stem":"간추린 것이 목적에 맞았는지 따져 보는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"그 글을 읽는 사람이 목적대로 할 수 있는지 본다","correct":true},{"t":"글자가 가장 많은지 본다","mis":"K3-2-u1-X16"},{"t":"친구 것과 똑같은지 본다","mis":"K3-2-u1-X16"},{"t":"재미있는 말이 들어갔는지 본다","mis":"K3-2-u1-X13"}],"explanation":["목적에 맞았는지는 따질 수 있어요.","읽는 사람이 할 수 있어야 해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#16','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C12',2,'mc','auto','내 경험에 어울리는 이야기를 고른 것으로 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X18','K3-2-u1-X02']::text[],false,'{"seq":16,"concept":"K3-2-u1-C12","difficulty":2,"kind":"mc","stem":"내 경험에 어울리는 이야기를 고른 것으로 알맞은 것은 무엇인가요?","options":[{"t":"친구에게 고마운데 말을 못 했던 경험에 「반쪽 우산」을 고른다","correct":true},{"t":"가장 긴 「나중에 온 아이」를 고른다","mis":"K3-2-u1-X18"},{"t":"비 오는 날 경험에는 「반쪽 우산」만 고를 수 있다","mis":"K3-2-u1-X02"},{"t":"유명한 이야기를 아무거나 고른다","mis":"K3-2-u1-X18"}],"explanation":["고르는 기준은 마음이에요.","길이·유명함·겉의 날씨가 아니에요.","고마운 마음이 이어져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#17','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C4',3,'mc','auto','친구가 「반쪽 우산」에서 나와 다른 줄을 인상 깊다고 했을 때 알맞은 말은 무엇인가요?',ARRAY['K3-2-u1-X05']::text[],false,'{"seq":17,"concept":"K3-2-u1-C4","difficulty":3,"kind":"mc","stem":"친구가 「반쪽 우산」에서 나와 다른 줄을 인상 깊다고 했을 때 알맞은 말은 무엇인가요?","options":[{"t":"“너는 왜 그 줄이 마음에 남았어?”","correct":true},{"t":"“그 줄은 틀렸어. 내 줄이 맞아.”","mis":"K3-2-u1-X05"},{"t":"“그럼 나도 네 줄로 바꿀게.”","mis":"K3-2-u1-X05"},{"t":"“인상 깊은 줄은 선생님이 정해 주실 거야.”","mis":"K3-2-u1-X05"}],"explanation":["다른 것은 틀린 것이 아니에요.","내 생각을 지울 필요도 없어요.","까닭을 물어봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#18','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C6',3,'ox','auto','「서아는 모른 척 고개를 숙였다」만으로는 서아의 마음을 짐작할 수 없어요.',ARRAY['K3-2-u1-X04']::text[],false,'{"seq":18,"concept":"K3-2-u1-C6","difficulty":3,"kind":"ox","stem":"「서아는 모른 척 고개를 숙였다」만으로는 서아의 마음을 짐작할 수 없어요.","answer":"X","reason_options":[{"t":"고개를 숙인 행동과 그 앞의 조마조마한 마음이 근거가 되어 짐작할 수 있기 때문에","correct":true},{"t":"마음이 글에 적혀 있지 않으면 짐작하면 안 되기 때문에","mis":"K3-2-u1-X04"}],"mis":"K3-2-u1-X04","explanation":["마음은 글에 그대로 적혀 있지 않아도 돼요.","행동이 근거예요.","그래서 X예요."],"asset":{"type":"passage","lines":["체육 시간에 서아는 하율이의 줄넘기를 빌렸다.","힘껏 돌리다가 손잡이가 툭 빠졌다. 서아는 가슴이 조마조마했다.","서아는 줄넘기를 하율이 사물함에 살금살금 넣어 두었다.","다음 날 하율이가 줄넘기를 들고 고개를 갸웃했다.","서아는 모른 척 고개를 숙였다. 그날 내내 공기놀이도 재미가 없었다."],"title":"이야기 「빠진 손잡이」 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#19','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C9',3,'ox','auto','묻고 답하는 말을 들을 때 질문과 대답을 짝지어 적으면 그 표가 곧 간추린 것이 돼요.',ARRAY['K3-2-u1-X12']::text[],false,'{"seq":19,"concept":"K3-2-u1-C9","difficulty":3,"kind":"ox","stem":"묻고 답하는 말을 들을 때 질문과 대답을 짝지어 적으면 그 표가 곧 간추린 것이 돼요.","answer":"O","reason_options":[{"t":"질문마다 중요한 대답만 남아 한눈에 정리되기 때문에","correct":true},{"t":"주고받은 말을 모두 옮겨 적은 것이기 때문에","mis":"K3-2-u1-X12"}],"mis":"K3-2-u1-X12","explanation":["질문과 대답을 짝지어요.","중요한 대답만 남아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#20','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C10',3,'match','auto','이야기를 간추리는 방법과 「빠진 손잡이」에서 찾은 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":20,"concept":"K3-2-u1-C10","difficulty":3,"kind":"match","stem":"이야기를 간추리는 방법과 「빠진 손잡이」에서 찾은 것을 알맞게 이으세요.","pairs":[{"l":"인물의 특성","r":"숨기려다 결국 사실대로 말한다"},{"l":"일이 일어난 차례","r":"빠짐 → 숨김 → 불편함 → 사과"},{"l":"원인과 결과","r":"사실대로 말하니 마음이 후련해졌다"}],"mis":"K3-2-u1-X14","explanation":["인물은 어떤 아이인지예요.","차례는 일이 일어난 순서예요.","원인과 결과는 왜 · 그래서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#21','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C11',3,'ox','auto','느티나무의 「좋은 점」 칸에 「운동장 구석」을 적은 것은 바르게 적은 거예요.',ARRAY['K3-2-u1-X17']::text[],false,'{"seq":21,"concept":"K3-2-u1-C11","difficulty":3,"kind":"ox","stem":"느티나무의 「좋은 점」 칸에 「운동장 구석」을 적은 것은 바르게 적은 거예요.","answer":"X","reason_options":[{"t":"「운동장 구석」은 있는 곳이고 좋은 점은 시원한 그늘에서 쉴 수 있다는 것이기 때문에","correct":true},{"t":"느티나무에 대한 것이면 어느 칸에 적어도 되기 때문에","mis":"K3-2-u1-X17"}],"mis":"K3-2-u1-X17","explanation":["칸마다 묻는 것이 달라요.","운동장 구석은 어디인지예요.","그래서 X예요."],"asset":{"type":"passage","lines":["도서관 창가 — 저는 도서관 남쪽 창가예요.","오후가 되면 볕이 길게 들어와 아늑해요. 책을 읽다 보면 시간이 금방 가요.","느티나무 — 저는 운동장 구석에 서 있어요.","여름이면 가지가 넓게 그늘을 드리워서 아래가 시원해요. 아래에 긴 의자가 두 개 있어요.","복도 그림판 — 저는 급식실 앞 복도 벽이에요.","학년마다 만든 그림판이 줄지어 붙어 있어요. 해마다 그림이 바뀌어서 볼 때마다 달라요.","뒤뜰 텃밭 — 저는 학교 뒤뜰이에요.","학년마다 한 이랑씩 맡아 길러요. 심은 사람이 물을 주러 와야 해서 늘 누군가 와 있어요."],"title":"소개 「우리 학교 자랑거리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#22','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C14',3,'ox','auto','「탈것」이라는 묶는 이름을 알면 처음 본 「케이블카」도 탈것에 담을 수 있어요.',ARRAY['K3-2-u1-X22']::text[],false,'{"seq":22,"concept":"K3-2-u1-C14","difficulty":3,"kind":"ox","stem":"「탈것」이라는 묶는 이름을 알면 처음 본 「케이블카」도 탈것에 담을 수 있어요.","answer":"O","reason_options":[{"t":"묶는 이름을 알아 두면 새 낱말을 어디에 담을지 알 수 있기 때문에","correct":true},{"t":"묶는 이름은 이미 아는 낱말에만 쓸 수 있기 때문에","mis":"K3-2-u1-X22"}],"mis":"K3-2-u1-X22","explanation":["묶는 이름은 그릇과 같아요.","새 낱말도 담을 수 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#23','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C7',4,'mc','auto','「빠진 손잡이」와 「나중에 온 아이」를 함께 읽고 두 이야기의 인물에게 하고 싶은 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K3-2-u1-X09','K3-2-u1-X02']::text[],false,'{"seq":23,"concept":"K3-2-u1-C7","difficulty":4,"kind":"mc","stem":"「빠진 손잡이」와 「나중에 온 아이」를 함께 읽고 두 이야기의 인물에게 하고 싶은 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"“서아도 도빈이도 망설이다가 먼저 말을 꺼냈구나. 미루는 동안 마음이 무거웠던 걸 알 것 같아.”","correct":true},{"t":"“둘 다 처음부터 바로 말했어야지.”","mis":"K3-2-u1-X09"},{"t":"“둘 다 착한 아이가 되도록 노력해.”","mis":"K3-2-u1-X09"},{"t":"“두 이야기는 나오는 물건이 달라서 이어지지 않아.”","mis":"K3-2-u1-X02"}],"explanation":["두 인물 모두 망설이다 먼저 말했어요.","그 마음을 알아주는 말이에요.","탓하거나 가르치지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#24','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C11',4,'essay','teacher','「텃밭 물 주기 안내」를 간추리는 목적을 하나 정해 쓰고, 그 목적에 맞게 간추린 뒤, 왜 그것을 남겼는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K3-2-u1-C11","difficulty":4,"kind":"essay","stem":"「텃밭 물 주기 안내」를 간추리는 목적을 하나 정해 쓰고, 그 목적에 맞게 간추린 뒤, 왜 그것을 남겼는지 쓰세요.","answer_guide":{"answer":"예: 목적 — 물 당번 확인표를 만들려고. 간추린 것 — 물을 준 뒤에는 이랑 옆 기록판에 이름 적기. 까닭 — 확인표는 누가 언제 물을 주었는지 알아보려고 만드는 것이라 두 번 주는 일을 막는 기록판 이야기만 있으면 되기 때문이다.","scoring_points":["목적을 분명하게 정했는가","목적에 맞는 내용만 간추렸는가","그것을 남긴 까닭을 목적과 이어 썼는가"]},"explanation":["목적부터 정해요.","목적에 맞는 것만 남겨요.","왜 남겼는지 목적으로 설명해요."],"asset":{"type":"passage","lines":["첫째, 물은 아침 수업 전에 주세요. 한낮에는 물이 금방 말라요.","둘째, 잎이 아니라 뿌리 쪽 흙에 천천히 주세요.","셋째, 물을 준 뒤에는 이랑 옆 기록판에 이름을 적어 주세요. 두 번 주는 일을 막을 수 있어요.","음, 그러니까 가장 중요한 것은 흙을 손가락으로 눌러 보고 마른 날에만 주는 거예요."],"title":"안내 「텃밭 물 주기 안내」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_2_kor_u1_review_d#25','kor',3,2,'u1','','g3_2_kor_u1_review_d','unit_review','K3-2-u1-C13',4,'essay','teacher','「찧어」와 「빻으면」을 넣어 문장을 하나씩 만들고, 두 말이 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K3-2-u1-C13","difficulty":4,"kind":"essay","stem":"「찧어」와 「빻으면」을 넣어 문장을 하나씩 만들고, 두 말이 어떻게 소리 나는지와 쓸 때는 어떻게 쓰는지, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 「방앗간에서 쌀을 찧어 떡을 만들었다.」에서 「찧어」는 [찌어], 「콩을 빻으면 고운 가루가 된다.」에서 「빻으면」은 [빠으면]으로 소리 난다. 받침 ㅎ 뒤에 모음으로 시작하는 말이 와서 ㅎ 소리가 나지 않기 때문이다. 그래도 쓸 때는 받침 ㅎ을 그대로 살려 「찧어」, 「빻으면」으로 쓴다.","scoring_points":["두 말을 넣어 문장을 만들었는가","[찌어]·[빠으면]으로 소리 난다고 썼는가","쓸 때는 그대로 쓴다는 것과 까닭을 썼는가"]},"explanation":["모음 앞 받침 ㅎ이에요.","소리는 [찌어] · [빠으면]이에요.","글자는 그대로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
